package main

import (
	"fmt"
	"math"
	"strconv"
	"strings"
)

// ValueType represents the type of an MLR value
type ValueType int

const (
	VT_ABSENT  ValueType = iota // absent (field doesn't exist)
	VT_NULL                     // JSON null
	VT_ERROR                    // error
	VT_BOOL                     // boolean
	VT_INT                      // integer
	VT_FLOAT                    // float
	VT_STRING                   // string
	VT_ARRAY                    // array
	VT_MAP                      // map/record
)

// MLRVal is a Miller value
type MLRVal struct {
	Type    ValueType
	StrVal  string
	IntVal  int64
	FltVal  float64
	BoolVal bool
	ArrVal  []*MLRVal
	MapVal  *Mlrmap // for map/record type
}

var MV_ABSENT = &MLRVal{Type: VT_ABSENT}
var MV_NULL = &MLRVal{Type: VT_NULL}
var MV_ERROR = &MLRVal{Type: VT_ERROR}
var MV_TRUE = &MLRVal{Type: VT_BOOL, BoolVal: true}
var MV_FALSE = &MLRVal{Type: VT_BOOL, BoolVal: false}
var MV_EMPTY = &MLRVal{Type: VT_STRING, StrVal: ""}

func MvFromInt(n int64) *MLRVal { return &MLRVal{Type: VT_INT, IntVal: n} }
func MvFromFloat(f float64) *MLRVal { return &MLRVal{Type: VT_FLOAT, FltVal: f} }
func MvFromString(s string) *MLRVal { return &MLRVal{Type: VT_STRING, StrVal: s} }
func MvFromBool(b bool) *MLRVal {
	if b {
		return MV_TRUE
	}
	return MV_FALSE
}

func (v *MLRVal) IsAbsent() bool { return v.Type == VT_ABSENT }
func (v *MLRVal) IsNull() bool   { return v.Type == VT_NULL }
func (v *MLRVal) IsError() bool  { return v.Type == VT_ERROR }
func (v *MLRVal) IsBool() bool   { return v.Type == VT_BOOL }
func (v *MLRVal) IsInt() bool    { return v.Type == VT_INT }
func (v *MLRVal) IsFloat() bool  { return v.Type == VT_FLOAT }
func (v *MLRVal) IsString() bool { return v.Type == VT_STRING }
func (v *MLRVal) IsArray() bool  { return v.Type == VT_ARRAY }
func (v *MLRVal) IsMap() bool    { return v.Type == VT_MAP }
func (v *MLRVal) IsNumeric() bool { return v.Type == VT_INT || v.Type == VT_FLOAT }
func (v *MLRVal) IsPresent() bool { return v.Type != VT_ABSENT }
func (v *MLRVal) IsEmpty() bool  { return v.Type == VT_STRING && v.StrVal == "" }
func (v *MLRVal) IsNullOrAbsent() bool { return v.Type == VT_ABSENT || v.Type == VT_NULL }
func (v *MLRVal) IsEmptyMap() bool { return v.Type == VT_MAP && v.MapVal.Len() == 0 }
func (v *MLRVal) IsNonEmptyMap() bool { return v.Type == VT_MAP && v.MapVal.Len() > 0 }
func (v *MLRVal) IsNotNull() bool { return v.Type != VT_NULL && v.Type != VT_ABSENT }

func (v *MLRVal) String() string {
	switch v.Type {
	case VT_ABSENT:
		return ""
	case VT_NULL:
		return ""
	case VT_ERROR:
		return "(error)"
	case VT_BOOL:
		if v.BoolVal {
			return "true"
		}
		return "false"
	case VT_INT:
		return strconv.FormatInt(v.IntVal, 10)
	case VT_FLOAT:
		return formatFloat(v.FltVal)
	case VT_STRING:
		return v.StrVal
	case VT_ARRAY:
		return v.arrayString()
	case VT_MAP:
		return v.MapVal.String()
	}
	return ""
}

func formatFloat(f float64) string {
	if math.IsInf(f, 1) {
		return "+Inf"
	}
	if math.IsInf(f, -1) {
		return "-Inf"
	}
	if math.IsNaN(f) {
		return "NaN"
	}
	// Use strconv.FormatFloat which mimics Go's default formatting
	s := strconv.FormatFloat(f, 'g', -1, 64)
	return s
}

func (v *MLRVal) arrayString() string {
	parts := make([]string, len(v.ArrVal))
	for i, e := range v.ArrVal {
		parts[i] = e.jsonString()
	}
	return "[" + strings.Join(parts, ", ") + "]"
}

func (v *MLRVal) jsonString() string {
	switch v.Type {
	case VT_ABSENT:
		return "null"
	case VT_NULL:
		return "null"
	case VT_ERROR:
		return `"(error)"`
	case VT_BOOL:
		if v.BoolVal {
			return "true"
		}
		return "false"
	case VT_INT:
		return strconv.FormatInt(v.IntVal, 10)
	case VT_FLOAT:
		return formatFloat(v.FltVal)
	case VT_STRING:
		return jsonQuote(v.StrVal)
	case VT_ARRAY:
		return v.arrayString()
	case VT_MAP:
		return v.MapVal.String()
	}
	return "null"
}

func jsonQuote(s string) string {
	var b strings.Builder
	b.WriteByte('"')
	for _, c := range s {
		switch c {
		case '"':
			b.WriteString(`\"`)
		case '\\':
			b.WriteString(`\\`)
		case '\n':
			b.WriteString(`\n`)
		case '\r':
			b.WriteString(`\r`)
		case '\t':
			b.WriteString(`\t`)
		case '\b':
			b.WriteString(`\b`)
		case '\f':
			b.WriteString(`\f`)
		default:
			if c < 0x20 {
				fmt.Fprintf(&b, `\u%04x`, c)
			} else {
				b.WriteRune(c)
			}
		}
	}
	b.WriteByte('"')
	return b.String()
}

func (v *MLRVal) TypeName() string {
	switch v.Type {
	case VT_ABSENT:
		return "absent"
	case VT_NULL:
		return "null"
	case VT_ERROR:
		return "error"
	case VT_BOOL:
		return "bool"
	case VT_INT:
		return "int"
	case VT_FLOAT:
		return "float"
	case VT_STRING:
		return "string"
	case VT_ARRAY:
		return "array"
	case VT_MAP:
		return "map"
	}
	return "unknown"
}

// InferType tries to parse a string value as int, float, bool
func InferType(s string, opts *InferOpts) *MLRVal {
	if opts != nil && opts.NoInfer {
		return MvFromString(s)
	}
	if opts != nil && opts.InferIntAsFloat {
		// Will convert int-looking strings to float
	}

	// Check for empty
	if s == "" {
		return MV_EMPTY
	}

	// Try integer
	if i, err := strconv.ParseInt(s, 10, 64); err == nil {
		if opts != nil && opts.InferIntAsFloat {
			return MvFromFloat(float64(i))
		}
		return MvFromInt(i)
	}

	// Try octal if enabled
	if opts != nil && opts.InferOctal && len(s) >= 2 && s[0] == '0' && s[1] != 'x' && s[1] != 'X' {
		if i, err := strconv.ParseInt(s, 8, 64); err == nil {
			if opts.InferIntAsFloat {
				return MvFromFloat(float64(i))
			}
			return MvFromInt(i)
		}
	}

	// Try float
	if f, err := strconv.ParseFloat(s, 64); err == nil {
		return MvFromFloat(f)
	}

	return MvFromString(s)
}

type InferOpts struct {
	NoInfer         bool
	InferIntAsFloat bool
	InferOctal      bool
}

// Mlrmap is an ordered key-value store
type Mlrmap struct {
	keys   []string
	vals   map[string]*MLRVal
	// For dedup tracking
}

func NewMlrmap() *Mlrmap {
	return &Mlrmap{
		keys: make([]string, 0, 8),
		vals: make(map[string]*MLRVal),
	}
}

func (m *Mlrmap) Len() int { return len(m.keys) }

func (m *Mlrmap) Get(key string) *MLRVal {
	if v, ok := m.vals[key]; ok {
		return v
	}
	return MV_ABSENT
}

func (m *Mlrmap) Has(key string) bool {
	_, ok := m.vals[key]
	return ok
}

func (m *Mlrmap) Put(key string, val *MLRVal) {
	if _, exists := m.vals[key]; !exists {
		m.keys = append(m.keys, key)
	}
	m.vals[key] = val
}

func (m *Mlrmap) Remove(key string) {
	if _, exists := m.vals[key]; !exists {
		return
	}
	delete(m.vals, key)
	newKeys := make([]string, 0, len(m.keys)-1)
	for _, k := range m.keys {
		if k != key {
			newKeys = append(newKeys, k)
		}
	}
	m.keys = newKeys
}

func (m *Mlrmap) Keys() []string {
	return m.keys
}

func (m *Mlrmap) Copy() *Mlrmap {
	out := NewMlrmap()
	for _, k := range m.keys {
		v := m.vals[k]
		out.Put(k, copyVal(v))
	}
	return out
}

func (m *Mlrmap) String() string {
	var b strings.Builder
	b.WriteByte('{')
	for i, k := range m.keys {
		if i > 0 {
			b.WriteString(", ")
		}
		b.WriteString(jsonQuote(k))
		b.WriteString(": ")
		b.WriteString(m.vals[k].jsonString())
	}
	b.WriteByte('}')
	return b.String()
}

func copyVal(v *MLRVal) *MLRVal {
	if v == nil {
		return MV_ABSENT
	}
	switch v.Type {
	case VT_ARRAY:
		arr := make([]*MLRVal, len(v.ArrVal))
		for i, e := range v.ArrVal {
			arr[i] = copyVal(e)
		}
		return &MLRVal{Type: VT_ARRAY, ArrVal: arr}
	case VT_MAP:
		return &MLRVal{Type: VT_MAP, MapVal: v.MapVal.Copy()}
	default:
		// Immutable types can be shared
		return v
	}
}

// Record is the same as Mlrmap but used for stream records
type Record = Mlrmap

func NewRecord() *Record {
	return NewMlrmap()
}

// Deduplicate keys
func (m *Mlrmap) DedupKey(key string) string {
	if !m.Has(key) {
		return key
	}
	for i := 2; ; i++ {
		candidate := fmt.Sprintf("%s_%d", key, i)
		if !m.Has(candidate) {
			return candidate
		}
	}
}

// MvFromInterface creates MLRVal from a Go interface value (from JSON)
func MvFromInterface(v interface{}, opts *InferOpts) *MLRVal {
	if v == nil {
		return MV_NULL
	}
	switch val := v.(type) {
	case bool:
		return MvFromBool(val)
	case float64:
		// JSON numbers are float64; check if it's really an int
		if val == math.Trunc(val) && !math.IsInf(val, 0) && !math.IsNaN(val) {
			if val >= math.MinInt64 && val <= math.MaxInt64 {
				if opts == nil || !opts.InferIntAsFloat {
					return MvFromInt(int64(val))
				}
			}
		}
		return MvFromFloat(val)
	case string:
		return MvFromString(val)
	case []interface{}:
		arr := make([]*MLRVal, len(val))
		for i, e := range val {
			arr[i] = MvFromInterface(e, opts)
		}
		return &MLRVal{Type: VT_ARRAY, ArrVal: arr}
	case map[string]interface{}:
		// Use ordered map... but Go maps aren't ordered
		// We'll just use insertion order from JSON parse
		m := NewMlrmap()
		for k, e := range val {
			m.Put(k, MvFromInterface(e, opts))
		}
		return &MLRVal{Type: VT_MAP, MapVal: m}
	}
	return MV_NULL
}
