type Record = Mlrmap

func NewRecord() *Record {
	return NewMlrmap()
}

// Deduplicate keys
func (m *Mlrmap) DedupKey(key string) string {
	if !m.Has(key) {
		return key
	}
	for i := 2; ; i++ {
		candidate := fmt.Sprintf("%s_%d", key, i)
		if !m.Has(candidate) {
			return candidate
		}
	}
}

// MvFromInterface creates MLRVal from a Go interface value (from JSON)
func MvFromInterface(v interface{}, opts *InferOpts) *MLRVal {
	if v == nil {
		return MV_NULL
	}
	switch val := v.(type) {
	case bool:
		return MvFromBool(val)
	case float64:
		// JSON numbers are float64; check if it's really an int
		if val == math.Trunc(val) && !math.IsInf(val, 0) && !math.IsNaN(val) {
			if val >= math.MinInt64 && val <= math.MaxInt64 {
				if opts == nil || !opts.InferIntAsFloat {
					return MvFromInt(int64(val))
				}
			}
		}
		return MvFromFloat(val)
	case string:
		return MvFromString(val)
	case []interface{}:
		arr := make([]*MLRVal, len(val))
		for i, e := range val {
			arr[i] = MvFromInterface(e, opts)
		}
		return &MLRVal{Type: VT_ARRAY, ArrVal: arr}
	case map[string]interface{}:
		// Use ordered map... but Go maps aren't ordered
		// We'll just use insertion order from JSON parse
		m := NewMlrmap()
		for k, e := range val {
			m.Put(k, MvFromInterface(e, opts))
		}
		return &MLRVal{Type: VT_MAP, MapVal: m}
	}
	return MV_NULL
}
