	m.vals[newKey] = val
}

// Reorder reorders fields, optionally moving to front
func (m *Mlrmap) Reorder(fieldNames []string, putAtFront bool) {
	newKeys := make([]string, 0, len(m.keys))
	used := make(map[string]bool)

	if putAtFront {
		for _, k := range fieldNames {
			if m.Has(k) {
				newKeys = append(newKeys, k)
				used[k] = true
			}
		}
		for _, k := range m.keys {
			if !used[k] {
				newKeys = append(newKeys, k)
			}
		}
	} else {
		// Specified fields at end
		for _, k := range m.keys {
			inList := false
			for _, fn := range fieldNames {
				if k == fn {
					inList = true
					break
				}
			}
			if !inList {
				newKeys = append(newKeys, k)
			}
		}
		for _, k := range fieldNames {
			if m.Has(k) {
				newKeys = append(newKeys, k)
				used[k] = true
			}
		}
