package main

import (
	"bufio"
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

const VERSION = "6.16.0"

func main() {
	os.Exit(mainInner(os.Args[1:]))
}

func mainInner(args []string) int {
	// Handle special first-arg cases
	if len(args) == 0 {
		printMainUsage()
		return 0
	}

	// Check for subcommands
	switch args[0] {
	case "--version", "-v":
		fmt.Printf("mlr %s\n", VERSION)
		return 0
	case "--help", "-h", "-?":
		printMainUsage()
		return 0
	case "-g":
		printAllFlags()
		return 0
	case "-l":
		printVerbList()
		return 0
	case "-L":
		printVerbUsage()
		return 0
	case "-f":
		printFunctionList()
		return 0
	case "-F":
		printFunctionUsage()
		return 0
	case "-k":
		printKeywordList()
		return 0
	case "-K":
		printKeywordUsage()
		return 0
	case "help":
		return doHelp(args[1:])
	case "aux-list":
		printAuxents()
		return 0
	case "hex":
		return doHex(args[1:])
	case "lecat":
		return doLecat(args[1:])
	case "termcvt":
		return doTermcvt(args[1:])
	case "unhex":
		return doUnhex(args[1:])
	case "regtest":
		fmt.Fprintln(os.Stderr, "mlr: regtest not available in this build")
		return 1
	case "repl":
		fmt.Fprintln(os.Stderr, "mlr: repl not available in this build")
		return 1
	case "--list-color-codes":
		printColorCodes()
		return 0
	case "--list-color-names":
		printColorNames()
		return 0
	}

	// Load mlrrc
	mlrrcArgs := []string{}
	if !hasFlag(args, "--norc") {
		mlrrcArgs = loadMLRRC()
	}

	// Combine mlrrc args with command-line args
	allArgs := append(mlrrcArgs, args...)

	// Parse options
	opts, remaining, err := ParseArgs(allArgs)
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		return 1
	}
	if opts == nil {
		printMainUsage()
		return 0
	}

	// Handle -n flag
	if opts.NoInput {
		opts.From = []string{"/dev/null"}
	}

	// Process --files
	for _, ff := range opts.Files {
		lines, err := readFileLines(ff)
		if err != nil {
			fmt.Fprintf(os.Stderr, "mlr: cannot open --files file: %v\n", err)
			return 1
		}
		for _, line := range lines {
			line = strings.TrimSpace(line)
			if line != "" && !strings.HasPrefix(line, "#") {
				opts.From = append(opts.From, line)
			}
		}
	}

	if len(remaining) == 0 {
		printMainUsage()
		return 0
	}

	// Parse verbs from remaining args
	verbChain, inputFiles, err := parseVerbChain(remaining, opts)
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		return 1
	}

	// Combine input files from --from and positional args
	allInputFiles := append(opts.From, inputFiles...)

	// Run the pipeline
	return runPipeline(verbChain, allInputFiles, opts)
}

func hasFlag(args []string, flag string) bool {
	for _, a := range args {
		if a == flag {
			return true
		}
	}
	return false
}

func loadMLRRC() []string {
	mlrrc := os.Getenv("MLRRC")
	if mlrrc == "__none__" {
		return nil
	}

	var files []string
	if mlrrc != "" {
		files = []string{mlrrc}
	} else {
		home, _ := os.UserHomeDir()
		if home != "" {
			files = append(files, filepath.Join(home, ".mlrrc"))
		}
		files = append(files, ".mlrrc")
	}

	var result []string
	for _, f := range files {
		lines, err := readFileLines(f)
		if err != nil {
			continue // silently skip
		}
		for _, line := range lines {
			line = strings.TrimSpace(line)
			if line == "" || strings.HasPrefix(line, "#") {
				continue
			}
			// Add -- prefix if not present
			if !strings.HasPrefix(line, "-") {
				line = "--" + line
			}
			// Split on first space for flags with args
			parts := strings.SplitN(line, " ", 2)
			result = append(result, parts...)
		}
	}
	return result
}

func readFileLines(fname string) ([]string, error) {
	f, err := os.Open(fname)
	if err != nil {
		return nil, err
	}
	defer f.Close()

	var lines []string
	scanner := bufio.NewScanner(f)
	for scanner.Scan() {
		lines = append(lines, scanner.Text())
	}
	return lines, scanner.Err()
}

func printColorCodes() {
	for i := 0; i < 256; i++ {
		fmt.Printf("\033[38;5;%dm%3d\033[0m ", i, i)
		if (i+1)%16 == 0 {
			fmt.Println()
		}
	}
	fmt.Println()
}

func printColorNames() {
	// Color names (ANSI 256-color names)
	names := []struct{ num int; name string }{
		{0, "black"}, {1, "red"}, {2, "green"}, {3, "yellow"},
		{4, "blue"}, {5, "magenta"}, {6, "cyan"}, {7, "white"},
		{8, "bright-black"}, {9, "bright-red"}, {10, "bright-green"}, {11, "bright-yellow"},
		{12, "bright-blue"}, {13, "bright-magenta"}, {14, "bright-cyan"}, {15, "bright-white"},
		// Named 256-color values
		{160, "red3"}, {196, "red1"}, {208, "darkorange"},
		{33, "dodgerblue1"}, {46, "green1"}, {51, "cyan1"},
		{93, "purple"}, {129, "mediumorchid1"}, {171, "orchid"},
		{198, "hotpink"}, {201, "magenta1"}, {226, "yellow1"},
	}
	for _, n := range names {
		fmt.Printf("%s = %d\n", n.name, n.num)
	}
}
