package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"strings"
)

// VerbInstance is a parsed verb with its options
type VerbInstance struct {
	Name    string
	Args    []string
	Handler VerbHandler
}

// VerbHandler processes records from a channel and emits to another
type VerbHandler interface {
	// Process handles a record. Returns output records (can be nil or empty).
	// Called once per input record, plus once with nil for end-of-stream.
	Process(rec *Record, state *State) []*Record
	// Flush is called at end of all input
	Flush(state *State) []*Record
}

// State holds shared state for DSL verbs
type State struct {
	Opts      *Options
	NR        int64  // record number over all files
	FNR       int64  // record number within file
	Filename  string
	Filenum   int64
	OOSvars   *Mlrmap // out-of-stream variables @...
	LocalVars *VarStack
	Writer    RecordWriter
	// For tee/emit redirect
	OpenFiles map[string]*os.File
}

func NewState(opts *Options, writer RecordWriter) *State {
	return &State{
		Opts:      opts,
		OOSvars:   NewMlrmap(),
		LocalVars: NewVarStack(),
		Writer:    writer,
		OpenFiles: make(map[string]*os.File),
	}
}

// RecordWriter writes records to output
type RecordWriter interface {
	Write(rec *Record, state *State) error
	Done() error
}

// VerbStack holds the chain of verbs
type VerbStack []*VerbInstance

func parseVerbChain(args []string, opts *Options) (VerbStack, []string, error) {
	var chain VerbStack
	var inputFiles []string

	i := 0
	for i < len(args) {
		arg := args[i]

		// "then" separates verbs
		if arg == "then" {
			i++
			continue
		}

		// Check if it's a verb
		verbName := arg
		if !isVerbName(verbName) {
			// It's an input file
			inputFiles = append(inputFiles, args[i:]...)
			break
		}

		// Find the verb's args (until next verb or "then")
		i++
		var verbArgs []string
		for i < len(args) {
			if args[i] == "then" {
				break
			}
			// Check if next arg starts a new verb - but we need to be careful
			// because verb args might look like file names
			verbArgs = append(verbArgs, args[i])
			i++
		}

		handler, remaining, err := createVerbHandler(verbName, verbArgs, opts)
		if err != nil {
			return nil, nil, fmt.Errorf("mlr: verb %s: %v", verbName, err)
		}

		chain = append(chain, &VerbInstance{
			Name:    verbName,
			Args:    verbArgs[:len(verbArgs)-len(remaining)],
			Handler: handler,
		})

		// remaining are input files for this verb (shouldn't happen for chained verbs)
		if len(remaining) > 0 {
			// Put remaining back for file processing
			inputFiles = append(inputFiles, remaining...)
			// Reset i to skip already-processed args
			break
		}
	}

	return chain, inputFiles, nil
}

func isVerbName(s string) bool {
	for _, v := range getVerbNames() {
		if v == s {
			return true
		}
	}
	return false
}

func runPipeline(chain VerbStack, inputFiles []string, opts *Options) int {
	// Setup output writer
	writer := newWriter(opts)
	state := NewState(opts, writer)

	// Apply seed if set
	if opts.SeedSet {
		seedRandom(opts.Seed)
	}

	// Create verb handlers (already created in parseVerbChain)

	// If no input files, read stdin (unless -n)
	if len(inputFiles) == 0 && !opts.NoInput {
		inputFiles = []string{"-"}
	}

	var err error

	// Process input files
	for fileIdx, fname := range inputFiles {
		state.Filename = fname
		state.Filenum = int64(fileIdx + 1)
		state.FNR = 0

		var reader io.Reader
		if fname == "-" || fname == "" {
			reader = os.Stdin
			state.Filename = "(stdin)"
		} else {
			f, e := openInputFile(fname, opts)
			if e != nil {
				fmt.Fprintf(os.Stderr, "mlr: %v\n", e)
				return 1
			}
			defer f.Close()
			reader = f
		}

		// Create record reader for this file
		recReader := newReader(opts, reader)

		for {
			rec, rerr := recReader.Read(state)
			if rerr == io.EOF {
				break
			}
			if rerr != nil {
				fmt.Fprintf(os.Stderr, "mlr: %v\n", rerr)
				if opts.StopOnError {
					return 1
				}
				continue
			}
			if rec == nil {
				continue
			}

			state.NR++
			state.FNR++

			// Progress reporting
			if opts.NRProgressMod > 0 && state.NR%opts.NRProgressMod == 0 {
				fmt.Fprintf(os.Stderr, "File: %s Record: %d\n", state.Filename, state.NR)
			}

			// Run through verb chain
			recs := []*Record{rec}
			for _, v := range chain {
				var outRecs []*Record
				for _, r := range recs {
					out := v.Handler.Process(r, state)
					outRecs = append(outRecs, out...)
				}
				recs = outRecs
			}

			// Write output records
			for _, r := range recs {
				if werr := writer.Write(r, state); werr != nil {
					fmt.Fprintf(os.Stderr, "mlr: write error: %v\n", werr)
				}
			}
		}
	}

	// Flush all verbs (end-of-stream processing)
	var finalRecs []*Record
	for _, v := range chain {
		var outRecs []*Record
		for _, r := range finalRecs {
			out := v.Handler.Process(r, state)
			outRecs = append(outRecs, out...)
		}
		flushOut := v.Handler.Flush(state)
		outRecs = append(outRecs, flushOut...)
		finalRecs = outRecs
	}
	for _, r := range finalRecs {
		if werr := writer.Write(r, state); werr != nil {
			fmt.Fprintf(os.Stderr, "mlr: write error: %v\n", werr)
		}
	}

	// Done
	err = writer.Done()
	if err != nil {
		fmt.Fprintf(os.Stderr, "mlr: %v\n", err)
		return 1
	}

	// Close open files from tee/emit
	for _, f := range state.OpenFiles {
		f.Close()
	}

	return 0
}

func openInputFile(fname string, opts *Options) (io.ReadCloser, error) {
	// Check for prepipe
	if opts.Prepipe != "" {
		return openWithPrepipe(opts.Prepipe+" < "+fname, false)
	}
	if opts.PrepipeX != "" {
		return openWithPrepipe(opts.PrepipeX+" "+fname, false)
	}
	if opts.PrepipeGunzip {
		return openWithPrepipe("gunzip < "+fname, false)
	}
	if opts.PrepipeBZ2 {
		return openWithPrepipe("bzip2 -d < "+fname, false)
	}
	if opts.PrepipeZcat {
		return openWithPrepipe("zcat < "+fname, false)
	}
	if opts.PrepipeZstdcat {
		return openWithPrepipe("zstdcat < "+fname, false)
	}

	f, err := os.Open(fname)
	if err != nil {
		return nil, err
	}

	// Handle compression based on extension or flags
	if opts.GZIn || strings.HasSuffix(fname, ".gz") {
		return openGZIP(f)
	}
	if opts.BZ2In || strings.HasSuffix(fname, ".bz2") {
		return openBZ2(f)
	}
	if opts.ZIn || strings.HasSuffix(fname, ".z") {
		return openZlib(f)
	}
	if opts.ZstdIn || strings.HasSuffix(fname, ".zst") || strings.HasSuffix(fname, ".zstd") {
		return openZstd(f)
	}

	return f, nil
}

// RecordReader reads records from a stream
type RecordReader interface {
	Read(state *State) (*Record, error)
}

func newReader(opts *Options, r io.Reader) RecordReader {
	br := bufio.NewReader(r)
	switch opts.IFmt {
	case FORMAT_CSV, FORMAT_CSVLITE:
		return newCSVReader(br, opts)
	case FORMAT_TSV, FORMAT_TSVLITE:
		return newTSVReader(br, opts)
	case FORMAT_JSON:
		return newJSONReader(r, opts, false)
	case FORMAT_JSONL:
		return newJSONReader(r, opts, true)
	case FORMAT_PPRINT:
		return newPPPrintReader(br, opts)
	case FORMAT_XTAB:
		return newXtabReader(br, opts)
	case FORMAT_NIDX:
		return newNIDXReader(br, opts)
	case FORMAT_MARKDOWN:
		return newMarkdownReader(br, opts)
	case FORMAT_DCF:
		return newDCFReader(br, opts)
	case FORMAT_ASV:
		return newASVReader(br, opts)
	case FORMAT_USV:
		return newUSVReader(br, opts)
	case FORMAT_YAML:
		return newYAMLReader(br, opts)
	case FORMAT_GEN:
		return newGenReader(opts)
	default: // DKVP
		return newDKVPReader(br, opts)
	}
}

func newWriter(opts *Options) RecordWriter {
	bw := bufio.NewWriter(os.Stdout)
	switch opts.OFmt {
	case FORMAT_CSV, FORMAT_CSVLITE:
		return newCSVWriter(bw, opts)
	case FORMAT_TSV, FORMAT_TSVLITE:
		return newTSVWriter(bw, opts)
	case FORMAT_JSON:
		return newJSONWriter(bw, opts, true)
	case FORMAT_JSONL:
		return newJSONWriter(bw, opts, false)
	case FORMAT_PPRINT:
		return newPPPrintWriter(bw, opts)
	case FORMAT_XTAB:
		return newXtabWriter(bw, opts)
	case FORMAT_NIDX:
		return newNIDXWriter(bw, opts)
	case FORMAT_MARKDOWN:
		return newMarkdownWriter(bw, opts)
	case FORMAT_DCF:
		return newDCFWriter(bw, opts)
	case FORMAT_ASV:
		return newASVWriter(bw, opts)
	case FORMAT_USV:
		return newUSVWriter(bw, opts)
	case FORMAT_YAML:
		return newYAMLWriter(bw, opts)
	default: // DKVP
		return newDKVPWriter(bw, opts)
	}
}
