	// Called once per input record, plus once with nil for end-of-stream.
	Process(rec *Record, state *State) []*Record
	// Flush is called at end of all input
	Flush(state *State) []*Record
}

// State holds shared state for DSL verbs
type State struct {
	Opts      *Options
	NR        int64  // record number over all files
	FNR       int64  // record number within file
	Filename  string
	Filenum   int64
