func parseVerbChain(args []string, opts *Options) (VerbStack, []string, error) {
	var chain VerbStack
	var inputFiles []string

	i := 0
	for i < len(args) {
		arg := args[i]

		// "then" separates verbs
		if arg == "then" {
			i++
			continue
		}

		// Check if it's a verb
		verbName := arg
		if !isVerbName(verbName) {
			// It's an input file
			inputFiles = append(inputFiles, args[i:]...)
			break
		}

		// Find the verb's args (until next verb or "then")
		i++
		var verbArgs []string
		for i < len(args) {
			if args[i] == "then" {
				break
			}
			// Check if next arg starts a new verb - but we need to be careful
			// because verb args might look like file names
			verbArgs = append(verbArgs, args[i])
			i++
		}

		handler, remaining, err := createVerbHandler(verbName, verbArgs, opts)
		if err != nil {
			return nil, nil, fmt.Errorf("mlr: verb %s: %v", verbName, err)
		}

		chain = append(chain, &VerbInstance{
			Name:    verbName,
			Args:    verbArgs[:len(verbArgs)-len(remaining)],
			Handler: handler,
		})

		// remaining are input files for this verb (shouldn't happen for chained verbs)
		if len(remaining) > 0 {
			// Put remaining back for file processing
			inputFiles = append(inputFiles, remaining...)
			// Reset i to skip already-processed args
			break
		}
	}

	return chain, inputFiles, nil
}

