func runPipeline(chain VerbStack, inputFiles []string, opts *Options) int {
	// Setup output writer
	writer := newWriter(opts)
	state := NewState(opts, writer)

	// Apply seed if set
	if opts.SeedSet {
		seedRandom(opts.Seed)
	}

	// Create verb handlers (already created in parseVerbChain)

	// If no input files, read stdin (unless -n)
	if len(inputFiles) == 0 && !opts.NoInput {
		inputFiles = []string{"-"}
	}

	var err error

	// Process input files
	for fileIdx, fname := range inputFiles {
		state.Filename = fname
		state.Filenum = int64(fileIdx + 1)
		state.FNR = 0

		var reader io.Reader
		if fname == "-" || fname == "" {
			reader = os.Stdin
			state.Filename = "(stdin)"
		} else {
			f, e := openInputFile(fname, opts)
			if e != nil {
				fmt.Fprintf(os.Stderr, "mlr: %v\n", e)
				return 1
			}
			defer f.Close()
			reader = f
		}

		// Create record reader for this file
		recReader := newReader(opts, reader)

		for {
			rec, rerr := recReader.Read(state)
			if rerr == io.EOF {
				break
			}
			if rerr != nil {
				fmt.Fprintf(os.Stderr, "mlr: %v\n", rerr)
				if opts.StopOnError {
					return 1
				}
				continue
			}
			if rec == nil {
				continue
			}

			state.NR++
			state.FNR++

			// Progress reporting
			if opts.NRProgressMod > 0 && state.NR%opts.NRProgressMod == 0 {
				fmt.Fprintf(os.Stderr, "File: %s Record: %d\n", state.Filename, state.NR)
			}

			// Run through verb chain
			recs := []*Record{rec}
			for _, v := range chain {
				var outRecs []*Record
				for _, r := range recs {
					out := v.Handler.Process(r, state)
					outRecs = append(outRecs, out...)
				}
				recs = outRecs
			}

			// Write output records
			for _, r := range recs {
				if werr := writer.Write(r, state); werr != nil {
					fmt.Fprintf(os.Stderr, "mlr: write error: %v\n", werr)
				}
			}
		}
	}

	// Flush all verbs (end-of-stream processing)
	var finalRecs []*Record
	for _, v := range chain {
		var outRecs []*Record
		for _, r := range finalRecs {
			out := v.Handler.Process(r, state)
			outRecs = append(outRecs, out...)
		}
		flushOut := v.Handler.Flush(state)
		outRecs = append(outRecs, flushOut...)
		finalRecs = outRecs
	}
	for _, r := range finalRecs {
		if werr := writer.Write(r, state); werr != nil {
			fmt.Fprintf(os.Stderr, "mlr: write error: %v\n", werr)
		}
	}

	// Done
	err = writer.Done()
	if err != nil {
		fmt.Fprintf(os.Stderr, "mlr: %v\n", err)
		return 1
	}

	// Close open files from tee/emit
	for _, f := range state.OpenFiles {
		f.Close()
	}

	return 0
}

func openInputFile(fname string, opts *Options) (io.ReadCloser, error) {
	// Check for prepipe
	if opts.Prepipe != "" {
		return openWithPrepipe(opts.Prepipe+" < "+fname, false)
	}
	if opts.PrepipeX != "" {
		return openWithPrepipe(opts.PrepipeX+" "+fname, false)
	}
	if opts.PrepipeGunzip {
