	if err != nil {
		r.Close()
		return nil, err
	}
	return &multiCloser{gz, r}, nil
}

func openBZ2(r io.ReadCloser) (io.ReadCloser, error) {
	bz := bzip2.NewReader(r)
	return &multiCloser{io.NopCloser(bz), r}, nil
}

func openZlib(r io.ReadCloser) (io.ReadCloser, error) {
	zr, err := zlib.NewReader(r)
	if err != nil {
		r.Close()
		return nil, err
	}
	return &multiCloser{zr, r}, nil
}

func openZstd(r io.ReadCloser) (io.ReadCloser, error) {
	// Try external zstd
	cmd := exec.Command("zstd", "-d", "--stdout")
	cmd.Stdin = r
	out, err := cmd.Output()
	if err != nil {
		r.Close()
		return nil, fmt.Errorf("zstd decompression failed: %v", err)
	}
	r.Close()
	return io.NopCloser(bytesReader(out)), nil
}

func openWithPrepipe(cmdStr string, useFilename bool) (io.ReadCloser, error) {
	cmd := exec.Command("sh", "-c", cmdStr)
	cmd.Stderr = os.Stderr
	out, err := cmd.Output()
	if err != nil {
		return nil, fmt.Errorf("prepipe command failed: %v", err)
	}
	return io.NopCloser(bytesReader(out)), nil
}

type bytesReaderCloser struct {
	*io.Reader
	data []byte
	pos  int
}

func bytesReader(data []byte) io.Reader {
	return &byteSliceReader{data: data, pos: 0}
}

type byteSliceReader struct {
	data []byte
	pos  int
}

func (r *byteSliceReader) Read(p []byte) (int, error) {
	if r.pos >= len(r.data) {
		return 0, io.EOF
	}
	n := copy(p, r.data[r.pos:])
	r.pos += n
	return n, nil
}

type multiCloser struct {
	io.ReadCloser
	inner io.Closer
}

func (m *multiCloser) Close() error {
	err1 := m.ReadCloser.Close()
	err2 := m.inner.Close()
	if err1 != nil {
		return err1
	}
	return err2
}
