package main

import (
	"bufio"
	"io"
	"strings"
)

// DKVP Reader
type DKVPReader struct {
	br   *bufio.Reader
	opts *Options
	done bool
}

func newDKVPReader(br *bufio.Reader, opts *Options) *DKVPReader {
	return &DKVPReader{br: br, opts: opts}
}

func (r *DKVPReader) Read(state *State) (*Record, error) {
	if r.done {
		return nil, io.EOF
	}

	// Read comments first
	for {
		line, err := readLine(r.br)
		if err == io.EOF {
			r.done = true
			return nil, io.EOF
		}
		if err != nil {
			return nil, err
		}

		// Strip trailing CR
		line = strings.TrimRight(line, "\r")

		// Handle comments
		if r.opts.PassComments && strings.HasPrefix(line, r.opts.PassCommentsWith) {
			// print immediately
			writeComment(line, state)
			continue
		}
		if r.opts.SkipComments && strings.HasPrefix(line, r.opts.SkipCommentsWith) {
			continue
		}

		// Empty line - skip
		if line == "" {
			continue
		}

		return parseDKVP(line, r.opts), nil
	}
}

func parseDKVP(line string, opts *Options) *Record {
	rec := NewRecord()
	ifs := opts.IFS
	ips := opts.IPS

	var fields []string
	if opts.IFSRegex {
		fields = splitByRegex(line, ifs)
	} else if opts.RepIFS {
		fields = splitRepeat(line, ifs)
	} else {
		fields = splitString(line, ifs)
	}

	fieldNum := 0
	for _, field := range fields {
		fieldNum++
		var key, val string

		var idx int
		if opts.IPSRegex {
			idx = indexByRegex(field, ips)
		} else {
			idx = strings.Index(field, ips)
		}

		if idx < 0 {
			// Keyless field
			if opts.IncrKey {
				key = strings.TrimLeft(field, ips)
			} else {
				key = strings.Itoa(fieldNum)
			}
			val = field
		} else {
			key = field[:idx]
			val = field[idx+len(ips):]
		}

		mv := InferType(val, &opts.InferOpts)

		if opts.NoDedupe {
			rec.Put(key, mv)
		} else {
			actualKey := rec.DedupKey(key)
			rec.Put(actualKey, mv)
		}
	}

	return rec
}

// DKVP Writer
type DKVPWriter struct {
	bw   *bufio.Writer
	opts *Options
}

func newDKVPWriter(bw *bufio.Writer, opts *Options) *DKVPWriter {
	return &DKVPWriter{bw: bw, opts: opts}
}

func (w *DKVPWriter) Write(rec *Record, state *State) error {
	ofs := w.opts.OFS
	ops := w.opts.OPS
	ors := w.opts.ORS

	var sb strings.Builder
	first := true
	for _, k := range rec.Keys() {
		if !first {
			sb.WriteString(ofs)
		}
		first = false
		v := rec.Get(k)
		sb.WriteString(k)
		sb.WriteString(ops)
		sb.WriteString(formatValue(v, w.opts))
	}
	sb.WriteString(ors)

	_, err := w.bw.WriteString(sb.String())
	if err != nil {
		return err
	}
	return w.bw.Flush()
}

func (w *DKVPWriter) Done() error {
	return w.bw.Flush()
}

func formatValue(v *MLRVal, opts *Options) string {
	if v == nil {
		return ""
	}
	if opts != nil && opts.OFmtStr != "" {
		if v.IsFloat() {
			return fmt.Sprintf(opts.OFmtStr, v.FltVal)
		}
		if v.IsInt() && strings.Contains(opts.OFmtStr, "f") || 
		   strings.Contains(opts.OFmtStr, "e") || 
		   strings.Contains(opts.OFmtStr, "g") {
			return fmt.Sprintf(opts.OFmtStr, float64(v.IntVal))
		}
	}
	switch v.Type {
	case VT_ARRAY:
		// Auto-flatten for non-JSON formats
		if opts == nil || !opts.NoAutoFlatten {
			// Return the string representation
			return v.arrayString()
		}
		return v.arrayString()
	case VT_MAP:
		if opts == nil || !opts.NoAutoFlatten {
			return v.MapVal.String()
		}
		return v.MapVal.String()
	}
	return v.String()
}

// Helper functions
func readLine(br *bufio.Reader) (string, error) {
	line, err := br.ReadString('\n')
	if len(line) > 0 {
		// Remove trailing newline
		if line[len(line)-1] == '\n' {
			line = line[:len(line)-1]
		}
		return line, nil
	}
	return line, err
}

func splitString(s, sep string) []string {
	if sep == "" {
		// Split each character
		result := make([]string, len(s))
		for i, c := range s {
			result[i] = string(c)
		}
		return result
	}
	return strings.Split(s, sep)
}

func splitRepeat(s, sep string) []string {
	// Split on sep, ignoring empty fields
	if sep == " " || sep == "\t" {
		return strings.Fields(s)
	}
	parts := strings.Split(s, sep)
	var result []string
	for _, p := range parts {
		if p != "" {
			result = append(result, p)
		}
	}
	return result
}

func fmt_Sprintf(format string, args ...interface{}) string {
	return fmt.Sprintf(format, args...)
}

import "fmt"
import "strconv"

func strings_Itoa(n int) string {
	return strconv.Itoa(n)
}
