package main

import (
	"regexp"
	"strings"
)

var regexCache = make(map[string]*regexp.Regexp)

func getRegex(pattern string) *regexp.Regexp {
	// Handle case-insensitive flag suffix 'i'
	if re, ok := regexCache[pattern]; ok {
		return re
	}

	pat := pattern
	flags := ""
	if strings.HasSuffix(pat, "i") && len(pat) > 1 {
		// Check if it's a pattern ending with 'i' for case-insensitive
		// This is a Miller convention: regex ends with 'i' means case-insensitive
		// But we need to be careful not to treat 'i' as a regex flag in simple cases
		pat = pat[:len(pat)-1]
		flags = "(?i)"
	}

	var re *regexp.Regexp
	var err error
	if flags != "" {
		re, err = regexp.Compile(flags + pat)
	} else {
		re, err = regexp.Compile(pat)
	}
	if err != nil {
		// Return a regex that never matches
		re = regexp.MustCompile("(?!)")
	}
	regexCache[pattern] = re
	return re
}

func getRegexMiller(pattern string) (*regexp.Regexp, bool) {
	// Miller regex with optional trailing 'i' for case-insensitive
	caseInsensitive := false
	pat := pattern
	if strings.HasSuffix(pat, "i") {
		// Check if there's a quote around it - miller convention
		// Trailing 'i' means case insensitive
		caseInsensitive = true
		pat = pat[:len(pat)-1]
	}

	var re *regexp.Regexp
	var err error
	if caseInsensitive {
		re, err = regexp.Compile("(?i)" + pat)
	} else {
		re, err = regexp.Compile(pat)
	}
	if err != nil {
		return nil, false
	}
	return re, true
}

func splitByRegex(s, pattern string) []string {
	re := getRegex(pattern)
	return re.Split(s, -1)
}

func indexByRegex(s, pattern string) int {
	re := getRegex(pattern)
	loc := re.FindStringIndex(s)
	if loc == nil {
		return -1
	}
	return loc[0]
}

func regexMatch(s, pattern string) bool {
	re := getRegex(pattern)
	return re.MatchString(s)
}

func regexSub(s, pattern, replacement string) string {
	re := getRegex(pattern)
	// Handle backreferences: \1 -> ${1}
	repl := convertBackrefs(replacement)
	return re.ReplaceAllString(s, repl)
}

func regexGsub(s, pattern, replacement string) string {
	return regexSub(s, pattern, replacement)
}

func convertBackrefs(repl string) string {
	// Miller uses \1, \2 etc; Go regexp uses ${1}, ${2}
	var sb strings.Builder
	i := 0
	for i < len(repl) {
		if repl[i] == '\\' && i+1 < len(repl) {
			next := repl[i+1]
			if next >= '0' && next <= '9' {
				sb.WriteString("${")
				sb.WriteByte(next)
				sb.WriteByte('}')
				i += 2
				continue
			}
		}
		sb.WriteByte(repl[i])
		i++
	}
	return sb.String()
}
