		}

		rec := NewRecord()

		if r.opts.CSVHeaderlessInput {
			// Use numeric keys
			for i, f := range fields {
				key := strconv.Itoa(i + 1)
				rec.Put(key, InferType(f, &r.opts.InferOpts))
			}
		} else {
			// Use header keys
			for i, h := range r.header {
				var f string
				if i < len(fields) {
					f = fields[i]
				}
				// Trim leading space from values if requested
				if r.opts.CSVTrimLeadingSpace {
					f = strings.TrimSpace(f)
				}
				rec.Put(h, InferType(f, &r.opts.InferOpts))
			}
			// Handle ragged (more fields than header)
			if r.opts.AllowRaggedCSV && len(fields) > len(r.header) {
				for i := len(r.header); i < len(fields); i++ {
					key := strconv.Itoa(i + 1)
					rec.Put(key, InferType(fields[i], &r.opts.InferOpts))
				}
			}
		}

		return rec, nil
	}
}

// CSV Writer
type CSVWriter struct {
	bw      *bufio.Writer
	cw      *csv.Writer
	header  []string
	opts    *Options
	raw     bool
	isFirst bool
}

func newCSVWriter(bw *bufio.Writer, opts *Options) *CSVWriter {
	w := &CSVWriter{bw: bw, opts: opts, isFirst: true}
	w.raw = (opts.OFmt == FORMAT_CSVLITE)
	if !w.raw {
		w.cw = csv.NewWriter(bw)
		if opts.OFmt == FORMAT_TSV || opts.OFmt == FORMAT_TSVLITE {
			w.cw.Comma = '\t'
		}
	}
	return w
}

func newTSVWriter(bw *bufio.Writer, opts *Options) *CSVWriter {
	w := &CSVWriter{bw: bw, opts: opts, isFirst: true}
	w.raw = (opts.OFmt == FORMAT_TSVLITE)
	if !w.raw {
		w.cw = csv.NewWriter(bw)
		w.cw.Comma = '\t'
	}
	return w
}

func (w *CSVWriter) Write(rec *Record, state *State) error {
	keys := rec.Keys()

	if w.opts.CSVHeaderlessOutput {
		// Just write values
		vals := make([]string, len(keys))
		for i, k := range keys {
			v := rec.Get(k)
			vals[i] = formatValue(v, w.opts)
		}
		return w.writeRow(vals)
	}

	// Check if header changed (or first record)
	headerChanged := false
	if w.header == nil {
		headerChanged = true
		w.header = make([]string, len(keys))
		copy(w.header, keys)
	} else if !w.opts.NoAutoUnsparsify {
		// Check if keys match current header
		if len(keys) != len(w.header) {
			headerChanged = true
		} else {
			for i, k := range keys {
				if i >= len(w.header) || k != w.header[i] {
					headerChanged = true
					break
				}
			}
		}
		if headerChanged {
			w.header = make([]string, len(keys))
			copy(w.header, keys)
		}
	}

	if headerChanged || w.isFirst {
		w.isFirst = false
		if err := w.writeRow(w.header); err != nil {
			return err
		}
	}

	// Write values
	vals := make([]string, len(w.header))
	for i, h := range w.header {
		v := rec.Get(h)
		if v.IsAbsent() {
			vals[i] = ""
		} else {
			vals[i] = formatValue(v, w.opts)
		}
	}

	return w.writeRow(vals)
}

func (w *CSVWriter) writeRow(fields []string) error {
	if w.raw {
		ofs := w.opts.OFS
		ors := w.opts.ORS
		if w.opts.OFmt == FORMAT_TSV || w.opts.OFmt == FORMAT_TSVLITE {
			ofs = "\t"
		}
		line := strings.Join(fields, ofs) + ors
		_, err := w.bw.WriteString(line)
		if err != nil {
			return err
		}
		return w.bw.Flush()
	}

	if w.opts.QuoteAll {
		// Force quoting all fields
		var sb strings.Builder
		sep := ","
		if w.opts.OFmt == FORMAT_TSV || w.opts.OFmt == FORMAT_TSVLITE {
			sep = "\t"
		}
		if w.opts.OFS != "," && w.opts.OFS != "\t" {
			sep = w.opts.OFS
		}
		for i, f := range fields {
			if i > 0 {
				sb.WriteString(sep)
			}
			sb.WriteByte('"')
			sb.WriteString(strings.ReplaceAll(f, `"`, `""`))
			sb.WriteByte('"')
		}
		sb.WriteString(w.opts.ORS)
		_, err := w.bw.WriteString(sb.String())
		if err != nil {
			return err
		}
		return w.bw.Flush()
	}

	err := w.cw.Write(fields)
	if err != nil {
		return err
	}
	w.cw.Flush()
	return w.cw.Error()
}

func (w *CSVWriter) Done() error {
	if w.cw != nil {
		w.cw.Flush()
		return w.cw.Error()
	}
	return w.bw.Flush()
}
