cat > mlr-impl/json_io.go << 'GOEOF'
package main

import (
	"bufio"
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"strings"
)

// JSON Reader
type JSONReader struct {
	dec    *json.Decoder
	opts   *Options
	buf    []*Record
	isJSONL bool
	done   bool
	r      io.Reader
	br     *bufio.Reader
}

func newJSONReader(r io.Reader, opts *Options, isJSONL bool) *JSONReader {
	reader := &JSONReader{
		opts:    opts,
		isJSONL: isJSONL,
		r:       r,
	}
	if isJSONL {
		reader.br = bufio.NewReader(r)
	} else {
		reader.dec = json.NewDecoder(r)
	}
	return reader
}

func (r *JSONReader) Read(state *State) (*Record, error) {
	if r.done {
		return nil, io.EOF
	}

	// Return from buffer first
	if len(r.buf) > 0 {
		rec := r.buf[0]
		r.buf = r.buf[1:]
		return rec, nil
	}

	if r.isJSONL {
		// JSON Lines: one JSON object per line
		for {
			line, err := r.br.ReadString('\n')
			line = strings.TrimRight(line, "\r\n")
			if line == "" {
				if err == io.EOF {
					r.done = true
					return nil, io.EOF
				}
				if err != nil {
					return nil, err
				}
				continue
			}

			// Handle comments
			if r.opts.PassComments && r.opts.PassCommentsWith != "" && strings.HasPrefix(line, r.opts.PassCommentsWith) {
				writeComment(line, state)
				continue
			}
			if r.opts.SkipComments && r.opts.SkipCommentsWith != "" && strings.HasPrefix(line, r.opts.SkipCommentsWith) {
				continue
			}

			rec, jerr := parseJSONRecord(line, r.opts)
			if jerr != nil {
				return nil, fmt.Errorf("mlr: %v", jerr)
			}

			if err == io.EOF {
				// This line was the last
			}
			return rec, nil
		}
	} else {
		// Full JSON: could be array or object
		// Try to read next token
		tok, err := r.dec.Token()
		if err == io.EOF {
			r.done = true
			return nil, io.EOF
		}
		if err != nil {
			return nil, fmt.Errorf("mlr: invalid character '%v' looking for beginning of value", err)
		}

		switch t := tok.(type) {
		case json.Delim:
			if t == '[' {
				// Array of objects - read until ']'
				for r.dec.More() {
					var raw json.RawMessage
					if err := r.dec.Decode(&raw); err != nil {
						return nil, fmt.Errorf("mlr: JSON decode error: %v", err)
					}
					rec, jerr := parseJSONRecord(string(raw), r.opts)
					if jerr != nil {
						return nil, jerr
					}
					r.buf = append(r.buf, rec)
				}
				// Read closing ]
				r.dec.Token()
				if len(r.buf) > 0 {
					rec := r.buf[0]
					r.buf = r.buf[1:]
					return rec, nil
				}
				return nil, io.EOF
			} else if t == '{' {
				// Single object - read it back
				// We need to reconstruct the object
				rawBytes, rerr := readJSONObject(r.dec)
				if rerr != nil {
					return nil, rerr
				}
				rec, jerr := parseJSONRecord("{"+string(rawBytes)+"}", r.opts)
				if jerr != nil {
					return nil, jerr
				}
				return rec, nil
			}
		}

		// Try to decode as a raw message
		r.dec = json.NewDecoder(r.r)
		var raw json.RawMessage
		if err := r.dec.Decode(&raw); err != nil {
			r.done = true
			return nil, io.EOF
		}
		rec, jerr := parseJSONRecord(string(raw), r.opts)
		if jerr != nil {
			return nil, jerr
		}
		return rec, nil
	}
}

func readJSONObject(dec *json.Decoder) ([]byte, error) {
	// We already read the '{', now read until '}'
	var buf bytes.Buffer
	depth := 1
	for depth > 0 {
		tok, err := dec.Token()
		if err != nil {
			return nil, err
		}
		switch t := tok.(type) {
		case json.Delim:
			if t == '{' || t == '[' {
				depth++
				buf.WriteString(string(t))
			} else if t == '}' || t == ']' {
				depth--
				buf.WriteString(string(t))
			}
		case string:
			b, _ := json.Marshal(t)
			buf.Write(b)
		case float64:
			fmt.Fprintf(&buf, "%v", t)
		case bool:
			if t {
				buf.WriteString("true")
			} else {
				buf.WriteString("false")
			}
		case nil:
			buf.WriteString("null")
		}
	}
	return buf.Bytes(), nil
}

func parseJSONRecord(s string, opts *Options) (*Record, error) {
	// Parse JSON string into a Record
	var raw interface{}
	if err := json.Unmarshal([]byte(s), &raw); err != nil {
		return nil, fmt.Errorf("JSON parse error: %v", err)
	}

	switch v := raw.(type) {
	case map[string]interface{}:
		// Parse with ordering from JSON
		rec := NewRecord()
		// We need ordered keys - re-parse with ordered decoder
		dec := json.NewDecoder(strings.NewReader(s))
		dec.UseNumber()
		parseJSONObjectOrdered(dec, rec, opts)
		return rec, nil
	case []interface{}:
		// Array - treat as indexed record
		rec := NewRecord()
		for i, elem := range v {
			key := fmt.Sprintf("%d", i+1)
			rec.Put(key, MvFromInterface(elem, &opts.InferOpts))
		}
		return rec, nil
	default:
		return nil, fmt.Errorf("expected JSON object or array, got %T", raw)
	}
}

func parseJSONObjectOrdered(dec *json.Decoder, rec *Record, opts *Options) error {
	// Read {
	tok, err := dec.Token()
	if err != nil {
		return err
	}
	if d, ok := tok.(json.Delim); !ok || d != '{' {
		return fmt.Errorf("expected {")
	}

	for dec.More() {
		// Read key
		keyTok, err := dec.Token()
		if err != nil {
			return err
		}
		key, ok := keyTok.(string)
		if !ok {
			return fmt.Errorf("expected string key")
		}

		// Read value
		val, err := decodeJSONValue(dec, opts)
		if err != nil {
			return err
		}

		if opts.NoDedupe {
			rec.Put(key, val)
		} else {
			actualKey := rec.DedupKey(key)
			rec.Put(actualKey, val)
		}
	}

	// Read }
	dec.Token()
	return nil
}

func decodeJSONValue(dec *json.Decoder, opts *Options) (*MLRVal, error) {
	tok, err := dec.Token()
	if err != nil {
		return nil, err
	}

	switch t := tok.(type) {
	case json.Delim:
		if t == '{' {
			// Nested map
			subRec := NewMlrmap()
			for dec.More() {
				keyTok, err := dec.Token()
				if err != nil {
					return nil, err
				}
				key, ok := keyTok.(string)
				if !ok {
					return nil, fmt.Errorf("expected string key")
				}
				val, err := decodeJSONValue(dec, opts)
				if err != nil {
					return nil, err
				}
				subRec.Put(key, val)
			}
			dec.Token() // read }
			return &MLRVal{Type: VT_MAP, MapVal: subRec}, nil
		} else if t == '[' {
			// Array
			var arr []*MLRVal
			for dec.More() {
				val, err := decodeJSONValue(dec, opts)
				if err != nil {
					return nil, err
				}
				arr = append(arr, val)
			}
			dec.Token() // read ]
			return &MLRVal{Type: VT_ARRAY, ArrVal: arr}, nil
		}
	case json.Number:
		// Check if integer
		s := t.String()
		if !strings.Contains(s, ".") && !strings.Contains(s, "e") && !strings.Contains(s, "E") {
			if i, err := t.Int64(); err == nil {
				if opts.InferOpts.InferIntAsFloat {
					return MvFromFloat(float64(i)), nil
				}
				return MvFromInt(i), nil
			}
		}
		f, err := t.Float64()
		if err != nil {
			return MvFromString(s), nil
		}
		return MvFromFloat(f), nil
	case string:
		return MvFromString(t), nil
	case bool:
		return MvFromBool(t), nil
	case nil:
		return MV_NULL, nil
	}

	return MV_NULL, nil
}

// JSON Writer
type JSONWriter struct {
	bw        *bufio.Writer
	opts      *Options
	isArray   bool
	count     int
	needComma bool
}

func newJSONWriter(bw *bufio.Writer, opts *Options, isArray bool) *JSONWriter {
	return &JSONWriter{
		bw:      bw,
		opts:    opts,
		isArray: isArray,
	}
}

func (w *JSONWriter) Write(rec *Record, state *State) error {
	if w.isArray && w.opts.JListWrap {
		if w.count == 0 {
