	}
}

func readJSONObject(dec *json.Decoder) ([]byte, error) {
	// We already read the '{', now read until '}'
	var buf bytes.Buffer
	depth := 1
	for depth > 0 {
		tok, err := dec.Token()
		if err != nil {
			return nil, err
		}
		switch t := tok.(type) {
		case json.Delim:
			if t == '{' || t == '[' {
				depth++
				buf.WriteString(string(t))
			} else if t == '}' || t == ']' {
				depth--
				buf.WriteString(string(t))
			}
		case string:
			b, _ := json.Marshal(t)
			buf.Write(b)
		case float64:
			fmt.Fprintf(&buf, "%v", t)
		case bool:
			if t {
				buf.WriteString("true")
			} else {
				buf.WriteString("false")
			}
		case nil:
			buf.WriteString("null")
		}
	}
	return buf.Bytes(), nil
}

func parseJSONRecord(s string, opts *Options) (*Record, error) {
	// Parse JSON string into a Record
	var raw interface{}
	if err := json.Unmarshal([]byte(s), &raw); err != nil {
		return nil, fmt.Errorf("JSON parse error: %v", err)
	}

	switch v := raw.(type) {
	case map[string]interface{}:
		// Parse with ordering from JSON
		rec := NewRecord()
		// We need ordered keys - re-parse with ordered decoder
		dec := json.NewDecoder(strings.NewReader(s))
		dec.UseNumber()
		parseJSONObjectOrdered(dec, rec, opts)
		return rec, nil
	case []interface{}:
		// Array - treat as indexed record
		rec := NewRecord()
		for i, elem := range v {
			key := fmt.Sprintf("%d", i+1)
			rec.Put(key, MvFromInterface(elem, &opts.InferOpts))
		}
		return rec, nil
	default:
		return nil, fmt.Errorf("expected JSON object or array, got %T", raw)
	}
}

func parseJSONObjectOrdered(dec *json.Decoder, rec *Record, opts *Options) error {
	// Read {
	tok, err := dec.Token()
	if err != nil {
		return err
	}
	if d, ok := tok.(json.Delim); !ok || d != '{' {
		return fmt.Errorf("expected {")
	}

	for dec.More() {
		// Read key
		keyTok, err := dec.Token()
		if err != nil {
			return err
		}
		key, ok := keyTok.(string)
		if !ok {
			return fmt.Errorf("expected string key")
		}

		// Read value
		val, err := decodeJSONValue(dec, opts)
		if err != nil {
			return err
		}

		if opts.NoDedupe {
			rec.Put(key, val)
		} else {
			actualKey := rec.DedupKey(key)
			rec.Put(actualKey, val)
		}
	}

	// Read }
	dec.Token()
	return nil
}

func decodeJSONValue(dec *json.Decoder, opts *Options) (*MLRVal, error) {
	tok, err := dec.Token()
	if err != nil {
		return nil, err
	}

	switch t := tok.(type) {
	case json.Delim:
		if t == '{' {
			// Nested map
			subRec := NewMlrmap()
			for dec.More() {
				keyTok, err := dec.Token()
				if err != nil {
					return nil, err
				}
				key, ok := keyTok.(string)
				if !ok {
					return nil, fmt.Errorf("expected string key")
				}
				val, err := decodeJSONValue(dec, opts)
				if err != nil {
					return nil, err
				}
				subRec.Put(key, val)
			}
			dec.Token() // read }
			return &MLRVal{Type: VT_MAP, MapVal: subRec}, nil
		} else if t == '[' {
			// Array
			var arr []*MLRVal
			for dec.More() {
				val, err := decodeJSONValue(dec, opts)
				if err != nil {
					return nil, err
				}
				arr = append(arr, val)
			}
			dec.Token() // read ]
			return &MLRVal{Type: VT_ARRAY, ArrVal: arr}, nil
		}
	case json.Number:
		// Check if integer
		s := t.String()
		if !strings.Contains(s, ".") && !strings.Contains(s, "e") && !strings.Contains(s, "E") {
			if i, err := t.Int64(); err == nil {
				if opts.InferOpts.InferIntAsFloat {
					return MvFromFloat(float64(i)), nil
				}
				return MvFromInt(i), nil
			}
		}
		f, err := t.Float64()
		if err != nil {
			return MvFromString(s), nil
		}
		return MvFromFloat(f), nil
	case string:
		return MvFromString(t), nil
	case bool:
		return MvFromBool(t), nil
	case nil:
		return MV_NULL, nil
	}

	return MV_NULL, nil
}

// JSON Writer
type JSONWriter struct {
	bw        *bufio.Writer
	opts      *Options
	isArray   bool
	count     int
	needComma bool
}

func newJSONWriter(bw *bufio.Writer, opts *Options, isArray bool) *JSONWriter {
	return &JSONWriter{
		bw:      bw,
		opts:    opts,
		isArray: isArray,
	}
}

func (w *JSONWriter) Write(rec *Record, state *State) error {
	if w.isArray && w.opts.JListWrap {
		if w.count == 0 {
			w.bw.WriteString("[\n")
		} else {
			w.bw.WriteString(",\n")
		}
	}
	w.count++

	var err error
	if w.opts.JVStack {
		err = w.writeRecordMultiline(rec)
	} else {
		err = w.writeRecordOneLine(rec)
	}
	if err != nil {
		return err
	}

	if !w.isArray || !w.opts.JListWrap {
		w.bw.WriteString("\n")
	}

	return w.bw.Flush()
}

func (w *JSONWriter) writeRecordMultiline(rec *Record) error {
	w.bw.WriteString("{\n")
	keys := rec.Keys()
	for i, k := range keys {
		v := rec.Get(k)
		w.bw.WriteString("  ")
		w.bw.WriteString(jsonQuote(k))
		w.bw.WriteString(": ")
		w.bw.WriteString(w.formatJSONValue(v, "  "))
		if i < len(keys)-1 {
			w.bw.WriteString(",")
		}
		w.bw.WriteString("\n")
	}
	w.bw.WriteString("}")
	return nil
}

func (w *JSONWriter) writeRecordOneLine(rec *Record) error {
	w.bw.WriteString("{")
	keys := rec.Keys()
	for i, k := range keys {
		if i > 0 {
			w.bw.WriteString(", ")
		}
		v := rec.Get(k)
		w.bw.WriteString(jsonQuote(k))
		w.bw.WriteString(": ")
		w.bw.WriteString(w.formatJSONValue(v, ""))
	}
	w.bw.WriteString("}")
	return nil
}

func (w *JSONWriter) formatJSONValue(v *MLRVal, indent string) string {
	if v == nil {
		return "null"
	}

	switch v.Type {
	case VT_ABSENT, VT_NULL:
		return "null"
	case VT_ERROR:
		return `"(error)"`
	case VT_BOOL:
		if v.BoolVal {
			return "true"
		}
		return "false"
	case VT_INT:
		if w.opts.JVQuoteAll {
			return jsonQuote(v.String())
		}
		return v.String()
	case VT_FLOAT:
		if w.opts.JVQuoteAll {
			return jsonQuote(formatValue(v, w.opts))
		}
		s := formatValue(v, w.opts)
		return s
	case VT_STRING:
		if w.opts.JVQuoteAll {
			return jsonQuote(v.StrVal)
		}
		return jsonQuote(v.StrVal)
	case VT_ARRAY:
		if w.opts.JVStack && indent != "" {
			return w.formatJSONArray(v, indent)
		}
		return w.formatJSONArrayOneLine(v)
	case VT_MAP:
		if w.opts.JVStack && indent != "" {
			return w.formatJSONMap(v.MapVal, indent)
		}
		return w.formatJSONMapOneLine(v.MapVal)
	}
	return "null"
}

func (w *JSONWriter) formatJSONArray(v *MLRVal, indent string) string {
	if len(v.ArrVal) == 0 {
		return "[]"
	}
	var sb strings.Builder
	sb.WriteString("[\n")
	for i, e := range v.ArrVal {
		sb.WriteString(indent + "  ")
		sb.WriteString(w.formatJSONValue(e, indent+"  "))
		if i < len(v.ArrVal)-1 {
			sb.WriteString(",")
		}
		sb.WriteString("\n")
	}
	sb.WriteString(indent + "]")
	return sb.String()
}

func (w *JSONWriter) formatJSONArrayOneLine(v *MLRVal) string {
	var sb strings.Builder
	sb.WriteString("[")
	for i, e := range v.ArrVal {
		if i > 0 {
			sb.WriteString(", ")
		}
		sb.WriteString(w.formatJSONValue(e, ""))
	}
	sb.WriteString("]")
	return sb.String()
}

func (w *JSONWriter) formatJSONMap(m *Mlrmap, indent string) string {
	var sb strings.Builder
	sb.WriteString("{\n")
	keys := m.Keys()
	for i, k := range keys {
		v := m.Get(k)
		sb.WriteString(indent + "  ")
		sb.WriteString(jsonQuote(k))
		sb.WriteString(": ")
		sb.WriteString(w.formatJSONValue(v, indent+"  "))
		if i < len(keys)-1 {
			sb.WriteString(",")
		}
		sb.WriteString("\n")
	}
	sb.WriteString(indent + "}")
	return sb.String()
}

func (w *JSONWriter) formatJSONMapOneLine(m *Mlrmap) string {
	var sb strings.Builder
	sb.WriteString("{")
	keys := m.Keys()
	for i, k := range keys {
		if i > 0 {
			sb.WriteString(", ")
		}
		v := m.Get(k)
		sb.WriteString(jsonQuote(k))
		sb.WriteString(": ")
		sb.WriteString(w.formatJSONValue(v, ""))
	}
	sb.WriteString("}")
	return sb.String()
}

func (w *JSONWriter) Done() error {
	if w.isArray && w.opts.JListWrap && w.count > 0 {
		w.bw.WriteString("]\n")
	} else if w.isArray && w.opts.JListWrap && w.count == 0 {
		w.bw.WriteString("[]\n")
	}
	return w.bw.Flush()
}
