// PPRINT Writer
type PPPrintWriter struct {
	bw      *bufio.Writer
	opts    *Options
	records []*Record
	header  []string
	colWidths map[string]int
}

func newPPPrintWriter(bw *bufio.Writer, opts *Options) *PPPrintWriter {
	return &PPPrintWriter{
		bw:   bw,
		opts: opts,
		colWidths: make(map[string]int),
	}
}

func (w *PPPrintWriter) Write(rec *Record, state *State) error {
	w.records = append(w.records, rec.Copy())

	// Update column widths
	for _, k := range rec.Keys() {
		kLen := utf8.RuneCountInString(k)
		if kLen > w.colWidths[k] {
			w.colWidths[k] = kLen
		}
		v := rec.Get(k)
		vStr := formatValue(v, w.opts)
		vLen := utf8.RuneCountInString(vStr)
		if vLen > w.colWidths[k] {
			w.colWidths[k] = vLen
		}
	}

	// Update header (union of all keys seen)
	for _, k := range rec.Keys() {
		found := false
		for _, h := range w.header {
			if h == k {
				found = true
				break
			}
		}
		if !found {
			w.header = append(w.header, k)
		}
	}

	return nil
}

func (w *PPPrintWriter) Done() error {
	if len(w.records) == 0 {
		return w.bw.Flush()
	}

	// Compute final column widths
	for _, k := range w.header {
		kLen := utf8.RuneCountInString(k)
		if kLen > w.colWidths[k] {
			w.colWidths[k] = kLen
		}
	}

	ofs := w.opts.OFS
	if ofs == "" {
		ofs = " "
	}

	if w.opts.Barred {
		// Print with borders
		var sb strings.Builder
		// Top border
		sb.WriteString("+")
		for _, h := range w.header {
			w := w.colWidths[h]
			sb.WriteString("-" + strings.Repeat("-", w) + "-+")
		}
		sb.WriteString("\n")
		w.bw.WriteString(sb.String())
		sb.Reset()

		// Header
		sb.WriteString("|")
		for _, h := range w.header {
			width := w.colWidths[h]
			sb.WriteString(" " + padRight(h, width, " ") + " |")
		}
		sb.WriteString("\n")
		w.bw.WriteString(sb.String())
		sb.Reset()

		// Header/data separator
		sb.WriteString("+")
		for _, h := range w.header {
			width := w.colWidths[h]
			sb.WriteString("-" + strings.Repeat("-", width) + "-+")
		}
		sb.WriteString("\n")
		w.bw.WriteString(sb.String())
		sb.Reset()

		// Data rows
		for _, rec := range w.records {
			sb.WriteString("|")
			for _, h := range w.header {
				width := w.colWidths[h]
				v := rec.Get(h)
				var vStr string
				if v.IsAbsent() {
					vStr = ""
				} else {
					vStr = formatValue(v, w.opts)
				}
				if w.opts.PPRightJust {
					sb.WriteString(" " + padLeft(vStr, width, " ") + " |")
				} else {
					sb.WriteString(" " + padRight(vStr, width, " ") + " |")
				}
			}
			sb.WriteString("\n")
			w.bw.WriteString(sb.String())
			sb.Reset()
		}

		// Bottom border
		sb.WriteString("+")
		for _, h := range w.header {
			width := w.colWidths[h]
			sb.WriteString("-" + strings.Repeat("-", width) + "-+")
		}
		sb.WriteString("\n")
		w.bw.WriteString(sb.String())
	} else {
		// Print header
		var sb strings.Builder
		for i, h := range w.header {
			if i > 0 {
				sb.WriteString(ofs)
			}
			if w.opts.PPRightJust {
				sb.WriteString(padLeft(h, w.colWidths[h], " "))
			} else {
				sb.WriteString(padRight(h, w.colWidths[h], " "))
			}
		}
		sb.WriteString(w.opts.ORS)
		w.bw.WriteString(sb.String())
		sb.Reset()

		// Print data rows
		for _, rec := range w.records {
			for i, h := range w.header {
				if i > 0 {
					sb.WriteString(ofs)
				}
				v := rec.Get(h)
				var vStr string
				if v.IsAbsent() {
					vStr = ""
				} else {
					vStr = formatValue(v, w.opts)
				}
				if w.opts.PPRightJust {
					sb.WriteString(padLeft(vStr, w.colWidths[h], " "))
				} else {
					if i == len(w.header)-1 {
						// Last field: don't pad
						sb.WriteString(vStr)
					} else {
						sb.WriteString(padRight(vStr, w.colWidths[h], " "))
					}
				}
			}
			sb.WriteString(w.opts.ORS)
			w.bw.WriteString(sb.String())
			sb.Reset()
		}
	}

	return w.bw.Flush()
}

func padRight(s string, width int, padChar string) string {
	l := utf8.RuneCountInString(s)
	if l >= width {
		return s
	}
	return s + strings.Repeat(padChar, width-l)
}

func padLeft(s string, width int, padChar string) string {
	l := utf8.RuneCountInString(s)
	if l >= width {
		return s
	}
	return strings.Repeat(padChar, width-l) + s
}

// XTAB Reader
type XtabReader struct {
	br   *bufio.Reader
	opts *Options
	done bool
}

func newXtabReader(br *bufio.Reader, opts *Options) *XtabReader {
	return &XtabReader{br: br, opts: opts}
}

func (r *XtabReader) Read(state *State) (*Record, error) {
	if r.done {
		return nil, io.EOF
	}

	rec := NewRecord()
	emptyLineCount := 0
	hasData := false

	for {
		line, err := readLine(r.br)
		if err == io.EOF && line == "" {
			if hasData {
				r.done = true
				return rec, nil
			}
			return nil, io.EOF
		}
		if err != nil && line == "" {
			if hasData {
				return rec, nil
			}
			return nil, err
		}

		line = strings.TrimRight(line, "\r")

		if line == "" {
			emptyLineCount++
			if emptyLineCount >= 1 && hasData {
				return rec, nil
			}
			continue
		}
		emptyLineCount = 0

		// Handle comments
		if r.opts.PassComments && r.opts.PassCommentsWith != "" && strings.HasPrefix(line, r.opts.PassCommentsWith) {
			writeComment(line, state)
			continue
		}
		if r.opts.SkipComments && r.opts.SkipCommentsWith != "" && strings.HasPrefix(line, r.opts.SkipCommentsWith) {
			continue
		}

		hasData = true

		// Parse "key   value"
		ips := r.opts.IPS
		var key, val string

		if r.opts.IPSRegex {
			idx := indexByRegex(line, ips)
			if idx < 0 {
				key = line
				val = ""
			} else {
				key = line[:idx]
				val = line[idx+1:]
			}
		} else {
			// Default: split on first occurrence of IPS (which is " ")
			// But we need to handle multiple spaces for alignment
			parts := strings.SplitN(line, ips, 2)
			if len(parts) == 2 {
				key = strings.TrimRight(parts[0], " ")
				val = strings.TrimLeft(parts[1], " ")
			} else {
				key = line
				val = ""
			}
		}

		rec.Put(key, InferType(val, &r.opts.InferOpts))
	}
}

// XTAB Writer
type XtabWriter struct {
	bw   *bufio.Writer
	opts *Options
	first bool
}

func newXtabWriter(bw *bufio.Writer, opts *Options) *XtabWriter {
	return &XtabWriter{bw: bw, opts: opts, first: true}
}

func (w *XtabWriter) Write(rec *Record, state *State) error {
	if !w.first {
		w.bw.WriteString(w.opts.ORS)
	}
	w.first = false

	ops := w.opts.OPS
	if ops == "" {
		ops = " "
	}

	keys := rec.Keys()

	// Find max key length for alignment
	maxKeyLen := 0
	if !strings.Contains(ops, "  ") || len(ops) == 1 {
		for _, k := range keys {
			l := utf8.RuneCountInString(k)
			if l > maxKeyLen {
				maxKeyLen = l
			}
		}
	}

	for _, k := range keys {
		v := rec.Get(k)
		vStr := formatValue(v, w.opts)

		if maxKeyLen > 0 {
			if w.opts.XtabRightJust {
				w.bw.WriteString(padLeft(k, maxKeyLen, " ") + ops + vStr + "\n")
			} else {
				w.bw.WriteString(padRight(k, maxKeyLen, " ") + ops + vStr + "\n")
			}
		} else {
			w.bw.WriteString(k + ops + vStr + "\n")
		}
	}

	return w.bw.Flush()
}

func (w *XtabWriter) Done() error {
	return w.bw.Flush()
}

