	return w.bw.Flush()
}

// Markdown Reader
type MarkdownReader struct {
	br     *bufio.Reader
	opts   *Options
	header []string
	done   bool
}

func newMarkdownReader(br *bufio.Reader, opts *Options) *MarkdownReader {
	return &MarkdownReader{br: br, opts: opts}
}

func (r *MarkdownReader) Read(state *State) (*Record, error) {
	if r.done {
		return nil, io.EOF
	}

	for {
		line, err := readLine(r.br)
		if err == io.EOF && line == "" {
			r.done = true
			return nil, io.EOF
		}
		if err != nil && line == "" {
			return nil, err
		}
		line = strings.TrimRight(line, "\r")

		if line == "" {
			continue
		}

		// Parse markdown table row: | a | b | c |
		if !strings.HasPrefix(line, "|") {
			continue
		}

		// Check if separator row: | --- | --- |
		if strings.Contains(line, "---") {
			continue
		}

		parts := strings.Split(line, "|")
		// Remove first and last empty parts
		if len(parts) > 2 {
			parts = parts[1 : len(parts)-1]
		}

		var fields []string
		for _, p := range parts {
			fields = append(fields, strings.TrimSpace(p))
		}

		if r.header == nil {
			r.header = fields
			continue
		}

		rec := NewRecord()
		for i, h := range r.header {
			var val string
			if i < len(fields) {
				val = fields[i]
			}
			rec.Put(h, InferType(val, &r.opts.InferOpts))
		}
		return rec, nil
	}
}

// Markdown Writer
type MarkdownWriter struct {
	bw      *bufio.Writer
	opts    *Options
	records []*Record
	header  []string
	colWidths map[string]int
}

func newMarkdownWriter(bw *bufio.Writer, opts *Options) *MarkdownWriter {
	return &MarkdownWriter{
		bw:        bw,
		opts:      opts,
		colWidths: make(map[string]int),
	}
}

func (w *MarkdownWriter) Write(rec *Record, state *State) error {
	w.records = append(w.records, rec.Copy())

	for _, k := range rec.Keys() {
		kLen := utf8.RuneCountInString(k)
		if kLen > w.colWidths[k] {
			w.colWidths[k] = kLen
		}
		v := rec.Get(k)
		vStr := formatValue(v, w.opts)
		vLen := utf8.RuneCountInString(vStr)
		if vLen > w.colWidths[k] {
			w.colWidths[k] = vLen
		}

		// Add to header if not already
		found := false
		for _, h := range w.header {
			if h == k {
				found = true
				break
			}
		}
		if !found {
			w.header = append(w.header, k)
		}
	}

	return nil
}

func (w *MarkdownWriter) Done() error {
	if len(w.records) == 0 {
		return w.bw.Flush()
	}

	// Ensure minimum width of 3 for --- separator
	for k, v := range w.colWidths {
		if v < 3 {
			w.colWidths[k] = 3
		}
	}

	// Header row
	var sb strings.Builder
	sb.WriteString("| ")
	for i, h := range w.header {
		if i > 0 {
			sb.WriteString(" | ")
		}
		// For markdown, we don't pad headers but pad the content
		sb.WriteString(h)
	}
	sb.WriteString(" |\n")
	w.bw.WriteString(sb.String())
	sb.Reset()

	// Separator row
	sb.WriteString("| ")
	for i, h := range w.header {
		if i > 0 {
			sb.WriteString(" | ")
		}
		width := w.colWidths[h]
		if width < 3 {
			width = 3
		}
		sb.WriteString(strings.Repeat("-", width))
	}
	sb.WriteString(" |\n")
	w.bw.WriteString(sb.String())
	sb.Reset()

	// Data rows
	for _, rec := range w.records {
		sb.WriteString("| ")
		for i, h := range w.header {
			if i > 0 {
				sb.WriteString(" | ")
			}
			v := rec.Get(h)
			var vStr string
			if v.IsAbsent() {
				vStr = ""
			} else {
				vStr = formatValue(v, w.opts)
			}
			sb.WriteString(vStr)
		}
		sb.WriteString(" |\n")
		w.bw.WriteString(sb.String())
		sb.Reset()
	}

	return w.bw.Flush()
}

// DCF Reader (Debian Control File)
type DCFReader struct {
	br   *bufio.Reader
	opts *Options
	done bool
}

func newDCFReader(br *bufio.Reader, opts *Options) *DCFReader {
	return &DCFReader{br: br, opts: opts}
}

func (r *DCFReader) Read(state *State) (*Record, error) {
	if r.done {
		return nil, io.EOF
	}

	rec := NewRecord()
	hasData := false
	var currentKey string
	var currentVal strings.Builder

	for {
		line, err := readLine(r.br)
		if err == io.EOF && line == "" {
			if hasData {
				if currentKey != "" {
					rec.Put(currentKey, InferType(strings.TrimRight(currentVal.String(), "\n"), &r.opts.InferOpts))
				}
				r.done = true
				return rec, nil
			}
			return nil, io.EOF
		}
		if err != nil && line == "" {
			if hasData {
				if currentKey != "" {
					rec.Put(currentKey, InferType(strings.TrimRight(currentVal.String(), "\n"), &r.opts.InferOpts))
				}
				return rec, nil
			}
			return nil, err
		}

		line = strings.TrimRight(line, "\r")

		if line == "" {
			if hasData {
				if currentKey != "" {
					rec.Put(currentKey, InferType(strings.TrimRight(currentVal.String(), "\n"), &r.opts.InferOpts))
				}
				return rec, nil
			}
			continue
		}

		hasData = true

		// Check if continuation line (starts with space/tab)
		if (line[0] == ' ' || line[0] == '\t') && currentKey != "" {
			currentVal.WriteString("\n")
			currentVal.WriteString(strings.TrimLeft(line, " \t"))
			continue
		}

		// Save previous key-value
		if currentKey != "" {
			rec.Put(currentKey, InferType(currentVal.String(), &r.opts.InferOpts))
			currentVal.Reset()
		}

		// Parse "key: value"
		idx := strings.Index(line, ": ")
		if idx < 0 {
			idx = strings.Index(line, ":")
		}
		if idx >= 0 {
			currentKey = line[:idx]
			if idx+2 <= len(line) {
				currentVal.WriteString(line[idx+2:])
			} else if idx+1 <= len(line) {
				currentVal.WriteString(line[idx+1:])
			}
		} else {
			currentKey = line
		}
	}
}

// DCF Writer
type DCFWriter struct {
	bw   *bufio.Writer
	opts *Options
}

func newDCFWriter(bw *bufio.Writer, opts *Options) *DCFWriter {
