		// Document separator
		if line == "---" {
			if hasData {
				return rec, nil
			}
			continue
		}

		if line == "" {
			if hasData {
				return rec, nil
			}
			continue
		}

		hasData = true

		// Parse "key: value"
		idx := strings.Index(line, ": ")
		if idx >= 0 {
			key := strings.TrimSpace(line[:idx])
			val := strings.TrimSpace(line[idx+2:])
			rec.Put(key, InferType(val, &r.opts.InferOpts))
