		}
		if err != nil && line == "" {
			if hasData {
				return rec, nil
			}
			return nil, err
		}

		line = strings.TrimRight(line, "\r")

		if line == "" {
			emptyLineCount++
			if emptyLineCount >= 1 && hasData {
				return rec, nil
			}
			continue
		}
		emptyLineCount = 0

		// Handle comments
		if r.opts.PassComments && r.opts.PassCommentsWith != "" && strings.HasPrefix(line, r.opts.PassCommentsWith) {
			writeComment(line, state)
			continue
		}
		if r.opts.SkipComments && r.opts.SkipCommentsWith != "" && strings.HasPrefix(line, r.opts.SkipCommentsWith) {
			continue
		}

		hasData = true

		// Parse "key   value"
		ips := r.opts.IPS
		var key, val string

		if r.opts.IPSRegex {
			idx := indexByRegex(line, ips)
			if idx < 0 {
				key = line
				val = ""
			} else {
				key = line[:idx]
				val = line[idx+1:]
			}
		} else {
			// Default: split on first occurrence of IPS (which is " ")
			// But we need to handle multiple spaces for alignment
			parts := strings.SplitN(line, ips, 2)
			if len(parts) == 2 {
				key = strings.TrimRight(parts[0], " ")
				val = strings.TrimLeft(parts[1], " ")
			} else {
				key = line
				val = ""
			}
		}

		rec.Put(key, InferType(val, &r.opts.InferOpts))
	}
}

