func (r *YAMLReader) Read(state *State) (*Record, error) {
	if r.done {
		return nil, io.EOF
	}

	rec := NewRecord()
	hasData := false

	for {
		line, err := readLine(r.br)
		if err == io.EOF && line == "" {
			if hasData {
				r.done = true
				return rec, nil
			}
			return nil, io.EOF
		}
		if err != nil && line == "" {
			if hasData {
				return rec, nil
			}
			return nil, err
		}

		line = strings.TrimRight(line, "\r")

		// Document separator
		if line == "---" {
			if hasData {
				return rec, nil
			}
			continue
		}

		if line == "" {
			if hasData {
				return rec, nil
			}
			continue
		}

		hasData = true

		// Parse "key: value"
		idx := strings.Index(line, ": ")
		if idx >= 0 {
			key := strings.TrimSpace(line[:idx])
			val := strings.TrimSpace(line[idx+2:])
			rec.Put(key, InferType(val, &r.opts.InferOpts))
		} else if strings.HasSuffix(line, ":") {
			key := strings.TrimSuffix(line, ":")
			rec.Put(key, MV_EMPTY)
		}
	}
}

