	opts  *Options
	first bool
	count int
	// If yarray, buffer all and wrap in array
	records []*Record
}

func newYAMLWriter(bw *bufio.Writer, opts *Options) *YAMLWriter {
	return &YAMLWriter{bw: bw, opts: opts, first: true}
}

func (w *YAMLWriter) Write(rec *Record, state *State) error {
	if w.opts.YArray && !w.opts.NoYArray {
		w.records = append(w.records, rec.Copy())
		return nil
	}

	if !w.first {
		w.bw.WriteString("---\n")
	}
	w.first = false

	return w.writeRecord(rec)
}

func (w *YAMLWriter) writeRecord(rec *Record) error {
	for _, k := range rec.Keys() {
		v := rec.Get(k)
		vStr := formatValue(v, w.opts)
		w.bw.WriteString(k + ": " + vStr + "\n")
	}
	return w.bw.Flush()
}

func (w *YAMLWriter) Done() error {
	if w.opts.YArray && !w.opts.NoYArray {
		if len(w.records) == 0 {
			w.bw.WriteString("[]\n")
			return w.bw.Flush()
		}

		// Write as YAML array
		for _, rec := range w.records {
			first := true
			for _, k := range rec.Keys() {
				v := rec.Get(k)
				vStr := formatValue(v, w.opts)
				if first {
					w.bw.WriteString("- " + k + ": " + vStr + "\n")
					first = false
				} else {
					w.bw.WriteString("  " + k + ": " + vStr + "\n")
				}
			}
		}
	}
	return w.bw.Flush()
}

