			}
			if strings.HasPrefix(line, "|") {
				// Data line - strip leading/trailing |
				line = strings.Trim(line, "|")
			}
		}

		if line == "" {
			continue
		}

		// Handle comments
		if r.opts.PassComments && r.opts.PassCommentsWith != "" && strings.HasPrefix(line, r.opts.PassCommentsWith) {
			writeComment(line, state)
			continue
		}
		if r.opts.SkipComments && r.opts.SkipCommentsWith != "" && strings.HasPrefix(line, r.opts.SkipCommentsWith) {
			continue
		}

		var fields []string
		if r.opts.RepIFS || r.opts.IFS == " " {
			fields = strings.Fields(line)
		} else {
			fields = splitString(line, r.opts.IFS)
		}

		if r.header == nil {
			r.header = fields
			continue
		}

		rec := NewRecord()
		for i, h := range r.header {
			var val string
			if i < len(fields) {
				val = fields[i]
			}
			rec.Put(h, InferType(val, &r.opts.InferOpts))
		}
		return rec, nil
	}
