// YAML Reader (basic implementation)
type YAMLReader struct {
	br   *bufio.Reader
	opts *Options
	done bool
}

func newYAMLReader(br *bufio.Reader, opts *Options) *YAMLReader {
	return &YAMLReader{br: br, opts: opts}
}

func (r *YAMLReader) Read(state *State) (*Record, error) {
	if r.done {
		return nil, io.EOF
	}

	rec := NewRecord()
	hasData := false

	for {
		line, err := readLine(r.br)
		if err == io.EOF && line == "" {
			if hasData {
				r.done = true
				return rec, nil
			}
			return nil, io.EOF
		}
		if err != nil && line == "" {
			if hasData {
				return rec, nil
			}
			return nil, err
		}

		line = strings.TrimRight(line, "\r")

		// Document separator
		if line == "---" {
			if hasData {
				return rec, nil
			}
			continue
		}

		if line == "" {
			if hasData {
				return rec, nil
			}
			continue
		}

		hasData = true

		// Parse "key: value"
		idx := strings.Index(line, ": ")
		if idx >= 0 {
			key := strings.TrimSpace(line[:idx])
			val := strings.TrimSpace(line[idx+2:])
			rec.Put(key, InferType(val, &r.opts.InferOpts))
		} else if strings.HasSuffix(line, ":") {
			key := strings.TrimSuffix(line, ":")
			rec.Put(key, MV_EMPTY)
		}
	}
}

// YAML Writer
type YAMLWriter struct {
	bw    *bufio.Writer
	opts  *Options
	first bool
	count int
	// If yarray, buffer all and wrap in array
	records []*Record
}

func newYAMLWriter(bw *bufio.Writer, opts *Options) *YAMLWriter {
	return &YAMLWriter{bw: bw, opts: opts, first: true}
}

func (w *YAMLWriter) Write(rec *Record, state *State) error {
	if w.opts.YArray && !w.opts.NoYArray {
		w.records = append(w.records, rec.Copy())
		return nil
	}

	if !w.first {
		w.bw.WriteString("---\n")
	}
	w.first = false

	return w.writeRecord(rec)
}

func (w *YAMLWriter) writeRecord(rec *Record) error {
	for _, k := range rec.Keys() {
		v := rec.Get(k)
		vStr := formatValue(v, w.opts)
		w.bw.WriteString(k + ": " + vStr + "\n")
	}
	return w.bw.Flush()
}

func (w *YAMLWriter) Done() error {
	if w.opts.YArray && !w.opts.NoYArray {
		if len(w.records) == 0 {
			w.bw.WriteString("[]\n")
			return w.bw.Flush()
		}

		// Write as YAML array
		for _, rec := range w.records {
			first := true
			for _, k := range rec.Keys() {
				v := rec.Get(k)
				vStr := formatValue(v, w.opts)
				if first {
					w.bw.WriteString("- " + k + ": " + vStr + "\n")
					first = false
				} else {
					w.bw.WriteString("  " + k + ": " + vStr + "\n")
				}
			}
		}
	}
	return w.bw.Flush()
}

// Gen Reader (generate sequential numeric records)
type GenReader struct {
	opts    *Options
	current int64
	done    bool
}

func newGenReader(opts *Options) *GenReader {
	return &GenReader{opts: opts, current: opts.GenStart}
}

func (r *GenReader) Read(state *State) (*Record, error) {
	if r.done {
		return nil, io.EOF
	}

	if r.opts.GenStep > 0 && r.current > r.opts.GenStop {
		r.done = true
		return nil, io.EOF
	}
	if r.opts.GenStep < 0 && r.current < r.opts.GenStop {
		r.done = true
		return nil, io.EOF
	}

	rec := NewRecord()
	rec.Put(r.opts.GenFieldName, MvFromInt(r.current))
	r.current += r.opts.GenStep

	return rec, nil
}

