package main

// VarStack manages local variable scopes for DSL execution
type VarStack struct {
	frames []map[string]*MLRVal
}

func NewVarStack() *VarStack {
	return &VarStack{
		frames: []map[string]*MLRVal{make(map[string]*MLRVal)},
	}
}

func (vs *VarStack) Push() {
	vs.frames = append(vs.frames, make(map[string]*MLRVal))
}

func (vs *VarStack) Pop() {
	if len(vs.frames) > 1 {
		vs.frames = vs.frames[:len(vs.frames)-1]
	}
}

func (vs *VarStack) Get(name string) *MLRVal {
	// Search from top of stack down
	for i := len(vs.frames) - 1; i >= 0; i-- {
		if v, ok := vs.frames[i][name]; ok {
			return v
		}
	}
	return MV_ABSENT
}

func (vs *VarStack) Set(name string, val *MLRVal) {
	// Set in current frame
	if len(vs.frames) > 0 {
		vs.frames[len(vs.frames)-1][name] = val
	}
}

func (vs *VarStack) SetGlobal(name string, val *MLRVal) {
	// Set in bottom frame
	if len(vs.frames) > 0 {
		vs.frames[0][name] = val
	}
}

func (vs *VarStack) Unset(name string) {
	for i := len(vs.frames) - 1; i >= 0; i-- {
		if _, ok := vs.frames[i][name]; ok {
			delete(vs.frames[i], name)
			return
		}
	}
}
