package main

import (
	"compress/bzip2"
	"compress/gzip"
	"compress/zlib"
	"fmt"
	"io"
	"os"
	"os/exec"
)

func openGZIP(r io.ReadCloser) (io.ReadCloser, error) {
	gz, err := gzip.NewReader(r)
	if err != nil {
		r.Close()
		return nil, err
	}
	return &multiCloser2{ReadCloser: gz, inner: r}, nil
}

func openBZ2(r io.ReadCloser) (io.ReadCloser, error) {
	bz := bzip2.NewReader(r)
	return &multiCloser2{ReadCloser: io.NopCloser(bz), inner: r}, nil
}

func openZlib(r io.ReadCloser) (io.ReadCloser, error) {
	zr, err := zlib.NewReader(r)
	if err != nil {
		r.Close()
		return nil, err
	}
	return &multiCloser2{ReadCloser: zr, inner: r}, nil
}

func openZstd(r io.ReadCloser) (io.ReadCloser, error) {
	cmd := exec.Command("zstd", "-d", "--stdout")
	cmd.Stdin = r
	out, err := cmd.Output()
	if err != nil {
		r.Close()
		return nil, fmt.Errorf("zstd decompression failed: %v", err)
	}
	r.Close()
	return io.NopCloser(&byteSliceReader2{data: out, pos: 0}), nil
}

func openWithPrepipe(cmdStr string, useFilename bool) (io.ReadCloser, error) {
	cmd := exec.Command("sh", "-c", cmdStr)
	cmd.Stderr = os.Stderr
	out, err := cmd.Output()
	if err != nil {
		return nil, fmt.Errorf("prepipe command failed: %v", err)
	}
	return io.NopCloser(&byteSliceReader2{data: out, pos: 0}), nil
}

type byteSliceReader2 struct {
	data []byte
	pos  int
}

func (r *byteSliceReader2) Read(p []byte) (int, error) {
	if r.pos >= len(r.data) {
		return 0, io.EOF
	}
	n := copy(p, r.data[r.pos:])
	r.pos += n
	return n, nil
}

type multiCloser2 struct {
	io.ReadCloser
	inner io.Closer
}

func (m *multiCloser2) Close() error {
	err1 := m.ReadCloser.Close()
	err2 := m.inner.Close()
	if err1 != nil {
		return err1
	}
	return err2
}
