package main

import (
	"bufio"
	"encoding/hex"
	"fmt"
	"io"
	"os"
	"strings"
)

func doHex(args []string) int {
	raw := false
	var files []string

	for i := 0; i < len(args); i++ {
		switch args[i] {
		case "-r":
			raw = true
		case "-h", "--help":
			fmt.Print(`Usage: mlr hex [options] {zero or more file names}
Simple hex-dump.
If zero file names are supplied, standard input is read.
Options:
-r: print only raw hex without leading offset indicators or trailing ASCII dump.
-h or --help: print this message
`)
			return 0
		default:
			files = append(files, args[i])
		}
	}

	if len(files) == 0 {
		hexDump(os.Stdin, raw)
	} else {
		for _, f := range files {
			fh, err := os.Open(f)
			if err != nil {
				fmt.Fprintf(os.Stderr, "mlr hex: %v\n", err)
				return 1
			}
			hexDump(fh, raw)
			fh.Close()
		}
	}
	return 0
}

func hexDump(r io.Reader, raw bool) {
	data, err := io.ReadAll(r)
	if err != nil {
		return
	}

	if raw {
		fmt.Print(hex.EncodeToString(data))
		return
	}

	offset := 0
	for offset < len(data) {
		end := offset + 16
		if end > len(data) {
			end = len(data)
		}
		chunk := data[offset:end]

		fmt.Printf("%08x: ", offset)

		// Hex part
		for i := 0; i < 16; i++ {
			if i > 0 && i%8 == 0 {
				fmt.Print(" ")
			}
			if i < len(chunk) {
				fmt.Printf("%02x ", chunk[i])
			} else {
				fmt.Print("   ")
			}
		}

		// ASCII part
		fmt.Print(" |")
		for _, b := range chunk {
			if b >= 0x20 && b < 0x7f {
				fmt.Printf("%c", b)
			} else {
				fmt.Print(".")
			}
		}
		fmt.Println("|")

		offset += 16
	}
}

func doLecat(args []string) int {
	mono := false
	var files []string

	for i := 0; i < len(args); i++ {
		switch args[i] {
		case "--mono":
			mono = true
		case "-h", "--help":
			fmt.Print(`Usage: mlr lecat [options] {zero or more file names}
Simply echoes input, but flags CR characters in red and LF characters in green.
If zero file names are supplied, standard input is read.
Options:
--mono: don't try to colorize the output
-h or --help: print this message
`)
			return 0
		default:
			files = append(files, args[i])
		}
	}

	if len(files) == 0 {
		lecatDump(os.Stdin, mono)
	} else {
		for _, f := range files {
			fh, err := os.Open(f)
			if err != nil {
				fmt.Fprintf(os.Stderr, "mlr lecat: %v\n", err)
				return 1
			}
			lecatDump(fh, mono)
			fh.Close()
		}
	}
	return 0
}

func lecatDump(r io.Reader, mono bool) {
	br := bufio.NewReader(r)
	for {
		b, err := br.ReadByte()
		if err != nil {
			break
		}
		if b == '\r' {
			if mono {
				fmt.Print("<CR>")
			} else {
				fmt.Print("\033[31m<CR>\033[0m")
			}
		} else if b == '\n' {
			if mono {
				fmt.Print("<LF>")
			} else {
				fmt.Print("\033[32m<LF>\033[0m")
			}
			fmt.Println()
		} else {
			fmt.Printf("%c", b)
		}
	}
}

func doTermcvt(args []string) int {
	fmt.Print(`Usage: mlr termcvt [options] {zero or more file names}
Terminates lines with specified line ending.
If zero file names are supplied, standard input is read.
Options:
--from {format}: Input format (lf, crlf, cr). Default: lf.
--to {format}: Output format (lf, crlf, cr). Default: lf.
-i: In-place (modify files rather than writing to stdout).
-h or --help: print this message.
`)
	return 0
}

func doUnhex(args []string) int {
	var files []string

	for i := 0; i < len(args); i++ {
		switch args[i] {
		case "-h", "--help":
			fmt.Print(`Usage: mlr unhex [options] {zero or more file names}
Reads hexadecimal strings and decodes them.
If zero file names are supplied, standard input is read.
Options:
-h or --help: print this message
`)
			return 0
		default:
			files = append(files, args[i])
		}
	}

	if len(files) == 0 {
		unhexDump(os.Stdin)
	} else {
		for _, f := range files {
			fh, err := os.Open(f)
			if err != nil {
				fmt.Fprintf(os.Stderr, "mlr unhex: %v\n", err)
				return 1
			}
			unhexDump(fh)
			fh.Close()
		}
	}
	return 0
}

func unhexDump(r io.Reader) {
	scanner := bufio.NewScanner(r)
	for scanner.Scan() {
		line := scanner.Text()
		line = strings.TrimSpace(line)
		// Remove spaces
		line = strings.ReplaceAll(line, " ", "")
		decoded, err := hex.DecodeString(line)
		if err != nil {
			fmt.Fprintf(os.Stderr, "mlr unhex: %v\n", err)
			continue
		}
		os.Stdout.Write(decoded)
	}
}
