package main

import (
	"math/rand"
)

var globalRand = rand.New(rand.NewSource(0))
var randSeeded = false

func seedRandom(seed int64) {
	globalRand = rand.New(rand.NewSource(seed))
	randSeeded = true
}

func urand() float64 {
	return globalRand.Float64()
}

func urand32() int64 {
	return int64(globalRand.Uint32())
}

func urandint(lo, hi int64) int64 {
	if lo >= hi {
		return lo
	}
	return lo + globalRand.Int63n(hi-lo+1)
}

func urandrange(lo, hi float64) float64 {
	return lo + globalRand.Float64()*(hi-lo)
}

func urandelement(arr []*MLRVal) *MLRVal {
	if len(arr) == 0 {
		return MV_ABSENT
	}
	return arr[globalRand.Intn(len(arr))]
}
