type CutVerb struct {
	SimpleVerbBase
	fields      []string
	complement  bool
	reorder     bool
	regex       bool
}

func newCutVerb(args []string, opts *Options) (VerbHandler, []string, error) {
	v := &CutVerb{}
	i := 0
	for i < len(args) {
		switch args[i] {
		case "-f":
			i++
			if i >= len(args) {
				return nil, nil, fmt.Errorf("cut: -f requires field names")
			}
			v.fields = strings.Split(args[i], ",")
		case "-x", "--complement":
			v.complement = true
		case "-o":
			v.reorder = true
		case "-r":
			v.regex = true
		case "-h", "--help":
			printVerbHelp("cut")
			os.Exit(0)
		default:
			return v, args[i:], nil
		}
		i++
	}
	return v, nil, nil
}

func (v *CutVerb) Process(rec *Record, state *State) []*Record {
	if rec == nil {
		return nil
	}

	out := NewRecord()

	if v.complement {
		// Keep fields NOT in list
		for _, k := range rec.Keys() {
			if !v.fieldMatches(k) {
				out.Put(k, rec.Get(k))
			}
		}
	} else if v.reorder {
		// Keep specified fields in specified order
		for _, f := range v.fields {
			if v.regex {
				// Find all matching fields in order
				for _, k := range rec.Keys() {
					if matchesPattern(k, f) {
						out.Put(k, rec.Get(k))
					}
				}
			} else {
				val := rec.Get(f)
				if !val.IsAbsent() {
					out.Put(f, val)
				}
			}
		}
	} else {
		// Keep fields in original order
		for _, k := range rec.Keys() {
			if v.fieldMatches(k) {
				out.Put(k, rec.Get(k))
			}
		}
	}

	return []*Record{out}
}

func (v *CutVerb) fieldMatches(k string) bool {
	for _, f := range v.fields {
		if v.regex {
			if matchesPattern(k, f) {
				return true
			}
		} else {
			if k == f {
				return true
			}
		}
	}
	return false
}

func matchesPattern(s, pattern string) bool {
	// Check for case-insensitive suffix
	re, _ := getRegexMiller(pattern)
	if re == nil {
		return s == pattern
	}
	return re.MatchString(s)
}

