type RenameVerb struct {
	SimpleVerbBase
	oldNew  []string // alternating old, new
	regex   bool
}

func newRenameVerb(args []string, opts *Options) (VerbHandler, []string, error) {
	v := &RenameVerb{}
	i := 0
	for i < len(args) {
		switch args[i] {
		case "-r":
			v.regex = true
		case "-g":
			v.regex = true
		case "-h", "--help":
			printVerbHelp("rename")
			os.Exit(0)
		default:
			// Remaining args are old,new pairs as comma-separated
			if len(v.oldNew) == 0 {
				v.oldNew = strings.Split(args[i], ",")
			} else {
				return v, args[i:], nil
			}
		}
		i++
	}
	return v, nil, nil
}

func (v *RenameVerb) Process(rec *Record, state *State) []*Record {
	if rec == nil {
		return nil
	}

	for i := 0; i+1 < len(v.oldNew); i += 2 {
		old := v.oldNew[i]
		newName := v.oldNew[i+1]

		if v.regex {
			for _, k := range rec.Keys() {
				if regexMatch(k, old) {
					newKey := regexSub(k, old, newName)
					rec.Rename(k, newKey)
				}
			}
		} else {
			rec.Rename(old, newName)
		}
	}

	return []*Record{rec}
}

