type ReorderVerb struct {
	SimpleVerbBase
	fields []string
	putAtEnd bool
}

func newReorderVerb(args []string, opts *Options) (VerbHandler, []string, error) {
	v := &ReorderVerb{}
	i := 0
	for i < len(args) {
		switch args[i] {
		case "-f":
			i++
			if i >= len(args) {
				return nil, nil, fmt.Errorf("reorder: -f requires field names")
			}
			v.fields = strings.Split(args[i], ",")
		case "-e":
			v.putAtEnd = true
		case "-h", "--help":
			printVerbHelp("reorder")
			os.Exit(0)
		default:
			return v, args[i:], nil
		}
		i++
	}
	return v, nil, nil
}

func (v *ReorderVerb) Process(rec *Record, state *State) []*Record {
	if rec == nil {
		return nil
	}
	if v.putAtEnd {
		// Move specified fields to end
		rec.Reorder(v.fields, false)
	} else {
		// Move specified fields to front (default -f behavior)
		rec.MoveToFront(v.fields)
	}
	return []*Record{rec}
}
