		}
		i++
	}
	return v, nil, nil
}

func (v *ReorderVerb) Process(rec *Record, state *State) []*Record {
	if rec == nil {
		return nil
	}
	if v.putAtEnd {
		// Move specified fields to end
		rec.Reorder(v.fields, false)
	} else {
		// Move specified fields to front (default -f behavior)
		rec.MoveToFront(v.fields)
	}
	return []*Record{rec}
}
