	for i, k := range v.keys {
		vals[i] = rec.Get(k.field)
	}
	v.records = append(v.records, sortRecord{rec: rec, vals: vals})
	return nil
}

func (v *SortVerb) Flush(state *State) []*Record {
	sort.SliceStable(v.records, func(i, j int) bool {
		for ki, k := range v.keys {
			cmp := compareSortVals(v.records[i].vals[ki], v.records[j].vals[ki], k.order)
			if cmp != 0 {
				return cmp < 0
			}
		}
		return false
	})

	out := make([]*Record, len(v.records))
	for i, r := range v.records {
		out[i] = r.rec
	}
	return out
}

func compareSortVals(a, b *MLRVal, order sortOrder) int {
	// Absent values sort last for ascending, first for descending
	aAbsent := a.IsAbsent() || a.IsNull()
	bAbsent := b.IsAbsent() || b.IsNull()

	switch order {
	case SORT_NUM_ASC:
		if aAbsent && bAbsent {
			return 0
		}
		if aAbsent {
			return 1
		}
		if bAbsent {
			return -1
		}
		af := toFloat(a)
		bf := toFloat(b)
		if math.IsNaN(af) && math.IsNaN(bf) {
			return 0
		}
		if math.IsNaN(af) {
			return 1
		}
		if math.IsNaN(bf) {
			return -1
		}
		if af < bf {
			return -1
		}
		if af > bf {
			return 1
		}
		return 0
	case SORT_NUM_DESC:
		r := compareSortVals(a, b, SORT_NUM_ASC)
		if r != 0 && (!aAbsent && !bAbsent) {
			return -r
		}
		return r
	case SORT_LEX_ASC:
		as, bs := a.String(), b.String()
		if as < bs {
			return -1
		}
		if as > bs {
			return 1
		}
		return 0
	case SORT_LEX_DESC:
		r := compareSortVals(a, b, SORT_LEX_ASC)
		return -r
	case SORT_LEX_CI_ASC:
		as, bs := strings.ToLower(a.String()), strings.ToLower(b.String())
		if as < bs {
			return -1
		}
		if as > bs {
			return 1
		}
		return 0
	case SORT_LEX_CI_DESC:
		r := compareSortVals(a, b, SORT_LEX_CI_ASC)
		return -r
	case SORT_NAT_ASC:
		// Natural sort (alphanumeric)
		return naturalCompare(a.String(), b.String())
	case SORT_NAT_DESC:
		return -naturalCompare(a.String(), b.String())
	}
	return 0
}

func toFloat(v *MLRVal) float64 {
	switch v.Type {
	case VT_INT:
		return float64(v.IntVal)
	case VT_FLOAT:
		return v.FltVal
	case VT_STRING:
		f, err := strconv.ParseFloat(v.StrVal, 64)
		if err == nil {
			return f
		}
		return math.NaN()
	case VT_BOOL:
		if v.BoolVal {
			return 1
		}
		return 0
	}
	return math.NaN()
}

func naturalCompare(a, b string) int {
	// Simple natural sort: compare chunks of digits numerically
	i, j := 0, 0
	for i < len(a) && j < len(b) {
		if isDigit(a[i]) && isDigit(b[j]) {
			// Compare numeric chunks
			ai, an := getDigitChunk(a, i)
			bi, bn := getDigitChunk(b, j)
			anum, _ := strconv.ParseInt(ai, 10, 64)
			bnum, _ := strconv.ParseInt(bi, 10, 64)
			if anum < bnum {
				return -1
			}
			if anum > bnum {
				return 1
			}
			i += an
			j += bn
		} else {
			if a[i] < b[j] {
				return -1
			}
			if a[i] > b[j] {
				return 1
			}
			i++
			j++
		}
	}
	if len(a) < len(b) {
		return -1
	}
	if len(a) > len(b) {
		return 1
	}
	return 0
}

func isDigit(b byte) bool {
	return b >= '0' && b <= '9'
}

func getDigitChunk(s string, start int) (string, int) {
	end := start
	for end < len(s) && isDigit(s[end]) {
		end++
	}
	return s[start:end], end - start
}

