// UniqVerb outputs unique records
type UniqVerb struct {
	SimpleVerbBase
	groupFields []string
	excludeFields []string
	showCount   bool
	countOnly   bool
	outputAll   bool
	countField  string
	seen        map[string]int
	seenOrder   []string
	seenRecs    map[string]*Record
}

func newUniqVerb(args []string, opts *Options) (VerbHandler, []string, error) {
	v := &UniqVerb{
		countField: "count",
		seen:       make(map[string]int),
		seenRecs:   make(map[string]*Record),
	}
	i := 0
	for i < len(args) {
		switch args[i] {
		case "-g", "-f":
			i++
			if i >= len(args) {
				return nil, nil, fmt.Errorf("uniq: -%s requires field names", args[i-1])
			}
			v.groupFields = strings.Split(args[i], ",")
		case "-x":
			i++
			if i >= len(args) {
				return nil, nil, fmt.Errorf("uniq: -x requires field names")
			}
			v.excludeFields = strings.Split(args[i], ",")
		case "-c":
			v.showCount = true
		case "-n":
			v.countOnly = true
		case "-a":
			v.outputAll = true
		case "-o":
			i++
			if i >= len(args) {
				return nil, nil, fmt.Errorf("uniq: -o requires field name")
			}
			v.countField = args[i]
		case "-h", "--help":
			printVerbHelp("uniq")
			os.Exit(0)
		default:
			return v, args[i:], nil
		}
		i++
	}
	return v, nil, nil
}

func (v *UniqVerb) Process(rec *Record, state *State) []*Record {
	if rec == nil {
		return nil
	}

	var key string
	if v.outputAll {
		// Full record as key
		key = recordKey(rec, nil, nil)
	} else if len(v.excludeFields) > 0 {
		key = recordKey(rec, nil, v.excludeFields)
	} else {
		key = recordKey(rec, v.groupFields, nil)
	}

	if _, ok := v.seen[key]; !ok {
		v.seenOrder = append(v.seenOrder, key)
		if v.outputAll {
			v.seenRecs[key] = rec.Copy()
		} else {
			v.seenRecs[key] = rec.Copy()
		}
	}
	v.seen[key]++

	if !v.showCount && !v.countOnly && !v.outputAll {
		// Streaming output for non-count mode
		if v.seen[key] == 1 {
			return []*Record{rec}
		}
		return nil
	}

	return nil
}

func (v *UniqVerb) Flush(state *State) []*Record {
	if v.countOnly {
		rec := NewRecord()
		rec.Put("count", MvFromInt(int64(len(v.seen))))
		return []*Record{rec}
	}

	if v.showCount || v.outputAll {
		var out []*Record
		for _, key := range v.seenOrder {
			rec := v.seenRecs[key].Copy()
			if v.showCount {
				rec.Put(v.countField, MvFromInt(int64(v.seen[key])))
			}
			out = append(out, rec)
		}
		return out
	}

	return nil
}

func recordKey(rec *Record, includeFields, excludeFields []string) string {
	var sb strings.Builder
	for _, k := range rec.Keys() {
		if len(includeFields) > 0 {
			found := false
			for _, f := range includeFields {
				if k == f {
					found = true
					break
				}
			}
			if !found {
				continue
			}
		}
		if len(excludeFields) > 0 {
			skip := false
			for _, f := range excludeFields {
				if k == f {
					skip = true
					break
				}
			}
			if skip {
				continue
			}
		}
		sb.WriteString(k)
		sb.WriteString("=")
		sb.WriteString(rec.Get(k).String())
		sb.WriteString("|")
	}
	return sb.String()
}

