	v := &HavingFieldsVerb{}
	i := 0
	for i < len(args) {
		switch args[i] {
		case "--all-match":
			i++
			if i >= len(args) {
				return nil, nil, fmt.Errorf("having-fields: --all-match requires pattern")
			}
			v.allMatch = []string{args[i]}
		case "--any-match":
			i++
			if i >= len(args) {
				return nil, nil, fmt.Errorf("having-fields: --any-match requires pattern")
			}
			v.anyMatch = []string{args[i]}
		case "--none-match":
			i++
			if i >= len(args) {
				return nil, nil, fmt.Errorf("having-fields: --none-match requires pattern")
			}
			v.noneMatch = []string{args[i]}
		case "-h", "--help":
			printVerbHelp("having-fields")
			os.Exit(0)
		default:
			return v, args[i:], nil
		}
		i++
	}
	return v, nil, nil
}

func (v *HavingFieldsVerb) Process(rec *Record, state *State) []*Record {
	if rec == nil {
		return nil
	}

	keys := rec.Keys()

	for _, pattern := range v.allMatch {
		for _, k := range keys {
			if !regexMatch(k, pattern) {
				return nil
			}
		}
	}

	for _, pattern := range v.anyMatch {
		found := false
		for _, k := range keys {
			if regexMatch(k, pattern) {
				found = true
				break
			}
		}
		if !found {
			return nil
		}
	}

	for _, pattern := range v.noneMatch {
		for _, k := range keys {
			if regexMatch(k, pattern) {
				return nil
			}
		}
	}

	return []*Record{rec}
}

