func (v *SortVerb) Process(rec *Record, state *State) []*Record {
	if rec == nil {
		return nil
	}
	vals := make([]*MLRVal, len(v.keys))
	for i, k := range v.keys {
		vals[i] = rec.Get(k.field)
	}
	v.records = append(v.records, sortRecord{rec: rec, vals: vals})
	return nil
}

func (v *SortVerb) Flush(state *State) []*Record {
	sort.SliceStable(v.records, func(i, j int) bool {
		for ki, k := range v.keys {
			cmp := compareSortVals(v.records[i].vals[ki], v.records[j].vals[ki], k.order)
			if cmp != 0 {
				return cmp < 0
			}
		}
		return false
	})

	out := make([]*Record, len(v.records))
	for i, r := range v.records {
		out[i] = r.rec
	}
	return out
}

func compareSortVals(a, b *MLRVal, order sortOrder) int {
	// Absent values sort last for ascending, first for descending
	aAbsent := a.IsAbsent() || a.IsNull()
	bAbsent := b.IsAbsent() || b.IsNull()

	switch order {
	case SORT_NUM_ASC:
		if aAbsent && bAbsent {
			return 0
		}
		if aAbsent {
			return 1
		}
		if bAbsent {
			return -1
		}
		af := toFloat(a)
		bf := toFloat(b)
		if math.IsNaN(af) && math.IsNaN(bf) {
			return 0
		}
		if math.IsNaN(af) {
			return 1
		}
		if math.IsNaN(bf) {
			return -1
		}
		if af < bf {
			return -1
		}
		if af > bf {
			return 1
		}
		return 0
	case SORT_NUM_DESC:
		r := compareSortVals(a, b, SORT_NUM_ASC)
		if r != 0 && (!aAbsent && !bAbsent) {
			return -r
		}
		return r
	case SORT_LEX_ASC:
		as, bs := a.String(), b.String()
		if as < bs {
			return -1
		}
		if as > bs {
			return 1
		}
		return 0
	case SORT_LEX_DESC:
		r := compareSortVals(a, b, SORT_LEX_ASC)
		return -r
	case SORT_LEX_CI_ASC:
		as, bs := strings.ToLower(a.String()), strings.ToLower(b.String())
		if as < bs {
			return -1
		}
		if as > bs {
			return 1
		}
		return 0
	case SORT_LEX_CI_DESC:
		r := compareSortVals(a, b, SORT_LEX_CI_ASC)
		return -r
	case SORT_NAT_ASC:
		// Natural sort (alphanumeric)
		return naturalCompare(a.String(), b.String())
	case SORT_NAT_DESC:
		return -naturalCompare(a.String(), b.String())
	}
	return 0
}

func toFloat(v *MLRVal) float64 {
	switch v.Type {
	case VT_INT:
		return float64(v.IntVal)
	case VT_FLOAT:
		return v.FltVal
	case VT_STRING:
		f, err := strconv.ParseFloat(v.StrVal, 64)
		if err == nil {
			return f
		}
		return math.NaN()
	case VT_BOOL:
		if v.BoolVal {
			return 1
		}
		return 0
	}
	return math.NaN()
}

func naturalCompare(a, b string) int {
	// Simple natural sort: compare chunks of digits numerically
	i, j := 0, 0
	for i < len(a) && j < len(b) {
		if isDigit(a[i]) && isDigit(b[j]) {
			// Compare numeric chunks
			ai, an := getDigitChunk(a, i)
			bi, bn := getDigitChunk(b, j)
			anum, _ := strconv.ParseInt(ai, 10, 64)
			bnum, _ := strconv.ParseInt(bi, 10, 64)
			if anum < bnum {
				return -1
			}
			if anum > bnum {
				return 1
			}
			i += an
			j += bn
		} else {
			if a[i] < b[j] {
				return -1
			}
			if a[i] > b[j] {
				return 1
			}
			i++
			j++
		}
	}
	if len(a) < len(b) {
		return -1
	}
	if len(a) > len(b) {
		return 1
	}
	return 0
}

func isDigit(b byte) bool {
	return b >= '0' && b <= '9'
}

func getDigitChunk(s string, start int) (string, int) {
	end := start
	for end < len(s) && isDigit(s[end]) {
		end++
	}
	return s[start:end], end - start
}

// SortWithinRecordsVerb sorts keys within each record
type SortWithinRecordsVerb struct {
	SimpleVerbBase
	reverse bool
}

func newSortWithinRecordsVerb(args []string, opts *Options) (VerbHandler, []string, error) {
	v := &SortWithinRecordsVerb{}
	for i := 0; i < len(args); i++ {
		switch args[i] {
		case "-r":
			v.reverse = true
		case "-h", "--help":
			printVerbHelp("sort-within-records")
			os.Exit(0)
		default:
			return v, args[i:], nil
		}
	}
	return v, nil, nil
}

func (v *SortWithinRecordsVerb) Process(rec *Record, state *State) []*Record {
	if rec == nil {
		return nil
	}
	keys := rec.Keys()
	sortedKeys := make([]string, len(keys))
	copy(sortedKeys, keys)
	if v.reverse {
		sort.Sort(sort.Reverse(sort.StringSlice(sortedKeys)))
	} else {
		sort.Strings(sortedKeys)
	}

	newRec := NewRecord()
	for _, k := range sortedKeys {
		newRec.Put(k, rec.Get(k))
	}
	return []*Record{newRec}
}

// UniqVerb outputs unique records
type UniqVerb struct {
	SimpleVerbBase
	groupFields []string
	excludeFields []string
	showCount   bool
	countOnly   bool
	outputAll   bool
	countField  string
	seen        map[string]int
	seenOrder   []string
	seenRecs    map[string]*Record
}

func newUniqVerb(args []string, opts *Options) (VerbHandler, []string, error) {
	v := &UniqVerb{
		countField: "count",
		seen:       make(map[string]int),
		seenRecs:   make(map[string]*Record),
	}
	i := 0
	for i < len(args) {
		switch args[i] {
		case "-g", "-f":
			i++
			if i >= len(args) {
				return nil, nil, fmt.Errorf("uniq: -%s requires field names", args[i-1])
			}
			v.groupFields = strings.Split(args[i], ",")
		case "-x":
			i++
			if i >= len(args) {
				return nil, nil, fmt.Errorf("uniq: -x requires field names")
			}
			v.excludeFields = strings.Split(args[i], ",")
		case "-c":
			v.showCount = true
		case "-n":
			v.countOnly = true
		case "-a":
			v.outputAll = true
		case "-o":
			i++
			if i >= len(args) {
				return nil, nil, fmt.Errorf("uniq: -o requires field name")
			}
			v.countField = args[i]
		case "-h", "--help":
			printVerbHelp("uniq")
			os.Exit(0)
		default:
			return v, args[i:], nil
		}
		i++
	}
	return v, nil, nil
}

func (v *UniqVerb) Process(rec *Record, state *State) []*Record {
	if rec == nil {
		return nil
	}

	var key string
	if v.outputAll {
		// Full record as key
		key = recordKey(rec, nil, nil)
	} else if len(v.excludeFields) > 0 {
		key = recordKey(rec, nil, v.excludeFields)
	} else {
		key = recordKey(rec, v.groupFields, nil)
	}

	if _, ok := v.seen[key]; !ok {
		v.seenOrder = append(v.seenOrder, key)
		if v.outputAll {
			v.seenRecs[key] = rec.Copy()
		} else {
			v.seenRecs[key] = rec.Copy()
		}
	}
	v.seen[key]++

	if !v.showCount && !v.countOnly && !v.outputAll {
		// Streaming output for non-count mode
		if v.seen[key] == 1 {
			return []*Record{rec}
		}
		return nil
	}

	return nil
}

func (v *UniqVerb) Flush(state *State) []*Record {
	if v.countOnly {
		rec := NewRecord()
		rec.Put("count", MvFromInt(int64(len(v.seen))))
		return []*Record{rec}
	}

	if v.showCount || v.outputAll {
		var out []*Record
		for _, key := range v.seenOrder {
			rec := v.seenRecs[key].Copy()
			if v.showCount {
				rec.Put(v.countField, MvFromInt(int64(v.seen[key])))
			}
			out = append(out, rec)
		}
		return out
	}

	return nil
}

func recordKey(rec *Record, includeFields, excludeFields []string) string {
	var sb strings.Builder
	for _, k := range rec.Keys() {
		if len(includeFields) > 0 {
			found := false
			for _, f := range includeFields {
				if k == f {
					found = true
					break
				}
			}
			if !found {
				continue
			}
		}
		if len(excludeFields) > 0 {
			skip := false
			for _, f := range excludeFields {
				if k == f {
					skip = true
					break
				}
			}
			if skip {
				continue
			}
		}
		sb.WriteString(k)
		sb.WriteString("=")
		sb.WriteString(rec.Get(k).String())
		sb.WriteString("|")
	}
	return sb.String()
}

// CountVerb counts records
type CountVerb struct {
	SimpleVerbBase
