	counts      map[string]int64
	order       []string
	samples     map[string]*Record
}

func newCountVerb(args []string, opts *Options) (VerbHandler, []string, error) {
	v := &CountVerb{
		countField: "count",
		counts:     make(map[string]int64),
		samples:    make(map[string]*Record),
	}
	i := 0
	for i < len(args) {
		switch args[i] {
		case "-g":
			i++
			if i >= len(args) {
				return nil, nil, fmt.Errorf("count: -g requires field names")
			}
			v.groupFields = strings.Split(args[i], ",")
		case "-n":
			v.countOnly = true
		case "-o":
			i++
			if i >= len(args) {
				return nil, nil, fmt.Errorf("count: -o requires field name")
			}
			v.countField = args[i]
		case "-h", "--help":
			printVerbHelp("count")
			os.Exit(0)
		default:
			return v, args[i:], nil
		}
		i++
	}
	return v, nil, nil
}

func (v *CountVerb) Process(rec *Record, state *State) []*Record {
	if rec == nil {
		return nil
	}
	key := groupKey(rec, v.groupFields)
	if _, ok := v.counts[key]; !ok {
		v.order = append(v.order, key)
		v.samples[key] = rec.Copy()
	}
	v.counts[key]++
	return nil
}

func (v *CountVerb) Flush(state *State) []*Record {
	if v.countOnly {
		rec := NewRecord()
		rec.Put(v.countField, MvFromInt(int64(len(v.counts))))
		return []*Record{rec}
	}

	var out []*Record
	for _, key := range v.order {
		rec := NewRecord()
		// Add group fields
		sample := v.samples[key]
		for _, gf := range v.groupFields {
			rec.Put(gf, sample.Get(gf))
		}
		rec.Put(v.countField, MvFromInt(v.counts[key]))
		out = append(out, rec)
	}
	return out
}

