		switch args[i] {
		case "-v":
			v.invert = true
		case "-h", "--help":
			printVerbHelp("grep")
			os.Exit(0)
		default:
			if v.pattern == "" {
				v.pattern = args[i]
			} else {
				return v, args[i:], nil
			}
		}
		i++
	}
	return v, nil, nil
}

func (v *GrepVerb) Process(rec *Record, state *State) []*Record {
	if rec == nil {
		return nil
	}
	// Check if any field value matches the pattern
	matched := false
	for _, k := range rec.Keys() {
		val := rec.Get(k).String()
		if regexMatch(val, v.pattern) {
			matched = true
			break
		}
	}
	if v.invert {
		matched = !matched
	}
	if matched {
		return []*Record{rec}
	}
	return nil
}

