func (v *SubVerb) shouldProcess(k string) bool {
	if len(v.fields) > 0 {
		for _, f := range v.fields {
			if k == f {
				return true
			}
		}
		return false
	}
	if v.fieldRegex != "" {
		return regexMatch(k, v.fieldRegex)
	}
	return true
}

