type SsubVerb struct {
	SimpleVerbBase
	fields []string
	old    string
	new    string
}

func newSsubVerb(args []string, opts *Options) (VerbHandler, []string, error) {
	v := &SsubVerb{}
	i := 0
	for i < len(args) {
		switch args[i] {
		case "-f":
			i++
			if i >= len(args) {
				return nil, nil, fmt.Errorf("ssub: -f requires field names")
			}
			v.fields = strings.Split(args[i], ",")
		case "-h", "--help":
			printVerbHelp("ssub")
			os.Exit(0)
		default:
			if v.old == "" {
				v.old = args[i]
			} else if v.new == "" {
				v.new = args[i]
			} else {
				return v, args[i:], nil
			}
		}
		i++
	}
	return v, nil, nil
}

func (v *SsubVerb) Process(rec *Record, state *State) []*Record {
	if rec == nil {
		return nil
	}
	for _, k := range rec.Keys() {
		if len(v.fields) == 0 || containsStr(v.fields, k) {
			val := rec.Get(k)
			if val.IsString() {
				newVal := strings.Replace(val.StrVal, v.old, v.new, 1)
				rec.Put(k, MvFromString(newVal))
			}
		}
	}
	return []*Record{rec}
}

func containsStr(slice []string, s string) bool {
	for _, v := range slice {
		if v == s {
			return true
		}
	}
	return false
