type UnsparsifyVerb struct {
	fields   []string
	fillWith string
	allKeys  map[string]bool
	keyOrder []string
	records  []*Record
}

func newUnsparsifyVerb(args []string, opts *Options) (VerbHandler, []string, error) {
	v := &UnsparsifyVerb{
		fillWith: "",
		allKeys:  make(map[string]bool),
	}
	i := 0
	for i < len(args) {
		switch args[i] {
		case "--fill-with":
			i++
			if i >= len(args) {
				return nil, nil, fmt.Errorf("unsparsify: --fill-with requires value")
			}
			v.fillWith = args[i]
		case "-f":
			i++
			if i >= len(args) {
				return nil, nil, fmt.Errorf("unsparsify: -f requires field names")
			}
			v.fields = strings.Split(args[i], ",")
		case "-h", "--help":
			printVerbHelp("unsparsify")
			os.Exit(0)
		default:
			return v, args[i:], nil
		}
		i++
	}
	return v, nil, nil
}

func (v *UnsparsifyVerb) Process(rec *Record, state *State) []*Record {
	if rec == nil {
		return nil
	}

	if len(v.fields) > 0 {
		// Streaming mode for specific fields
		for _, f := range v.fields {
			if !rec.Has(f) {
				rec.Put(f, InferType(v.fillWith, nil))
			}
		}
		return []*Record{rec}
	}

	// Full mode - accumulate
	for _, k := range rec.Keys() {
		if !v.allKeys[k] {
			v.allKeys[k] = true
			v.keyOrder = append(v.keyOrder, k)
		}
	}
	v.records = append(v.records, rec)
	return nil
}

func (v *UnsparsifyVerb) Flush(state *State) []*Record {
	if len(v.fields) > 0 || len(v.records) == 0 {
		return nil
	}

	out := make([]*Record, len(v.records))
	for i, rec := range v.records {
		// Make sure all keys are present in key order
		newRec := NewRecord()
		for _, k := range v.keyOrder {
			if rec.Has(k) {
				newRec.Put(k, rec.Get(k))
			} else {
				newRec.Put(k, MvFromString(v.fillWith))
			}
		}
		// Add any extra keys not in keyOrder (shouldn't happen but be safe)
		for _, k := range rec.Keys() {
			if !v.allKeys[k] {
				newRec.Put(k, rec.Get(k))
			}
		}
		out[i] = newRec
	}
	return out
}

