					}
				}
				if !skip {
					rec.Put(k, sample.Get(k))
				}
			} else {
				rec.Put(k, sample.Get(k))
			}
		}
		rec.Put(v.countField, MvFromInt(v.counts[key]))
		out = append(out, rec)
	}
	return out
