		default:
			return v, args[i:], nil
		}
		i++
	}
	return v, nil, nil
}

func (v *HavingFieldsVerb) Process(rec *Record, state *State) []*Record {
	if rec == nil {
		return nil
	}

	keys := rec.Keys()

	for _, pattern := range v.allMatch {
		for _, k := range keys {
			if !regexMatch(k, pattern) {
				return nil
			}
		}
	}

	for _, pattern := range v.anyMatch {
		found := false
		for _, k := range keys {
			if regexMatch(k, pattern) {
				found = true
				break
			}
		}
		if !found {
			return nil
		}
	}

	for _, pattern := range v.noneMatch {
		for _, k := range keys {
			if regexMatch(k, pattern) {
				return nil
			}
		}
	}

	return []*Record{rec}
}

