func newSparsifyVerb(args []string, opts *Options) (VerbHandler, []string, error) {
	v := &SparsifyVerb{}
	i := 0
	for i < len(args) {
		switch args[i] {
		case "-f":
			i++
			if i >= len(args) {
				return nil, nil, fmt.Errorf("sparsify: -f requires field names")
			}
			v.fields = strings.Split(args[i], ",")
		case "-h", "--help":
			printVerbHelp("sparsify")
