func (v *SparsifyVerb) Process(rec *Record, state *State) []*Record {
	if rec == nil {
		return nil
	}

	var toRemove []string
	for _, k := range rec.Keys() {
		if len(v.fields) > 0 && !containsStr(v.fields, k) {
			continue
		}
		val := rec.Get(k)
