// SortVerb sorts records
type SortVerb struct {
	records []sortRecord
	keys    []sortKey
}

type sortKey struct {
	field string
	order sortOrder
}

type sortOrder int
const (
	SORT_LEX_ASC  sortOrder = iota
	SORT_LEX_DESC
	SORT_LEX_CI_ASC
	SORT_LEX_CI_DESC
	SORT_NUM_ASC
	SORT_NUM_DESC
	SORT_NAT_ASC
	SORT_NAT_DESC
)

type sortRecord struct {
	rec  *Record
	vals []*MLRVal
}

func newSortVerb(args []string, opts *Options) (VerbHandler, []string, error) {
	v := &SortVerb{}
	i := 0
	for i < len(args) {
		switch args[i] {
		case "-f":
			i++
			if i >= len(args) {
				return nil, nil, fmt.Errorf("sort: -f requires field names")
			}
			for _, f := range strings.Split(args[i], ",") {
				v.keys = append(v.keys, sortKey{field: f, order: SORT_LEX_ASC})
			}
		case "-r":
			i++
			if i >= len(args) {
				return nil, nil, fmt.Errorf("sort: -r requires field names")
			}
			for _, f := range strings.Split(args[i], ",") {
				v.keys = append(v.keys, sortKey{field: f, order: SORT_LEX_DESC})
			}
		case "-c":
			i++
			if i >= len(args) {
				return nil, nil, fmt.Errorf("sort: -c requires field names")
			}
			for _, f := range strings.Split(args[i], ",") {
				v.keys = append(v.keys, sortKey{field: f, order: SORT_LEX_CI_ASC})
			}
		case "-cr":
			i++
			if i >= len(args) {
