			}
			for _, f := range strings.Split(args[i], ",") {
				v.keys = append(v.keys, sortKey{field: f, order: SORT_LEX_CI_DESC})
			}
		case "-n", "-nf":
			i++
			if i >= len(args) {
				return nil, nil, fmt.Errorf("sort: -%s requires field names", strings.TrimPrefix(args[i-1], "-"))
			}
			for _, f := range strings.Split(args[i], ",") {
