			}
		case "-t":
			i++
			if i >= len(args) {
				return nil, nil, fmt.Errorf("sort: -t requires field names")
			}
			for _, f := range strings.Split(args[i], ",") {
				v.keys = append(v.keys, sortKey{field: f, order: SORT_NAT_ASC})
			}
		case "-tr", "-rt":
			i++
			if i >= len(args) {
				return nil, nil, fmt.Errorf("sort: -%s requires field names", args[i-1])
			}
			for _, f := range strings.Split(args[i], ",") {
				v.keys = append(v.keys, sortKey{field: f, order: SORT_NAT_DESC})
			}
		case "-b":
			// Move sort fields to beginning - not needed for sort logic
		case "-h", "--help":
			printVerbHelp("sort")
