				return nil, nil, fmt.Errorf("count-distinct: -f requires field names")
			}
			v.groupFields = strings.Split(args[i], ",")
		case "-x":
			i++
			if i >= len(args) {
				return nil, nil, fmt.Errorf("count-distinct: -x requires field names")
			}
			v.excludeFields = strings.Split(args[i], ",")
		case "-n":
			v.countOnly = true
		case "-u":
			v.unlashed = true
		case "-o":
			i++
			if i >= len(args) {
				return nil, nil, fmt.Errorf("count-distinct: -o requires field name")
			}
			v.countField = args[i]
		case "-h", "--help":
			printVerbHelp("count-distinct")
			os.Exit(0)
		default:
			return v, args[i:], nil
		}
		i++
	}
	return v, nil, nil
}

func (v *CountDistinctVerb) Process(rec *Record, state *State) []*Record {
	if rec == nil {
		return nil
	}

	key := recordKey(rec, v.groupFields, v.excludeFields)
	if _, ok := v.counts[key]; !ok {
		v.order = append(v.order, key)
		v.samples[key] = rec.Copy()
	}
	v.counts[key]++
	return nil
}

func (v *CountDistinctVerb) Flush(state *State) []*Record {
	if v.countOnly {
		rec := NewRecord()
		rec.Put(v.countField, MvFromInt(int64(len(v.counts))))
		return []*Record{rec}
	}

	var out []*Record
	for _, key := range v.order {
		rec := NewRecord()
		sample := v.samples[key]
		// Add group or exclude fields
		for _, k := range sample.Keys() {
			if len(v.groupFields) > 0 {
				found := false
				for _, gf := range v.groupFields {
					if k == gf {
						found = true
						break
					}
				}
				if found {
					rec.Put(k, sample.Get(k))
				}
			} else if len(v.excludeFields) > 0 {
				skip := false
				for _, ef := range v.excludeFields {
					if k == ef {
						skip = true
						break
					}
				}
				if !skip {
					rec.Put(k, sample.Get(k))
				}
			} else {
				rec.Put(k, sample.Get(k))
			}
		}
		rec.Put(v.countField, MvFromInt(v.counts[key]))
		out = append(out, rec)
	}
	return out
}

