type Stats1Verb struct {
	accumulators []string
	valueFields  []string
	groupFields  []string
	// State: map from group key to map from "field_accumulator" to value
	groups    map[string]*stats1Group
	order     []string
}

type stats1Group struct {
	groupVals map[string]*MLRVal
	counts    map[string]int64
	sums      map[string]float64
	mins      map[string]float64
	maxes     map[string]float64
	means     map[string]float64
	stddevs   map[string]*onlineStats
	// For median/percentile: need to store all values
	allVals   map[string][]float64
}

type onlineStats struct {
	n    int64
	mean float64
	M2   float64
}

func (s *onlineStats) update(x float64) {
	s.n++
	delta := x - s.mean
	s.mean += delta / float64(s.n)
	delta2 := x - s.mean
	s.M2 += delta * delta2
}

func (s *onlineStats) variance() float64 {
	if s.n < 2 {
		return math.NaN()
	}
	return s.M2 / float64(s.n-1)
}

func (s *onlineStats) stddev() float64 {
	return math.Sqrt(s.variance())
}

func newStats1Verb(args []string, opts *Options) (VerbHandler, []string, error) {
	v := &Stats1Verb{
		groups: make(map[string]*stats1Group),
	}
	i := 0
	for i < len(args) {
		switch args[i] {
		case "-a":
			i++
			if i >= len(args) {
				return nil, nil, fmt.Errorf("stats1: -a requires accumulator names")
			}
			v.accumulators = strings.Split(args[i], ",")
		case "-f":
			i++
			if i >= len(args) {
				return nil, nil, fmt.Errorf("stats1: -f requires field names")
			}
			v.valueFields = strings.Split(args[i], ",")
		case "-g":
			i++
			if i >= len(args) {
				return nil, nil, fmt.Errorf("stats1: -g requires group-by field names")
			}
			v.groupFields = strings.Split(args[i], ",")
		case "-F":
			// Float output - no-op for now
		case "-h", "--help":
			printVerbHelp("stats1")
			os.Exit(0)
		default:
			return v, args[i:], nil
		}
		i++
	}
	return v, nil, nil
}

func (v *Stats1Verb) Process(rec *Record, state *State) []*Record {
	if rec == nil {
		return nil
	}

	key := groupKey(rec, v.groupFields)
	grp, ok := v.groups[key]
	if !ok {
		grp = &stats1Group{
			groupVals: make(map[string]*MLRVal),
			counts:    make(map[string]int64),
			sums:      make(map[string]float64),
			mins:      make(map[string]float64),
			maxes:     make(map[string]float64),
			means:     make(map[string]float64),
			stddevs:   make(map[string]*onlineStats),
			allVals:   make(map[string][]float64),
		}
		// Save group-by values
		for _, gf := range v.groupFields {
			grp.groupVals[gf] = rec.Get(gf)
		}
		v.groups[key] = grp
		v.order = append(v.order, key)
	}

	for _, vf := range v.valueFields {
		val := rec.Get(vf)
		if val.IsAbsent() || val.IsNull() {
			continue
		}

		fval := toFloat(val)
		if math.IsNaN(fval) {
			continue
		}

		grp.counts[vf]++

		for _, acc := range v.accumulators {
			switch acc {
			case "count":
				// already counted
			case "sum":
				grp.sums[vf] += fval
			case "min":
				if grp.counts[vf] == 1 || fval < grp.mins[vf] {
					grp.mins[vf] = fval
				}
			case "max":
				if grp.counts[vf] == 1 || fval > grp.maxes[vf] {
					grp.maxes[vf] = fval
				}
			case "mean":
				if os, ok2 := grp.stddevs["mean_"+vf]; ok2 {
					os.update(fval)
				} else {
					s := &onlineStats{}
					s.update(fval)
					grp.stddevs["mean_"+vf] = s
				}
			case "stddev", "var", "skewness", "kurtosis", "meaneb":
				k := acc + "_" + vf
				if s, ok2 := grp.stddevs[k]; ok2 {
					s.update(fval)
				} else {
					s := &onlineStats{}
					s.update(fval)
					grp.stddevs[k] = s
				}
			case "median", "p25", "p75", "p90", "p95", "p99":
				grp.allVals[vf] = append(grp.allVals[vf], fval)
			}
		}
	}

	return nil
}

func (v *Stats1Verb) Flush(state *State) []*Record {
	var out []*Record

	for _, key := range v.order {
		grp := v.groups[key]
		rec := NewRecord()

		// Add group fields
		for _, gf := range v.groupFields {
			rec.Put(gf, grp.groupVals[gf])
		}

		// Add accumulator results
		for _, vf := range v.valueFields {
			for _, acc := range v.accumulators {
				outKey := vf + "_" + acc
				switch acc {
				case "count":
					rec.Put(outKey, MvFromInt(grp.counts[vf]))
				case "sum":
					s := grp.sums[vf]
					if s == math.Trunc(s) && !math.IsInf(s, 0) {
						rec.Put(outKey, MvFromInt(int64(s)))
					} else {
						rec.Put(outKey, MvFromFloat(s))
					}
				case "min":
					if grp.counts[vf] > 0 {
						rec.Put(outKey, MvFromFloat(grp.mins[vf]))
					}
				case "max":
					if grp.counts[vf] > 0 {
						rec.Put(outKey, MvFromFloat(grp.maxes[vf]))
					}
				case "mean":
					if s, ok := grp.stddevs["mean_"+vf]; ok {
						rec.Put(outKey, MvFromFloat(s.mean))
					}
				case "stddev":
					if s, ok := grp.stddevs[acc+"_"+vf]; ok {
						rec.Put(outKey, MvFromFloat(s.stddev()))
					}
				case "var":
					if s, ok := grp.stddevs[acc+"_"+vf]; ok {
						rec.Put(outKey, MvFromFloat(s.variance()))
					}
				case "meaneb":
					if s, ok := grp.stddevs[acc+"_"+vf]; ok && s.n > 0 {
						rec.Put(outKey, MvFromFloat(s.stddev()/math.Sqrt(float64(s.n))))
					}
				case "median":
					if vals, ok := grp.allVals[vf]; ok && len(vals) > 0 {
						rec.Put(outKey, MvFromFloat(percentile(vals, 50)))
					}
				case "p25":
					if vals, ok := grp.allVals[vf]; ok && len(vals) > 0 {
						rec.Put(outKey, MvFromFloat(percentile(vals, 25)))
					}
				case "p75":
					if vals, ok := grp.allVals[vf]; ok && len(vals) > 0 {
						rec.Put(outKey, MvFromFloat(percentile(vals, 75)))
					}
				case "p90":
					if vals, ok := grp.allVals[vf]; ok && len(vals) > 0 {
						rec.Put(outKey, MvFromFloat(percentile(vals, 90)))
					}
				case "p95":
					if vals, ok := grp.allVals[vf]; ok && len(vals) > 0 {
						rec.Put(outKey, MvFromFloat(percentile(vals, 95)))
					}
				case "p99":
					if vals, ok := grp.allVals[vf]; ok && len(vals) > 0 {
						rec.Put(outKey, MvFromFloat(percentile(vals, 99)))
					}
				case "mode":
					// Mode
				case "antimode":
					// Antimode
				case "null_count":
					// Already tracked
				}
			}
		}

		out = append(out, rec)
	}

	return out
}

func percentile(vals []float64, p float64) float64 {
	sorted := make([]float64, len(vals))
	copy(sorted, vals)
	sort.Float64s(sorted)

	n := float64(len(sorted))
	idx := p / 100.0 * (n - 1)
	lo := int(idx)
	hi := lo + 1

	if hi >= len(sorted) {
		return sorted[lo]
	}

	frac := idx - float64(lo)
	return sorted[lo]*(1-frac) + sorted[hi]*frac
}

// FillDownVerb
type FillDownVerb struct {
	SimpleVerbBase
	fields      []string
	all         bool
	onlyAbsent  bool
	lastVals    map[string]*MLRVal
}

func newFillDownVerb(args []string, opts *Options) (VerbHandler, []string, error) {
	v := &FillDownVerb{
		lastVals: make(map[string]*MLRVal),
	}
	i := 0
	for i < len(args) {
		switch args[i] {
		case "-f":
			i++
			if i >= len(args) {
				return nil, nil, fmt.Errorf("fill-down: -f requires field names")
			}
			v.fields = strings.Split(args[i], ",")
		case "--all":
			v.all = true
		case "-a", "--only-if-absent":
			v.onlyAbsent = true
		case "-h", "--help":
			printVerbHelp("fill-down")
			os.Exit(0)
		default:
			return v, args[i:], nil
		}
		i++
	}
	return v, nil, nil
}

func (v *FillDownVerb) Process(rec *Record, state *State) []*Record {
	if rec == nil {
		return nil
	}

	if v.all {
		for _, k := range rec.Keys() {
			v.fillField(rec, k)
		}
	} else {
		for _, f := range v.fields {
			v.fillField(rec, f)
		}
	}

	return []*Record{rec}
}

func (v *FillDownVerb) fillField(rec *Record, f string) {
	val := rec.Get(f)
	missing := val.IsAbsent() || (!v.onlyAbsent && val.IsEmpty())

	if missing {
		if last, ok := v.lastVals[f]; ok {
			rec.Put(f, last)
		}
	} else {
		v.lastVals[f] = val
	}
}

// FillEmptyVerb
type FillEmptyVerb struct {
	SimpleVerbBase
	fillVal string
	noInfer bool
}

func newFillEmptyVerb(args []string, opts *Options) (VerbHandler, []string, error) {
	v := &FillEmptyVerb{fillVal: "N/A"}
	i := 0
	for i < len(args) {
		switch args[i] {
		case "-v":
			i++
			if i >= len(args) {
				return nil, nil, fmt.Errorf("fill-empty: -v requires value")
			}
			v.fillVal = args[i]
		case "-S":
			v.noInfer = true
		case "-h", "--help":
			printVerbHelp("fill-empty")
			os.Exit(0)
		default:
			return v, args[i:], nil
		}
		i++
	}
	return v, nil, nil
}

func (v *FillEmptyVerb) Process(rec *Record, state *State) []*Record {
	if rec == nil {
		return nil
	}

	for _, k := range rec.Keys() {
		val := rec.Get(k)
		if val.IsEmpty() || val.IsAbsent() {
			if v.noInfer {
				rec.Put(k, MvFromString(v.fillVal))
			} else {
				rec.Put(k, InferType(v.fillVal, nil))
			}
		}
	}

	return []*Record{rec}
}

// CleanWhitespaceVerb
type CleanWhitespaceVerb struct {
	SimpleVerbBase
	keysOnly   bool
	valuesOnly bool
}

func newCleanWhitespaceVerb(args []string, opts *Options) (VerbHandler, []string, error) {
	v := &CleanWhitespaceVerb{}
	i := 0
	for i < len(args) {
		switch args[i] {
		case "-k", "--keys-only":
			v.keysOnly = true
		case "-v", "--values-only":
			v.valuesOnly = true
		case "-h", "--help":
			printVerbHelp("clean-whitespace")
			os.Exit(0)
		default:
			return v, args[i:], nil
		}
		i++
	}
	return v, nil, nil
}

func (v *CleanWhitespaceVerb) Process(rec *Record, state *State) []*Record {
	if rec == nil {
		return nil
	}

	if !v.valuesOnly {
		// Clean keys
		newRec := NewRecord()
		for _, k := range rec.Keys() {
			cleanK := cleanWhitespace(k)
			val := rec.Get(k)
			if !v.keysOnly && val.IsString() {
				val = MvFromString(cleanWhitespace(val.StrVal))
			}
			newRec.Put(cleanK, val)
		}
		return []*Record{newRec}
	}

	if !v.keysOnly {
		// Clean values only
		for _, k := range rec.Keys() {
			val := rec.Get(k)
			if val.IsString() {
				rec.Put(k, MvFromString(cleanWhitespace(val.StrVal)))
			}
		}
	}

	return []*Record{rec}
}

func cleanWhitespace(s string) string {
	s = strings.TrimSpace(s)
	// Replace multiple whitespace with single space
	var b strings.Builder
	lastWasSpace := false
	for _, c := range s {
		if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
			if !lastWasSpace {
				b.WriteRune(' ')
			}
			lastWasSpace = true
		} else {
			b.WriteRune(c)
			lastWasSpace = false
		}
	}
	return b.String()
}

// FormatValuesVerb
type FormatValuesVerb struct {
	SimpleVerbBase
	fmtStr      string
	fmtIfNum    bool
	asInt       bool
	asFloat     bool
	asString    bool
}

func newFormatValuesVerb(args []string, opts *Options) (VerbHandler, []string, error) {
	v := &FormatValuesVerb{}
	i := 0
	for i < len(args) {
		switch args[i] {
		case "--ifnum":
			v.fmtIfNum = true
		case "--int":
			v.asInt = true
		case "--float":
			v.asFloat = true
		case "--string":
			v.asString = true
		case "-f":
			i++
			if i >= len(args) {
				return nil, nil, fmt.Errorf("format-values: -f requires format")
			}
			v.fmtStr = args[i]
		case "-h", "--help":
			printVerbHelp("format-values")
			os.Exit(0)
		default:
			if v.fmtStr == "" {
				v.fmtStr = args[i]
			} else {
				return v, args[i:], nil
			}
		}
		i++
	}
	return v, nil, nil
}

func (v *FormatValuesVerb) Process(rec *Record, state *State) []*Record {
	if rec == nil {
		return nil
	}

	if v.fmtStr == "" {
		return []*Record{rec}
	}

	for _, k := range rec.Keys() {
		val := rec.Get(k)
		if val.IsFloat() {
			rec.Put(k, MvFromString(fmt.Sprintf(v.fmtStr, val.FltVal)))
		} else if val.IsInt() && strings.ContainsAny(v.fmtStr, "eEfFgG") {
			rec.Put(k, MvFromString(fmt.Sprintf(v.fmtStr, float64(val.IntVal))))
		} else if val.IsInt() {
			rec.Put(k, MvFromString(fmt.Sprintf(v.fmtStr, val.IntVal)))
		}
	}

	return []*Record{rec}
}

// FractionVerb
type FractionVerb struct {
	SimpleVerbBase
	fields      []string
	groupFields []string
	cumulative  bool
	reverse     bool
	// Accumulate
	sums    map[string]float64
	records []*frationRecord
	keys    []string
}

type frationRecord struct {
	rec *Record
	key string
	vals map[string]float64
}

func newFractionVerb(args []string, opts *Options) (VerbHandler, []string, error) {
	v := &FractionVerb{
		sums: make(map[string]float64),
	}
	i := 0
	for i < len(args) {
		switch args[i] {
		case "-f":
			i++
			if i >= len(args) {
				return nil, nil, fmt.Errorf("fraction: -f requires field names")
			}
			v.fields = strings.Split(args[i], ",")
		case "-g":
			i++
			if i >= len(args) {
				return nil, nil, fmt.Errorf("fraction: -g requires field names")
			}
			v.groupFields = strings.Split(args[i], ",")
		case "-c":
			v.cumulative = true
		case "-h", "--help":
			printVerbHelp("fraction")
			os.Exit(0)
		default:
			return v, args[i:], nil
		}
		i++
	}
	return v, nil, nil
}

func (v *FractionVerb) Process(rec *Record, state *State) []*Record {
	if rec == nil {
		return nil
	}

	key := groupKey(rec, v.groupFields)

	fr := &frationRecord{rec: rec, key: key, vals: make(map[string]float64)}
	for _, f := range v.fields {
		val := rec.Get(f)
		fval := toFloat(val)
		if !math.IsNaN(fval) {
			fr.vals[f] = fval
			groupKey := key + ":" + f
			v.sums[groupKey] += fval
		}
	}
	v.records = append(v.records, fr)
	v.keys = append(v.keys, key)

	return nil
}

func (v *FractionVerb) Flush(state *State) []*Record {
	cumulativeSums := make(map[string]float64)

	var out []*Record
	for _, fr := range v.records {
		for _, f := range v.fields {
			groupKey := fr.key + ":" + f
			total := v.sums[groupKey]
			if total != 0 {
				frac := fr.vals[f] / total
				if v.cumulative {
					cumulativeSums[groupKey] += frac
					fr.rec.Put(f, MvFromFloat(cumulativeSums[groupKey]))
				} else {
					fr.rec.Put(f, MvFromFloat(frac))
				}
			}
		}
		out = append(out, fr.rec)
	}
	return out
}

// SampleVerb - reservoir sampling
type SampleVerb struct {
	groupFields []string
	k           int
	groups      map[string][]*Record
	order       []string
}

func newSampleVerb(args []string, opts *Options) (VerbHandler, []string, error) {
	v := &SampleVerb{
		k:      100,
		groups: make(map[string][]*Record),
	}
	i := 0
	for i < len(args) {
		switch args[i] {
		case "-g":
			i++
			if i >= len(args) {
				return nil, nil, fmt.Errorf("sample: -g requires field names")
			}
			v.groupFields = strings.Split(args[i], ",")
		case "-k":
			i++
			if i >= len(args) {
				return nil, nil, fmt.Errorf("sample: -k requires count")
			}
			n, err := strconv.Atoi(args[i])
			if err != nil {
				return nil, nil, err
			}
			v.k = n
		case "-h", "--help":
			printVerbHelp("sample")
			os.Exit(0)
		default:
			return v, args[i:], nil
		}
		i++
	}
	return v, nil, nil
}

func (v *SampleVerb) Process(rec *Record, state *State) []*Record {
	if rec == nil {
		return nil
	}
	key := groupKey(rec, v.groupFields)
	if _, ok := v.groups[key]; !ok {
		v.order = append(v.order, key)
	}
	buf := v.groups[key]
	if len(buf) < v.k {
		buf = append(buf, rec)
	} else {
		// Reservoir sampling
		j := int(urandint(0, int64(len(buf))))
		if j < v.k {
			buf[j] = rec
		}
	}
	v.groups[key] = buf
	return nil
}

func (v *SampleVerb) Flush(state *State) []*Record {
	var out []*Record
	for _, key := range v.order {
		out = append(out, v.groups[key]...)
	}
	return out
}

// ShuffleVerb
type ShuffleVerb struct {
	records []*Record
}

func newShuffleVerb(args []string, opts *Options) (VerbHandler, []string, error) {
	v := &ShuffleVerb{}
	for i := 0; i < len(args); i++ {
		if args[i] == "-h" || args[i] == "--help" {
			printVerbHelp("shuffle")
			os.Exit(0)
		} else {
			return v, args[i:], nil
		}
	}
	return v, nil, nil
}

func (v *ShuffleVerb) Process(rec *Record, state *State) []*Record {
	if rec == nil {
		return nil
	}
	v.records = append(v.records, rec)
	return nil
}

func (v *ShuffleVerb) Flush(state *State) []*Record {
	// Fisher-Yates shuffle
	for i := len(v.records) - 1; i > 0; i-- {
		j := int(urandint(0, int64(i)))
		v.records[i], v.records[j] = v.records[j], v.records[i]
	}
	return v.records
}

// BootstrapVerb
type BootstrapVerb struct {
	n       int64
	records []*Record
	useN    bool
}

func newBootstrapVerb(args []string, opts *Options) (VerbHandler, []string, error) {
	v := &BootstrapVerb{n: -1}
	i := 0
	for i < len(args) {
		switch args[i] {
		case "-n":
			i++
			if i >= len(args) {
				return nil, nil, fmt.Errorf("bootstrap: -n requires count")
			}
			n, err := parseInt64(args[i])
			if err != nil {
				return nil, nil, err
			}
			v.n = n
			v.useN = true
		case "-h", "--help":
			printVerbHelp("bootstrap")
			os.Exit(0)
		default:
			return v, args[i:], nil
		}
		i++
	}
	return v, nil, nil
}

func (v *BootstrapVerb) Process(rec *Record, state *State) []*Record {
	if rec == nil {
		return nil
	}
	v.records = append(v.records, rec)
	return nil
}

func (v *BootstrapVerb) Flush(state *State) []*Record {
	n := int64(len(v.records))
	if v.useN {
		n = v.n
	}

	out := make([]*Record, n)
	for i := int64(0); i < n; i++ {
		idx := urandint(0, int64(len(v.records))-1)
		out[i] = v.records[idx]
	}
	return out
}

