func (v *RepeatVerb) Process(rec *Record, state *State) []*Record {
	if rec == nil {
		return nil
	}

	n := v.n
	if v.nField != "" {
		val := rec.Get(v.nField)
		if val.IsInt() {
			n = val.IntVal
		} else if val.IsFloat() {
			n = int64(val.FltVal)
		}
	}

	out := make([]*Record, n)
	for i := int64(0); i < n; i++ {
		out[i] = rec.Copy()
	}
	return out
}

