	i := 0
	for i < len(args) {
		if args[i] == "-h" || args[i] == "--help" {
			printVerbHelp(name)
			os.Exit(0)
		}
		if strings.HasPrefix(args[i], "-") {
			i++
			if i < len(args) && !strings.HasPrefix(args[i], "-") {
				i++ // skip argument to flag
			}
		} else {
			return v, args[i:], nil
		}
	}
	return v, nil, nil
}

