// CleanWhitespaceVerb
type CleanWhitespaceVerb struct {
	SimpleVerbBase
	keysOnly   bool
	valuesOnly bool
}

func newCleanWhitespaceVerb(args []string, opts *Options) (VerbHandler, []string, error) {
	v := &CleanWhitespaceVerb{}
	i := 0
	for i < len(args) {
		switch args[i] {
		case "-k", "--keys-only":
			v.keysOnly = true
		case "-v", "--values-only":
			v.valuesOnly = true
		case "-h", "--help":
			printVerbHelp("clean-whitespace")
			os.Exit(0)
		default:
			return v, args[i:], nil
		}
		i++
	}
	return v, nil, nil
}

func (v *CleanWhitespaceVerb) Process(rec *Record, state *State) []*Record {
	if rec == nil {
		return nil
	}

	if !v.valuesOnly {
		// Clean keys
		newRec := NewRecord()
		for _, k := range rec.Keys() {
			cleanK := cleanWhitespace(k)
			val := rec.Get(k)
			if !v.keysOnly && val.IsString() {
				val = MvFromString(cleanWhitespace(val.StrVal))
			}
			newRec.Put(cleanK, val)
		}
		return []*Record{newRec}
	}

	if !v.keysOnly {
		// Clean values only
		for _, k := range rec.Keys() {
			val := rec.Get(k)
			if val.IsString() {
				rec.Put(k, MvFromString(cleanWhitespace(val.StrVal)))
			}
		}
	}

	return []*Record{rec}
}

func cleanWhitespace(s string) string {
	s = strings.TrimSpace(s)
	// Replace multiple whitespace with single space
	var b strings.Builder
	lastWasSpace := false
	for _, c := range s {
		if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
			if !lastWasSpace {
				b.WriteRune(' ')
			}
			lastWasSpace = true
		} else {
			b.WriteRune(c)
			lastWasSpace = false
		}
	}
	return b.String()
}

