// Seqgen generates its own records - needs special handling in pipeline
// For now, just pass through input records (correct behavior would be to ignore input and generate)
func (v *SeqgenVerb) Process(rec *Record, state *State) []*Record {
	return nil // seqgen ignores input records
}

func (v *SeqgenVerb) Flush(state *State) []*Record {
	var out []*Record

	startF := toFloat(v.start)
	stepF := toFloat(v.step)
	stopF := toFloat(v.stop)

	for current := startF; ; current += stepF {
		if stepF > 0 && current > stopF {
			break
		}
		if stepF < 0 && current < stopF {
			break
		}
		if stepF == 0 {
			break
		}

		rec := NewRecord()
		// Keep as int if all values are integers
		if v.start.IsInt() && v.step.IsInt() && v.stop.IsInt() {
			rec.Put(v.fieldName, MvFromInt(int64(current)))
		} else {
			rec.Put(v.fieldName, MvFromFloat(current))
		}
		out = append(out, rec)
	}

	return out
}

// BarVerb
type BarVerb struct {
	SimpleVerbBase
	fields     []string
	lo         float64
	hi         float64
	width      int
	fillChar   string
	oobChar    string
	blankChar  string
	auto       bool
	autoRecords []*Record
	autoVals    map[string][]float64
}

func newBarVerb(args []string, opts *Options) (VerbHandler, []string, error) {
	v := &BarVerb{
		lo:        0.0,
		hi:        100.0,
		width:     40,
		fillChar:  "*",
		oobChar:   "#",
		blankChar: ".",
		autoVals:  make(map[string][]float64),
	}
	i := 0
	for i < len(args) {
		switch args[i] {
		case "-f":
			i++
			if i >= len(args) {
				return nil, nil, fmt.Errorf("bar: -f requires field names")
			}
			v.fields = strings.Split(args[i], ",")
		case "--lo":
			i++
			if i >= len(args) {
				return nil, nil, fmt.Errorf("bar: --lo requires value")
			}
			f, _ := parseFloat64(args[i])
			v.lo = f
		case "--hi":
			i++
			if i >= len(args) {
				return nil, nil, fmt.Errorf("bar: --hi requires value")
			}
			f, _ := parseFloat64(args[i])
			v.hi = f
		case "-w":
			i++
			if i >= len(args) {
				return nil, nil, fmt.Errorf("bar: -w requires width")
			}
			n, _ := strconv.Atoi(args[i])
			v.width = n
		case "--auto":
			v.auto = true
		case "-c":
			i++
			if i >= len(args) {
				return nil, nil, fmt.Errorf("bar: -c requires character")
			}
			v.fillChar = args[i]
		case "-x":
			i++
			if i >= len(args) {
				return nil, nil, fmt.Errorf("bar: -x requires character")
			}
			v.oobChar = args[i]
		case "-b":
			i++
			if i >= len(args) {
				return nil, nil, fmt.Errorf("bar: -b requires character")
			}
			v.blankChar = args[i]
		case "-h", "--help":
			printVerbHelp("bar")
			os.Exit(0)
		default:
			return v, args[i:], nil
		}
		i++
	}
	return v, nil, nil
}

func (v *BarVerb) Process(rec *Record, state *State) []*Record {
	if rec == nil {
		return nil
	}

	if v.auto {
		for _, f := range v.fields {
			val := rec.Get(f)
			fval := toFloat(val)
			if !math.IsNaN(fval) {
				v.autoVals[f] = append(v.autoVals[f], fval)
			}
		}
		v.autoRecords = append(v.autoRecords, rec)
		return nil
	}

	v.processRecord(rec)
	return []*Record{rec}
}

func (v *BarVerb) processRecord(rec *Record) {
	for _, f := range v.fields {
		val := rec.Get(f)
		fval := toFloat(val)
		if math.IsNaN(fval) {
			continue
		}

		bar := v.makeBar(fval, v.lo, v.hi)
		rec.Put(f, MvFromString(bar))
	}
}

func (v *BarVerb) makeBar(val, lo, hi float64) string {
	if val < lo || val > hi {
		return strings.Repeat(v.oobChar, v.width)
	}

	frac := (val - lo) / (hi - lo)
	filled := int(frac * float64(v.width))
	if filled > v.width {
		filled = v.width
	}

	return strings.Repeat(v.fillChar, filled) + strings.Repeat(v.blankChar, v.width-filled)
}

func (v *BarVerb) Flush(state *State) []*Record {
	if !v.auto {
		return nil
	}

	// Compute auto min/max
	for f, vals := range v.autoVals {
		if len(vals) == 0 {
			continue
		}
		minVal, maxVal := vals[0], vals[0]
		for _, val := range vals {
			if val < minVal {
				minVal = val
			}
			if val > maxVal {
				maxVal = val
			}
		}
		v.autoVals[f] = []float64{minVal, maxVal}
	}

	for _, rec := range v.autoRecords {
		for _, f := range v.fields {
			val := rec.Get(f)
			fval := toFloat(val)
			if math.IsNaN(fval) {
				continue
			}
			minMax := v.autoVals[f]
			if len(minMax) >= 2 {
				bar := v.makeBar(fval, minMax[0], minMax[1])
				rec.Put(f, MvFromString(bar))
			}
		}
	}

	return v.autoRecords
}

