type FillDownVerb struct {
	SimpleVerbBase
	fields      []string
	all         bool
	onlyAbsent  bool
	lastVals    map[string]*MLRVal
}

func newFillDownVerb(args []string, opts *Options) (VerbHandler, []string, error) {
	v := &FillDownVerb{
		lastVals: make(map[string]*MLRVal),
	}
	i := 0
	for i < len(args) {
		switch args[i] {
		case "-f":
			i++
			if i >= len(args) {
				return nil, nil, fmt.Errorf("fill-down: -f requires field names")
			}
			v.fields = strings.Split(args[i], ",")
		case "--all":
			v.all = true
		case "-a", "--only-if-absent":
			v.onlyAbsent = true
		case "-h", "--help":
			printVerbHelp("fill-down")
			os.Exit(0)
		default:
			return v, args[i:], nil
		}
		i++
	}
	return v, nil, nil
}

func (v *FillDownVerb) Process(rec *Record, state *State) []*Record {
	if rec == nil {
		return nil
	}

	if v.all {
		for _, k := range rec.Keys() {
			v.fillField(rec, k)
		}
	} else {
		for _, f := range v.fields {
			v.fillField(rec, f)
		}
	}

	return []*Record{rec}
}

func (v *FillDownVerb) fillField(rec *Record, f string) {
	val := rec.Get(f)
	missing := val.IsAbsent() || (!v.onlyAbsent && val.IsEmpty())

	if missing {
		if last, ok := v.lastVals[f]; ok {
			rec.Put(f, last)
		}
	} else {
		v.lastVals[f] = val
	}
}

