// PassthroughVerb is a no-op that passes records through
type PassthroughVerb struct {
	SimpleVerbBase
	name string
	args []string
}

func newPassthroughVerb(name string, args []string, opts *Options) (VerbHandler, []string, error) {
	v := &PassthroughVerb{name: name}
	// Skip all args that look like flags
	i := 0
	for i < len(args) {
		if args[i] == "-h" || args[i] == "--help" {
			printVerbHelp(name)
			os.Exit(0)
		}
		if strings.HasPrefix(args[i], "-") {
			i++
			if i < len(args) && !strings.HasPrefix(args[i], "-") {
				i++ // skip argument to flag
			}
		} else {
			return v, args[i:], nil
		}
	}
	return v, nil, nil
}

func (v *PassthroughVerb) Process(rec *Record, state *State) []*Record {
	if rec == nil {
		return nil
	}
	return []*Record{rec}
}

