// Token types for Miller DSL
type TokenType int

const (
	// Literals
	TOK_EOF TokenType = iota
	TOK_INT
	TOK_FLOAT
	TOK_STRING
	TOK_BOOL_TRUE
	TOK_BOOL_FALSE
	TOK_NULL
