	TOK_DAMP     // &&
	TOK_DPIPE    // ||
	TOK_DCARET   // ^^
	TOK_BANG     // !

	TOK_LSHIFT   // <<
	TOK_RSHIFT   // >>
	TOK_URSHIFT  // >>>

	TOK_EQ       // ==
	TOK_NEQ      // !=
	TOK_LT       // <
	TOK_GT       // >
	TOK_LEQ      // <=
	TOK_GEQ      // >=
	TOK_SPACESHIP // <=>
	TOK_MATCH    // =~
	TOK_NMATCH   // !=~

	TOK_ASSIGN       // =
	TOK_PLUS_ASSIGN  // +=
	TOK_MINUS_ASSIGN // -=
	TOK_STAR_ASSIGN  // *=
	TOK_SLASH_ASSIGN // /=
	TOK_DSTAR_ASSIGN // **=
	TOK_PERCENT_ASSIGN // %=
