	TOK_RPAREN   // )
	TOK_LBRACKET // [
	TOK_RBRACKET // ]
	TOK_LBRACE   // {
	TOK_RBRACE   // }
	TOK_COMMA    // ,
	TOK_SEMI     // ;

	// Keywords
	TOK_IF
	TOK_ELIF
	TOK_ELSE
	TOK_FOR
