	"bool": TOK_BOOL_TYPE, "num": TOK_NUM_TYPE, "map": TOK_MAP_TYPE,
	"all": TOK_ALL,
	"NR": TOK_NR, "FNR": TOK_FNR, "NF": TOK_NF,
	"FILENAME": TOK_FILENAME, "FILENUM": TOK_FILENUM,
	"IFS": TOK_IFS_VAR, "IPS": TOK_IPS_VAR, "IRS": TOK_IRS_VAR,
