type Lexer struct {
	input  []rune
	pos    int
	line   int
	col    int
}

func NewLexer(input string) *Lexer {
	return &Lexer{
		input: []rune(input),
		pos:   0,
		line:  1,
		col:   1,
	}
}

func (l *Lexer) peek() rune {
	if l.pos >= len(l.input) {
		return 0
	}
	return l.input[l.pos]
}

func (l *Lexer) peek2() rune {
	if l.pos+1 >= len(l.input) {
		return 0
	}
	return l.input[l.pos+1]
}

func (l *Lexer) peek3() rune {
	if l.pos+2 >= len(l.input) {
		return 0
	}
	return l.input[l.pos+2]
}

func (l *Lexer) advance() rune {
	if l.pos >= len(l.input) {
		return 0
	}
	c := l.input[l.pos]
	l.pos++
	if c == '\n' {
		l.line++
		l.col = 1
	} else {
		l.col++
	}
	return c
}

func (l *Lexer) skipWhitespaceAndComments() {
	for l.pos < len(l.input) {
		c := l.peek()
		if c == ' ' || c == '\t' || c == '\r' || c == '\n' {
			l.advance()
		} else if c == '#' {
			// Line comment
			for l.pos < len(l.input) && l.peek() != '\n' {
				l.advance()
			}
		} else {
			break
		}
	}
}

func (l *Lexer) Tokenize() ([]*Token, error) {
	var tokens []*Token

	for {
		l.skipWhitespaceAndComments()

		if l.pos >= len(l.input) {
			tokens = append(tokens, &Token{Type: TOK_EOF, Line: l.line, Col: l.col})
			break
		}

		tok, err := l.nextToken()
		if err != nil {
			return nil, err
		}
		if tok != nil {
			tokens = append(tokens, tok)
		}
	}

	return tokens, nil
}

func (l *Lexer) nextToken() (*Token, error) {
	line := l.line
	col := l.col
	c := l.peek()

	// Number literals
	if c >= '0' && c <= '9' || (c == '-' && l.peek2() >= '0' && l.peek2() <= '9' && false) {
		return l.lexNumber(line, col)
	}

	// String literals
	if c == '"' || c == '\'' {
		return l.lexString(line, col)
	}

	// Regex literals (in certain contexts) - we'll treat as string for now
	// Actually Miller uses strings as regexes

	// $ - field reference
	if c == '$' {
		l.advance()
		if l.peek() == '*' {
			l.advance()
			return &Token{Type: TOK_ALL_SREC, StrVal: "$*", Line: line, Col: col}, nil
		}
		if l.peek() == '[' {
			l.advance()
			return &Token{Type: TOK_FIELD_IDX, StrVal: "$[", Line: line, Col: col}, nil
		}
		if l.peek() == '{' {
			l.advance()
			// Read until }
			var sb strings.Builder
			for l.peek() != '}' && l.pos < len(l.input) {
				sb.WriteRune(l.advance())
			}
			if l.peek() == '}' {
				l.advance()
			}
			return &Token{Type: TOK_FIELD_BRACED, StrVal: sb.String(), Line: line, Col: col}, nil
		}
		// Read field name
		var sb strings.Builder
		for isIdentChar(l.peek()) {
			sb.WriteRune(l.advance())
		}
		return &Token{Type: TOK_FIELD, StrVal: sb.String(), Line: line, Col: col}, nil
	}

	// @ - out-of-stream variable
	if c == '@' {
		l.advance()
		if l.peek() == '*' {
			l.advance()
			return &Token{Type: TOK_ALL_OOSVAR, StrVal: "@*", Line: line, Col: col}, nil
		}
		if l.peek() == '[' {
			l.advance()
			return &Token{Type: TOK_OOSVAR_IDX, StrVal: "@[", Line: line, Col: col}, nil
		}
		if l.peek() == '{' {
			l.advance()
			var sb strings.Builder
			for l.peek() != '}' && l.pos < len(l.input) {
				sb.WriteRune(l.advance())
			}
			if l.peek() == '}' {
				l.advance()
			}
			return &Token{Type: TOK_OOSVAR_BRACED, StrVal: sb.String(), Line: line, Col: col}, nil
		}
		var sb strings.Builder
		for isIdentChar(l.peek()) {
			sb.WriteRune(l.advance())
		}
		return &Token{Type: TOK_OOSVAR, StrVal: sb.String(), Line: line, Col: col}, nil
	}

	// Identifiers and keywords
	if isIdentStart(c) {
		var sb strings.Builder
		for isIdentChar(l.peek()) {
			sb.WriteRune(l.advance())
		}
		name := sb.String()
		if tokType, ok := keywords[name]; ok {
			return &Token{Type: tokType, StrVal: name, Line: line, Col: col}, nil
		}
		return &Token{Type: TOK_IDENT, StrVal: name, Line: line, Col: col}, nil
	}

	// Operators
	l.advance() // consume c

	switch c {
	case '+':
		if l.peek() == '=' {
			l.advance()
			return &Token{Type: TOK_PLUS_ASSIGN, StrVal: "+=", Line: line, Col: col}, nil
		}
		return &Token{Type: TOK_PLUS, StrVal: "+", Line: line, Col: col}, nil
	case '-':
		if l.peek() == '=' {
			l.advance()
			return &Token{Type: TOK_MINUS_ASSIGN, StrVal: "-=", Line: line, Col: col}, nil
		}
		return &Token{Type: TOK_MINUS, StrVal: "-", Line: line, Col: col}, nil
	case '*':
		if l.peek() == '*' {
			l.advance()
			if l.peek() == '=' {
				l.advance()
				return &Token{Type: TOK_DSTAR_ASSIGN, StrVal: "**=", Line: line, Col: col}, nil
			}
			return &Token{Type: TOK_DSTAR, StrVal: "**", Line: line, Col: col}, nil
		}
		if l.peek() == '=' {
			l.advance()
			return &Token{Type: TOK_STAR_ASSIGN, StrVal: "*=", Line: line, Col: col}, nil
		}
		return &Token{Type: TOK_STAR, StrVal: "*", Line: line, Col: col}, nil
	case '/':
		if l.peek() == '/' {
			l.advance()
			if l.peek() == '=' {
				l.advance()
				return &Token{Type: TOK_SLASH_ASSIGN, StrVal: "//=", Line: line, Col: col}, nil
			}
			return &Token{Type: TOK_DSLASH, StrVal: "//", Line: line, Col: col}, nil
		}
		if l.peek() == '=' {
			l.advance()
			return &Token{Type: TOK_SLASH_ASSIGN, StrVal: "/=", Line: line, Col: col}, nil
		}
		return &Token{Type: TOK_SLASH, StrVal: "/", Line: line, Col: col}, nil
	case '%':
		if l.peek() == '=' {
			l.advance()
			return &Token{Type: TOK_PERCENT_ASSIGN, StrVal: "%=", Line: line, Col: col}, nil
		}
		return &Token{Type: TOK_PERCENT, StrVal: "%", Line: line, Col: col}, nil
	case '.':
		if l.peek() == '*' {
			l.advance()
			return &Token{Type: TOK_DOTSTAR, StrVal: ".*", Line: line, Col: col}, nil
		}
		if l.peek() == '+' {
			l.advance()
			return &Token{Type: TOK_DOTPLUS, StrVal: ".+", Line: line, Col: col}, nil
		}
		if l.peek() == '-' {
			l.advance()
			return &Token{Type: TOK_DOTMINUS, StrVal: ".-", Line: line, Col: col}, nil
		}
		if l.peek() == '/' {
			l.advance()
			return &Token{Type: TOK_DOTSLASH, StrVal: "./", Line: line, Col: col}, nil
		}
		if l.peek() == '=' {
			l.advance()
			return &Token{Type: TOK_DOT_ASSIGN, StrVal: ".=", Line: line, Col: col}, nil
		}
		return &Token{Type: TOK_DOT, StrVal: ".", Line: line, Col: col}, nil
	case '&':
		if l.peek() == '&' {
			l.advance()
			return &Token{Type: TOK_DAMP, StrVal: "&&", Line: line, Col: col}, nil
		}
		if l.peek() == '=' {
			l.advance()
			return &Token{Type: TOK_AMP_ASSIGN, StrVal: "&=", Line: line, Col: col}, nil
		}
		return &Token{Type: TOK_AMP, StrVal: "&", Line: line, Col: col}, nil
	case '|':
		if l.peek() == '|' {
			l.advance()
			return &Token{Type: TOK_DPIPE, StrVal: "||", Line: line, Col: col}, nil
		}
		if l.peek() == '=' {
			l.advance()
			return &Token{Type: TOK_PIPE_ASSIGN, StrVal: "|=", Line: line, Col: col}, nil
		}
		return &Token{Type: TOK_PIPE, StrVal: "|", Line: line, Col: col}, nil
	case '^':
		if l.peek() == '^' {
			l.advance()
			return &Token{Type: TOK_DCARET, StrVal: "^^", Line: line, Col: col}, nil
		}
		if l.peek() == '=' {
			l.advance()
			return &Token{Type: TOK_CARET_ASSIGN, StrVal: "^=", Line: line, Col: col}, nil
		}
		return &Token{Type: TOK_CARET, StrVal: "^", Line: line, Col: col}, nil
	case '~':
		return &Token{Type: TOK_TILDE, StrVal: "~", Line: line, Col: col}, nil
	case '!':
		if l.peek() == '=' {
			l.advance()
			if l.peek() == '~' {
				l.advance()
				return &Token{Type: TOK_NMATCH, StrVal: "!=~", Line: line, Col: col}, nil
			}
			return &Token{Type: TOK_NEQ, StrVal: "!=", Line: line, Col: col}, nil
		}
		return &Token{Type: TOK_BANG, StrVal: "!", Line: line, Col: col}, nil
	case '=':
		if l.peek() == '=' {
			l.advance()
			return &Token{Type: TOK_EQ, StrVal: "==", Line: line, Col: col}, nil
		}
		if l.peek() == '~' {
			l.advance()
			return &Token{Type: TOK_MATCH, StrVal: "=~", Line: line, Col: col}, nil
		}
		return &Token{Type: TOK_ASSIGN, StrVal: "=", Line: line, Col: col}, nil
	case '<':
		if l.peek() == '<' {
			l.advance()
			if l.peek() == '=' {
				l.advance()
				return &Token{Type: TOK_LSHIFT_ASSIGN, StrVal: "<<=", Line: line, Col: col}, nil
			}
			return &Token{Type: TOK_LSHIFT, StrVal: "<<", Line: line, Col: col}, nil
		}
		if l.peek() == '=' {
			l.advance()
			if l.peek() == '>' {
				l.advance()
				return &Token{Type: TOK_SPACESHIP, StrVal: "<=>", Line: line, Col: col}, nil
			}
			return &Token{Type: TOK_LEQ, StrVal: "<=", Line: line, Col: col}, nil
		}
		return &Token{Type: TOK_LT, StrVal: "<", Line: line, Col: col}, nil
	case '>':
		if l.peek() == '>' {
			l.advance()
			if l.peek() == '>' {
				l.advance()
				if l.peek() == '=' {
					l.advance()
					return &Token{Type: TOK_URSHIFT_ASSIGN, StrVal: ">>>=", Line: line, Col: col}, nil
				}
				return &Token{Type: TOK_URSHIFT, StrVal: ">>>", Line: line, Col: col}, nil
			}
			if l.peek() == '=' {
				l.advance()
				return &Token{Type: TOK_RSHIFT_ASSIGN, StrVal: ">>=", Line: line, Col: col}, nil
			}
			return &Token{Type: TOK_RSHIFT, StrVal: ">>", Line: line, Col: col}, nil
		}
		if l.peek() == '=' {
			l.advance()
			return &Token{Type: TOK_GEQ, StrVal: ">=", Line: line, Col: col}, nil
		}
		return &Token{Type: TOK_GT, StrVal: ">", Line: line, Col: col}, nil
	case '?':
		if l.peek() == '?' {
			l.advance()
			if l.peek() == '?' {
				l.advance()
				return &Token{Type: TOK_TQ, StrVal: "???", Line: line, Col: col}, nil
			}
			return &Token{Type: TOK_DQ, StrVal: "??", Line: line, Col: col}, nil
		}
		return &Token{Type: TOK_QUESTION, StrVal: "?", Line: line, Col: col}, nil
	case ':':
		return &Token{Type: TOK_COLON, StrVal: ":", Line: line, Col: col}, nil
	case '(':
		return &Token{Type: TOK_LPAREN, StrVal: "(", Line: line, Col: col}, nil
	case ')':
		return &Token{Type: TOK_RPAREN, StrVal: ")", Line: line, Col: col}, nil
	case '[':
		return &Token{Type: TOK_LBRACKET, StrVal: "[", Line: line, Col: col}, nil
	case ']':
		return &Token{Type: TOK_RBRACKET, StrVal: "]", Line: line, Col: col}, nil
	case '{':
		return &Token{Type: TOK_LBRACE, StrVal: "{", Line: line, Col: col}, nil
	case '}':
		return &Token{Type: TOK_RBRACE, StrVal: "}", Line: line, Col: col}, nil
	case ',':
		return &Token{Type: TOK_COMMA, StrVal: ",", Line: line, Col: col}, nil
	case ';':
		return &Token{Type: TOK_SEMI, StrVal: ";", Line: line, Col: col}, nil
	}

	return nil, fmt.Errorf("unexpected character %q at line %d col %d", c, line, col)
}

func (l *Lexer) lexNumber(line, col int) (*Token, error) {
	var sb strings.Builder
	isFloat := false

	// Hex
	if l.peek() == '0' && (l.peek2() == 'x' || l.peek2() == 'X') {
		sb.WriteRune(l.advance()) // 0
		sb.WriteRune(l.advance()) // x
		for isHexDigit(l.peek()) || l.peek() == '_' {
			if l.peek() != '_' {
				sb.WriteRune(l.advance())
			} else {
				l.advance()
			}
		}
		return &Token{Type: TOK_INT, StrVal: sb.String(), Line: line, Col: col}, nil
	}

	for l.pos < len(l.input) {
		c := l.peek()
		if c >= '0' && c <= '9' || c == '_' {
			if c != '_' {
				sb.WriteRune(c)
			}
			l.advance()
		} else if c == '.' && l.peek2() != '.' {
			sb.WriteRune(c)
			l.advance()
			isFloat = true
		} else if c == 'e' || c == 'E' {
			sb.WriteRune(c)
			l.advance()
			isFloat = true
			if l.peek() == '+' || l.peek() == '-' {
				sb.WriteRune(l.advance())
			}
		} else {
			break
		}
	}

	// Check for special suffixes (not standard Miller but be safe)

	if isFloat {
		return &Token{Type: TOK_FLOAT, StrVal: sb.String(), Line: line, Col: col}, nil
	}
	return &Token{Type: TOK_INT, StrVal: sb.String(), Line: line, Col: col}, nil
}

func (l *Lexer) lexString(line, col int) (*Token, error) {
	quote := l.advance() // consume opening quote
	var sb strings.Builder

	for l.pos < len(l.input) {
		c := l.peek()
		if c == rune(quote) {
			l.advance()
			break
		}
		if c == '\\' {
			l.advance()
			escaped := l.advance()
			switch escaped {
			case 'n':
				sb.WriteRune('\n')
			case 't':
				sb.WriteRune('\t')
			case 'r':
				sb.WriteRune('\r')
			case '\\':
				sb.WriteRune('\\')
			case '"':
				sb.WriteRune('"')
			case '\'':
				sb.WriteRune('\'')
			case '0':
				sb.WriteRune(0)
			case 'a':
				sb.WriteRune(7)
			case 'b':
				sb.WriteRune(8)
			case 'f':
				sb.WriteRune(12)
			case 'v':
				sb.WriteRune(11)
			default:
				sb.WriteRune('\\')
				sb.WriteRune(escaped)
			}
		} else {
			sb.WriteRune(l.advance())
		}
	}

	return &Token{Type: TOK_STRING, StrVal: sb.String(), Line: line, Col: col}, nil
}

func isIdentStart(c rune) bool {
	return unicode.IsLetter(c) || c == '_'
}

func isIdentChar(c rune) bool {
	return unicode.IsLetter(c) || unicode.IsDigit(c) || c == '_'
}

func isHexDigit(c rune) bool {
	return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')
}
