package main

import (
	"fmt"
	"strconv"
	"strings"
)

// DSLProgram represents a compiled DSL program
type DSLProgram struct {
	beginBlock *ASTNode
	mainBlock  *ASTNode
	endBlock   *ASTNode
	funcs      map[string]*ASTNode
	subrs      map[string]*ASTNode
	opts       *Options
}

func compileDSL(expr string, opts *Options) (*DSLProgram, error) {
	if expr == "" {
		return &DSLProgram{opts: opts, funcs: make(map[string]*ASTNode), subrs: make(map[string]*ASTNode)}, nil
	}

	lexer := NewLexer(expr)
	tokens, err := lexer.Tokenize()
	if err != nil {
		return nil, fmt.Errorf("mlr: %v", err)
	}

	parser := &Parser{tokens: tokens, pos: 0, opts: opts}
	prog, err := parser.parseProgram()
	if err != nil {
		return nil, err
	}

	return prog, nil
}

type Parser struct {
	tokens []*Token
	pos    int
	opts   *Options
}

func (p *Parser) peek() *Token {
	if p.pos >= len(p.tokens) {
		return &Token{Type: TOK_EOF}
	}
	return p.tokens[p.pos]
}

func (p *Parser) peekType() TokenType {
	return p.peek().Type
}

func (p *Parser) advance() *Token {
	tok := p.peek()
	if p.pos < len(p.tokens) {
		p.pos++
	}
	return tok
}

func (p *Parser) expect(t TokenType) (*Token, error) {
	tok := p.peek()
	if tok.Type != t {
		return nil, fmt.Errorf("mlr: Parse error on token %q at line %d column %d",
			tok.StrVal, tok.Line, tok.Col)
	}
	p.pos++
	return tok, nil
}

func (p *Parser) parseProgram() (*DSLProgram, error) {
	prog := &DSLProgram{
		opts:  p.opts,
		funcs: make(map[string]*ASTNode),
		subrs: make(map[string]*ASTNode),
	}

	// Collect begin, main, end blocks and function/subroutine definitions
	for p.peekType() != TOK_EOF {
		switch p.peekType() {
		case TOK_BEGIN:
			p.advance()
			block, err := p.parseBlock()
			if err != nil {
				return nil, err
			}
			if prog.beginBlock == nil {
				prog.beginBlock = block
			} else {
				// Merge
				prog.beginBlock.Children = append(prog.beginBlock.Children, block.Children...)
			}
		case TOK_END:
			p.advance()
			block, err := p.parseBlock()
			if err != nil {
				return nil, err
			}
			if prog.endBlock == nil {
				prog.endBlock = block
			} else {
				prog.endBlock.Children = append(prog.endBlock.Children, block.Children...)
			}
		case TOK_FUNC, TOK_FUNCT:
			p.advance()
			funcNode, name, err := p.parseFuncDef()
			if err != nil {
				return nil, err
			}
			prog.funcs[name] = funcNode
		case TOK_SUBR:
			p.advance()
			subrNode, name, err := p.parseSubrDef()
			if err != nil {
				return nil, err
			}
			prog.subrs[name] = subrNode
		default:
			stmt, err := p.parseStatement()
			if err != nil {
				return nil, err
			}
			if prog.mainBlock == nil {
				prog.mainBlock = newNode(NODE_BLOCK)
			}
			prog.mainBlock.Children = append(prog.mainBlock.Children, stmt)
		}
	}

	return prog, nil
}

func (p *Parser) parseFuncDef() (*ASTNode, string, error) {
	nameTok, err := p.expect(TOK_IDENT)
	if err != nil {
		return nil, "", err
	}
	name := nameTok.StrVal

	if _, err := p.expect(TOK_LPAREN); err != nil {
		return nil, "", err
	}

	var params []string
	for p.peekType() != TOK_RPAREN && p.peekType() != TOK_EOF {
		if len(params) > 0 {
			if _, err := p.expect(TOK_COMMA); err != nil {
				return nil, "", err
			}
		}
		paramTok, err := p.expect(TOK_IDENT)
		if err != nil {
			return nil, "", err
		}
		params = append(params, paramTok.StrVal)
	}

	if _, err := p.expect(TOK_RPAREN); err != nil {
		return nil, "", err
	}

	body, err := p.parseBlock()
	if err != nil {
		return nil, "", err
	}

	node := &ASTNode{
		Type:    NODE_FUNC_DEF,
		StrVal:  name,
		Children: []*ASTNode{body},
	}
	for _, param := range params {
		node.Children = append([]*ASTNode{{Type: NODE_LOCAL_VAR, StrVal: param}}, node.Children...)
	}
	// Store param count
	node.IntVal = int64(len(params))

	return node, name, nil
}

func (p *Parser) parseSubrDef() (*ASTNode, string, error) {
	nameTok, err := p.expect(TOK_IDENT)
	if err != nil {
		return nil, "", err
	}
	name := nameTok.StrVal

	if _, err := p.expect(TOK_LPAREN); err != nil {
		return nil, "", err
	}

	var params []string
	for p.peekType() != TOK_RPAREN && p.peekType() != TOK_EOF {
		if len(params) > 0 {
			if _, err := p.expect(TOK_COMMA); err != nil {
				return nil, "", err
			}
		}
		paramTok, err := p.expect(TOK_IDENT)
		if err != nil {
			return nil, "", err
		}
		params = append(params, paramTok.StrVal)
	}

	if _, err := p.expect(TOK_RPAREN); err != nil {
		return nil, "", err
	}

	body, err := p.parseBlock()
	if err != nil {
		return nil, "", err
	}

	node := &ASTNode{
		Type:    NODE_SUBR_DEF,
		StrVal:  name,
		Children: []*ASTNode{body},
		IntVal:  int64(len(params)),
	}

	return node, name, nil
}

func (p *Parser) parseBlock() (*ASTNode, error) {
	if _, err := p.expect(TOK_LBRACE); err != nil {
		return nil, err
	}

	block := newNode(NODE_BLOCK)

	for p.peekType() != TOK_RBRACE && p.peekType() != TOK_EOF {
		stmt, err := p.parseStatement()
		if err != nil {
			return nil, err
		}
		block.Children = append(block.Children, stmt)
	}

	if _, err := p.expect(TOK_RBRACE); err != nil {
		return nil, err
	}

	return block, nil
}

func (p *Parser) parseStatement() (*ASTNode, error) {
	tok := p.peek()

	switch tok.Type {
	case TOK_IF:
		return p.parseIf()
	case TOK_FOR:
		return p.parseFor()
	case TOK_WHILE:
		return p.parseWhile()
	case TOK_DO:
		return p.parseDoWhile()
	case TOK_BREAK:
		p.advance()
		p.skipSemicolon()
		return newNode(NODE_BREAK), nil
	case TOK_CONTINUE:
		p.advance()
		p.skipSemicolon()
		return newNode(NODE_CONTINUE), nil
	case TOK_RETURN:
		p.advance()
		if p.peekType() == TOK_SEMI || p.peekType() == TOK_RBRACE || p.peekType() == TOK_EOF {
			p.skipSemicolon()
			return newNode(NODE_RETURN), nil
		}
		expr, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		p.skipSemicolon()
		return newNode(NODE_RETURN, expr), nil
	case TOK_PRINT, TOK_PRINTN, TOK_EPRINT, TOK_EPRINTN:
		return p.parsePrint()
	case TOK_DUMP, TOK_EDUMP:
		return p.parseDump()
	case TOK_EMIT, TOK_EMIT1, TOK_EMITF, TOK_EMITP:
		return p.parseEmit()
	case TOK_TEE_KW:
		return p.parseTee()
	case TOK_UNSET:
		return p.parseUnset()
	case TOK_FILTER:
		p.advance()
		expr, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		p.skipSemicolon()
		return newNode(NODE_FILTER_STMT, expr), nil
	case TOK_CALL:
		p.advance()
		nameTok, err := p.expect(TOK_IDENT)
		if err != nil {
			return nil, err
		}
		if _, err := p.expect(TOK_LPAREN); err != nil {
			return nil, err
		}
		var args []*ASTNode
		for p.peekType() != TOK_RPAREN && p.peekType() != TOK_EOF {
			if len(args) > 0 {
				if _, err := p.expect(TOK_COMMA); err != nil {
					return nil, err
				}
			}
			arg, err := p.parseExpr()
			if err != nil {
				return nil, err
			}
			args = append(args, arg)
		}
		if _, err := p.expect(TOK_RPAREN); err != nil {
			return nil, err
		}
		p.skipSemicolon()
		node := &ASTNode{Type: NODE_CALL_STMT, FuncName: nameTok.StrVal, Children: args}
		return node, nil
	case TOK_VAR, TOK_INT_TYPE, TOK_FLOAT_TYPE, TOK_STR_TYPE, TOK_BOOL_TYPE, TOK_NUM_TYPE, TOK_MAP_TYPE:
		return p.parseVarDecl()
	case TOK_LBRACE:
		return p.parseBlock()
	case TOK_SEMI:
		p.advance()
		return newNode(NODE_BLOCK), nil
	default:
		// Expression statement (assignment, function call, etc.)
		return p.parseExprStatement()
	}
}

func (p *Parser) parseIf() (*ASTNode, error) {
	p.advance() // consume 'if'

	if _, err := p.expect(TOK_LPAREN); err != nil {
		return nil, err
	}
	cond, err := p.parseExpr()
	if err != nil {
		return nil, err
	}
	if _, err := p.expect(TOK_RPAREN); err != nil {
		return nil, err
	}

	thenBlock, err := p.parseBlock()
	if err != nil {
		return nil, err
	}

	node := &ASTNode{Type: NODE_IF, Children: []*ASTNode{cond, thenBlock}}

	for p.peekType() == TOK_ELIF {
		p.advance()
		if _, err := p.expect(TOK_LPAREN); err != nil {
			return nil, err
		}
		elifCond, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		if _, err := p.expect(TOK_RPAREN); err != nil {
			return nil, err
		}
		elifBlock, err := p.parseBlock()
		if err != nil {
			return nil, err
		}
		node.Children = append(node.Children, elifCond, elifBlock)
	}

	if p.peekType() == TOK_ELSE {
		p.advance()
		elseBlock, err := p.parseBlock()
		if err != nil {
			return nil, err
		}
		node.Children = append(node.Children, elseBlock)
	}

	return node, nil
}

func (p *Parser) parseFor() (*ASTNode, error) {
	p.advance() // consume 'for'

	if _, err := p.expect(TOK_LPAREN); err != nil {
		return nil, err
	}

	// Check if it's "for (k in expr)" or "for (k, v in expr)"
	// or C-style "for (init; cond; step)"

	// Try to parse the header
	tok1 := p.peek()

	// Save position for backtracking
	savedPos := p.pos

	// Try "for (var in expr)" pattern
	var keyVars []string
	for p.peekType() == TOK_IDENT || p.peekType() == TOK_VAR {
		if p.peekType() == TOK_VAR {
			p.advance()
		}
		nameTok := p.peek()
		if nameTok.Type != TOK_IDENT {
			break
		}
		p.advance()
		keyVars = append(keyVars, nameTok.StrVal)
		if p.peekType() == TOK_COMMA {
			p.advance()
		} else {
			break
		}
	}

	if p.peekType() == TOK_IN && len(keyVars) > 0 {
		p.advance() // consume 'in'
		iterExpr, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		if _, err := p.expect(TOK_RPAREN); err != nil {
			return nil, err
		}
		body, err := p.parseBlock()
		if err != nil {
			return nil, err
		}

		var nodeType NodeType
		if len(keyVars) == 1 {
			nodeType = NODE_FOR_KONLY
		} else {
			nodeType = NODE_FOR_KV
		}

		keyNodes := make([]*ASTNode, len(keyVars))
		for i, v := range keyVars {
			keyNodes[i] = &ASTNode{Type: NODE_LOCAL_VAR, StrVal: v}
		}
		children := append(keyNodes, iterExpr, body)
		return &ASTNode{Type: nodeType, Children: children}, nil
	}

	// Not a for-in loop, reset and try C-style or treat as error
	p.pos = savedPos
	_ = tok1

	// C-style for loop not supported - just parse as expression
	// Actually Miller doesn't have C-style for loops
	// The above should have worked; this is a parse error
	return nil, fmt.Errorf("mlr: unsupported for-loop syntax")
}

func (p *Parser) parseWhile() (*ASTNode, error) {
	p.advance() // consume 'while'

	if _, err := p.expect(TOK_LPAREN); err != nil {
		return nil, err
	}
	cond, err := p.parseExpr()
	if err != nil {
		return nil, err
	}
	if _, err := p.expect(TOK_RPAREN); err != nil {
		return nil, err
	}
	body, err := p.parseBlock()
	if err != nil {
		return nil, err
	}

	return newNode(NODE_WHILE, cond, body), nil
}

func (p *Parser) parseDoWhile() (*ASTNode, error) {
	p.advance() // consume 'do'
	body, err := p.parseBlock()
	if err != nil {
		return nil, err
	}

	if _, err := p.expect(TOK_WHILE); err != nil {
		return nil, err
	}
	if _, err := p.expect(TOK_LPAREN); err != nil {
		return nil, err
	}
	cond, err := p.parseExpr()
	if err != nil {
		return nil, err
	}
	if _, err := p.expect(TOK_RPAREN); err != nil {
		return nil, err
	}
	p.skipSemicolon()

	return newNode(NODE_DO_WHILE, body, cond), nil
}

func (p *Parser) parsePrint() (*ASTNode, error) {
	tok := p.advance()

	var nodeType NodeType
	switch tok.Type {
	case TOK_PRINT:
		nodeType = NODE_PRINT_STMT
	case TOK_PRINTN:
		nodeType = NODE_PRINTN_STMT
	case TOK_EPRINT:
		nodeType = NODE_EPRINT_STMT
	case TOK_EPRINTN:
		nodeType = NODE_EPRINTN_STMT
	}

	// Check for redirect
	var redirect *ASTNode
	var redirType string
	if p.peekType() == TOK_GT || p.peekType() == TOK_RSHIFT || p.peekType() == TOK_PIPE {
		redirType = p.peek().StrVal
		p.advance()
		r, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		redirect = r
	}

	node := &ASTNode{Type: nodeType, StrVal: redirType}

	if p.peekType() != TOK_SEMI && p.peekType() != TOK_RBRACE && p.peekType() != TOK_EOF {
		expr, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		node.Children = append(node.Children, expr)
	}

	if redirect != nil {
		node.Children = append(node.Children, redirect)
	}

	p.skipSemicolon()
	return node, nil
}

func (p *Parser) parseDump() (*ASTNode, error) {
	tok := p.advance()

	var nodeType NodeType
	if tok.Type == TOK_DUMP {
		nodeType = NODE_DUMP_STMT
	} else {
		nodeType = NODE_EDUMP_STMT
	}

	node := &ASTNode{Type: nodeType}

	// Check for redirect
	if p.peekType() == TOK_GT || p.peekType() == TOK_RSHIFT || p.peekType() == TOK_PIPE {
		node.StrVal = p.peek().StrVal
		p.advance()
		r, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		node.Children = append(node.Children, r)
	}

	p.skipSemicolon()
	return node, nil
}

func (p *Parser) parseEmit() (*ASTNode, error) {
	tok := p.advance()

	var nodeType NodeType
	switch tok.Type {
	case TOK_EMIT:
		nodeType = NODE_EMIT_STMT
	case TOK_EMIT1:
		nodeType = NODE_EMIT1_STMT
	case TOK_EMITF:
		nodeType = NODE_EMITF_STMT
	case TOK_EMITP:
		nodeType = NODE_EMITP_STMT
	}

	node := &ASTNode{Type: nodeType}

	// Check for redirect: emit >, emit >>, emit |
	if p.peekType() == TOK_GT || p.peekType() == TOK_RSHIFT || p.peekType() == TOK_PIPE {
		node.StrVal = p.peek().StrVal
		p.advance()
		r, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		node.Children = append(node.Children, r)
		if _, err := p.expect(TOK_COMMA); err != nil {
			return nil, err
		}
	}

	// Parse expressions
	expr, err := p.parseExpr()
	if err != nil {
		return nil, err
	}
	node.Children = append(node.Children, expr)

	// Optional additional index args
	for p.peekType() == TOK_COMMA {
		p.advance()
		arg, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		node.Children = append(node.Children, arg)
	}

	p.skipSemicolon()
	return node, nil
}

func (p *Parser) parseTee() (*ASTNode, error) {
	p.advance() // consume 'tee'

	node := &ASTNode{Type: NODE_TEE_STMT}

	if p.peekType() == TOK_GT || p.peekType() == TOK_RSHIFT || p.peekType() == TOK_PIPE {
		node.StrVal = p.peek().StrVal
		p.advance()
		r, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		node.Children = append(node.Children, r)
		p.advance() // skip comma
	}

	expr, err := p.parseExpr()
	if err != nil {
		return nil, err
	}
	node.Children = append(node.Children, expr)

	p.skipSemicolon()
	return node, nil
}

func (p *Parser) parseUnset() (*ASTNode, error) {
	p.advance() // consume 'unset'

	node := &ASTNode{Type: NODE_UNSET_STMT}

	if p.peekType() == TOK_ALL_SREC {
		p.advance()
		node.Children = append(node.Children, newNode(NODE_ALL_SREC))
	} else if p.peekType() == TOK_ALL_OOSVAR {
		p.advance()
		node.Children = append(node.Children, newNode(NODE_ALL_OOSVAR))
	} else {
		// Parse list of things to unset
		for {
			expr, err := p.parseLHS()
			if err != nil {
				return nil, err
			}
			node.Children = append(node.Children, expr)
			if p.peekType() != TOK_COMMA {
				break
			}
			p.advance()
		}
	}

	p.skipSemicolon()
	return node, nil
}

func (p *Parser) parseVarDecl() (*ASTNode, error) {
	tok := p.advance() // consume type keyword

	var declType string
	switch tok.Type {
	case TOK_VAR:
		declType = "var"
	case TOK_INT_TYPE:
		declType = "int"
	case TOK_FLOAT_TYPE:
		declType = "float"
	case TOK_STR_TYPE:
		declType = "str"
	case TOK_BOOL_TYPE:
		declType = "bool"
	case TOK_NUM_TYPE:
		declType = "num"
	case TOK_MAP_TYPE:
		declType = "map"
	}

	nameTok, err := p.expect(TOK_IDENT)
	if err != nil {
		return nil, err
	}

	node := &ASTNode{
		Type:    NODE_VAR_DECL,
		StrVal:  nameTok.StrVal,
		DeclType: declType,
	}

	if p.peekType() == TOK_ASSIGN {
		p.advance()
		expr, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		node.Children = append(node.Children, expr)
	}

	p.skipSemicolon()
	return node, nil
}

func (p *Parser) parseExprStatement() (*ASTNode, error) {
	// Parse an expression, which might be an assignment
	expr, err := p.parseExpr()
	if err != nil {
		return nil, err
	}
	p.skipSemicolon()
	return expr, nil
}

func (p *Parser) skipSemicolon() {
	for p.peekType() == TOK_SEMI {
		p.advance()
	}
}

// Expression parsing with precedence climbing
func (p *Parser) parseExpr() (*ASTNode, error) {
	return p.parseAssign()
}

func (p *Parser) parseAssign() (*ASTNode, error) {
	left, err := p.parseTernary()
	if err != nil {
		return nil, err
	}

	// Check for assignment operators
	switch p.peekType() {
	case TOK_ASSIGN, TOK_PLUS_ASSIGN, TOK_MINUS_ASSIGN, TOK_STAR_ASSIGN,
		TOK_SLASH_ASSIGN, TOK_DSTAR_ASSIGN, TOK_PERCENT_ASSIGN, TOK_DOT_ASSIGN,
		TOK_AMP_ASSIGN, TOK_PIPE_ASSIGN, TOK_CARET_ASSIGN,
		TOK_LSHIFT_ASSIGN, TOK_RSHIFT_ASSIGN, TOK_URSHIFT_ASSIGN:

		op := p.advance().StrVal
		right, err := p.parseAssign() // right-associative
		if err != nil {
			return nil, err
		}

		return &ASTNode{
			Type:     NODE_ASSIGN,
			Op:       op,
			Children: []*ASTNode{left, right},
		}, nil
	}

	return left, nil
}

func (p *Parser) parseTernary() (*ASTNode, error) {
	left, err := p.parseAbsentCoalesce()
	if err != nil {
		return nil, err
	}

	if p.peekType() == TOK_QUESTION {
		p.advance()
		thenExpr, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		if _, err := p.expect(TOK_COLON); err != nil {
			return nil, err
		}
		elseExpr, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		return newNode(NODE_TERNARY_OP, left, thenExpr, elseExpr), nil
	}

	return left, nil
}

func (p *Parser) parseAbsentCoalesce() (*ASTNode, error) {
	left, err := p.parseOr()
	if err != nil {
		return nil, err
	}

	for p.peekType() == TOK_DQ || p.peekType() == TOK_TQ {
		op := p.advance()
		right, err := p.parseOr()
		if err != nil {
			return nil, err
		}
		if op.Type == TOK_DQ {
			left = newNode(NODE_ABSENT_COALESCE, left, right)
		} else {
			left = newNode(NODE_EMPTY_COALESCE, left, right)
		}
	}

	return left, nil
}

func (p *Parser) parseOr() (*ASTNode, error) {
	left, err := p.parseXor()
	if err != nil {
		return nil, err
	}

	for p.peekType() == TOK_DPIPE {
		p.advance()
		right, err := p.parseXor()
		if err != nil {
			return nil, err
		}
		left = &ASTNode{Type: NODE_BINARY_OP, Op: "||", Children: []*ASTNode{left, right}}
	}

	return left, nil
}

func (p *Parser) parseXor() (*ASTNode, error) {
	left, err := p.parseAnd()
	if err != nil {
		return nil, err
	}

	for p.peekType() == TOK_DCARET {
		p.advance()
		right, err := p.parseAnd()
		if err != nil {
			return nil, err
		}
		left = &ASTNode{Type: NODE_BINARY_OP, Op: "^^", Children: []*ASTNode{left, right}}
	}

	return left, nil
}

func (p *Parser) parseAnd() (*ASTNode, error) {
	left, err := p.parseComparison()
	if err != nil {
		return nil, err
	}

	for p.peekType() == TOK_DAMP {
		p.advance()
		right, err := p.parseComparison()
		if err != nil {
			return nil, err
		}
		left = &ASTNode{Type: NODE_BINARY_OP, Op: "&&", Children: []*ASTNode{left, right}}
	}

	return left, nil
}

func (p *Parser) parseComparison() (*ASTNode, error) {
	left, err := p.parseBitor()
	if err != nil {
		return nil, err
	}

	for {
		var op string
		switch p.peekType() {
		case TOK_EQ:
			op = "=="
		case TOK_NEQ:
			op = "!="
		case TOK_LT:
			op = "<"
		case TOK_GT:
			op = ">"
		case TOK_LEQ:
			op = "<="
		case TOK_GEQ:
			op = ">="
		case TOK_SPACESHIP:
			op = "<=>"
		case TOK_MATCH:
			op = "=~"
		case TOK_NMATCH:
			op = "!=~"
		default:
			return left, nil
		}
		p.advance()
		right, err := p.parseBitor()
		if err != nil {
			return nil, err
		}
		left = &ASTNode{Type: NODE_BINARY_OP, Op: op, Children: []*ASTNode{left, right}}
	}
}

func (p *Parser) parseBitor() (*ASTNode, error) {
	left, err := p.parseBitxor()
	if err != nil {
		return nil, err
	}

	for p.peekType() == TOK_PIPE {
		p.advance()
		right, err := p.parseBitxor()
		if err != nil {
			return nil, err
		}
		left = &ASTNode{Type: NODE_BINARY_OP, Op: "|", Children: []*ASTNode{left, right}}
	}

	return left, nil
}

func (p *Parser) parseBitxor() (*ASTNode, error) {
	left, err := p.parseBitand()
	if err != nil {
		return nil, err
	}

	for p.peekType() == TOK_CARET {
		p.advance()
		right, err := p.parseBitand()
		if err != nil {
			return nil, err
		}
		left = &ASTNode{Type: NODE_BINARY_OP, Op: "^", Children: []*ASTNode{left, right}}
	}

	return left, nil
}

func (p *Parser) parseBitand() (*ASTNode, error) {
	left, err := p.parseShift()
	if err != nil {
		return nil, err
	}

	for p.peekType() == TOK_AMP {
		p.advance()
		right, err := p.parseShift()
		if err != nil {
			return nil, err
		}
		left = &ASTNode{Type: NODE_BINARY_OP, Op: "&", Children: []*ASTNode{left, right}}
	}

	return left, nil
}

func (p *Parser) parseShift() (*ASTNode, error) {
	left, err := p.parseAddSub()
	if err != nil {
		return nil, err
	}

	for p.peekType() == TOK_LSHIFT || p.peekType() == TOK_RSHIFT || p.peekType() == TOK_URSHIFT {
		op := p.advance().StrVal
		right, err := p.parseAddSub()
		if err != nil {
			return nil, err
		}
		left = &ASTNode{Type: NODE_BINARY_OP, Op: op, Children: []*ASTNode{left, right}}
	}

	return left, nil
}

func (p *Parser) parseAddSub() (*ASTNode, error) {
	left, err := p.parseMulDiv()
	if err != nil {
		return nil, err
	}

	for p.peekType() == TOK_PLUS || p.peekType() == TOK_MINUS || p.peekType() == TOK_DOT ||
		p.peekType() == TOK_DOTPLUS || p.peekType() == TOK_DOTMINUS {
		op := p.advance().StrVal
		right, err := p.parseMulDiv()
		if err != nil {
			return nil, err
		}
		left = &ASTNode{Type: NODE_BINARY_OP, Op: op, Children: []*ASTNode{left, right}}
	}

	return left, nil
}

func (p *Parser) parseMulDiv() (*ASTNode, error) {
	left, err := p.parseUnary()
	if err != nil {
		return nil, err
	}

	for p.peekType() == TOK_STAR || p.peekType() == TOK_SLASH || p.peekType() == TOK_PERCENT ||
		p.peekType() == TOK_DSLASH || p.peekType() == TOK_DOTSTAR || p.peekType() == TOK_DOTSLASH {
		op := p.advance().StrVal
		right, err := p.parseUnary()
		if err != nil {
			return nil, err
		}
		left = &ASTNode{Type: NODE_BINARY_OP, Op: op, Children: []*ASTNode{left, right}}
	}

	return left, nil
}

func (p *Parser) parseUnary() (*ASTNode, error) {
	switch p.peekType() {
	case TOK_BANG:
		p.advance()
		operand, err := p.parseUnary()
		if err != nil {
			return nil, err
		}
		return &ASTNode{Type: NODE_UNARY_OP, Op: "!", Children: []*ASTNode{operand}}, nil
	case TOK_TILDE:
		p.advance()
		operand, err := p.parseUnary()
		if err != nil {
			return nil, err
		}
		return &ASTNode{Type: NODE_UNARY_OP, Op: "~", Children: []*ASTNode{operand}}, nil
	case TOK_MINUS:
		p.advance()
		operand, err := p.parseUnary()
		if err != nil {
			return nil, err
		}
		return &ASTNode{Type: NODE_UNARY_OP, Op: "-", Children: []*ASTNode{operand}}, nil
	case TOK_PLUS:
		p.advance()
		return p.parseUnary()
	}

	return p.parsePower()
}

func (p *Parser) parsePower() (*ASTNode, error) {
	left, err := p.parsePostfix()
	if err != nil {
		return nil, err
	}

	if p.peekType() == TOK_DSTAR {
		p.advance()
		right, err := p.parseUnary() // right-associative
		if err != nil {
			return nil, err
		}
		return &ASTNode{Type: NODE_BINARY_OP, Op: "**", Children: []*ASTNode{left, right}}, nil
	}

	return left, nil
}

func (p *Parser) parsePostfix() (*ASTNode, error) {
	base, err := p.parsePrimary()
	if err != nil {
		return nil, err
	}

	// Handle indexing: expr[key]
	for p.peekType() == TOK_LBRACKET {
		p.advance()
		idx, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		if _, err := p.expect(TOK_RBRACKET); err != nil {
			return nil, err
		}
		base = &ASTNode{Type: NODE_INDEX, Children: []*ASTNode{base, idx}}
	}

	return base, nil
}

func (p *Parser) parsePrimary() (*ASTNode, error) {
	tok := p.peek()

	switch tok.Type {
	case TOK_INT:
		p.advance()
		// Parse integer
		var n int64
		var err error
		if strings.HasPrefix(tok.StrVal, "0x") || strings.HasPrefix(tok.StrVal, "0X") {
			n, err = strconv.ParseInt(tok.StrVal[2:], 16, 64)
		} else {
			n, err = strconv.ParseInt(tok.StrVal, 10, 64)
		}
		if err != nil {
			// Try as uint64
			u, err2 := strconv.ParseUint(tok.StrVal, 10, 64)
			if err2 != nil {
				return nil, fmt.Errorf("mlr: invalid integer literal: %s", tok.StrVal)
			}
			return &ASTNode{Type: NODE_INT_LIT, IntVal: int64(u)}, nil
		}
		return &ASTNode{Type: NODE_INT_LIT, IntVal: n}, nil

	case TOK_FLOAT:
		p.advance()
		f, err := strconv.ParseFloat(tok.StrVal, 64)
		if err != nil {
			return nil, fmt.Errorf("mlr: invalid float literal: %s", tok.StrVal)
		}
		return &ASTNode{Type: NODE_FLOAT_LIT, FltVal: f}, nil

	case TOK_STRING:
		p.advance()
		return &ASTNode{Type: NODE_STRING_LIT, StrVal: tok.StrVal}, nil

	case TOK_TRUE:
		p.advance()
		return &ASTNode{Type: NODE_BOOL_LIT, BoolVal: true}, nil
	case TOK_FALSE:
		p.advance()
		return &ASTNode{Type: NODE_BOOL_LIT, BoolVal: false}, nil
	case TOK_NULL_LIT:
		p.advance()
		return newNode(NODE_NULL_LIT), nil
	case TOK_INF:
		p.advance()
		return &ASTNode{Type: NODE_INF_LIT, BoolVal: true}, nil
	case TOK_NAN:
		p.advance()
		return newNode(NODE_NAN_LIT), nil

	case TOK_FIELD:
		p.advance()
		node := &ASTNode{Type: NODE_FIELD_REF, StrVal: tok.StrVal}
		// Handle indexed access: $name[key]
		for p.peekType() == TOK_LBRACKET {
			p.advance()
			idx, err := p.parseExpr()
			if err != nil {
				return nil, err
			}
			if _, err := p.expect(TOK_RBRACKET); err != nil {
				return nil, err
			}
			node = &ASTNode{Type: NODE_INDEX, Children: []*ASTNode{node, idx}}
		}
		return node, nil

	case TOK_FIELD_BRACED:
		p.advance()
		return &ASTNode{Type: NODE_FIELD_REF, StrVal: tok.StrVal}, nil

	case TOK_FIELD_IDX:
		p.advance() // consume $[
		idx, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		if _, err := p.expect(TOK_RBRACKET); err != nil {
			return nil, err
		}
		return &ASTNode{Type: NODE_FIELD_IDX, Children: []*ASTNode{idx}}, nil

	case TOK_ALL_SREC:
		p.advance()
		return newNode(NODE_ALL_SREC), nil

	case TOK_OOSVAR:
		p.advance()
		node := &ASTNode{Type: NODE_OOSVAR_REF, StrVal: tok.StrVal}
		// Handle indexed access: @name[key]
		for p.peekType() == TOK_LBRACKET {
			p.advance()
			idx, err := p.parseExpr()
			if err != nil {
				return nil, err
			}
			if _, err := p.expect(TOK_RBRACKET); err != nil {
				return nil, err
			}
			node = &ASTNode{Type: NODE_INDEX, Children: []*ASTNode{node, idx}}
		}
		return node, nil

	case TOK_OOSVAR_BRACED:
		p.advance()
		return &ASTNode{Type: NODE_OOSVAR_REF, StrVal: tok.StrVal}, nil

	case TOK_OOSVAR_IDX:
		p.advance() // consume @[
		idx, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		if _, err := p.expect(TOK_RBRACKET); err != nil {
			return nil, err
		}
		return &ASTNode{Type: NODE_OOSVAR_IDX, Children: []*ASTNode{idx}}, nil

	case TOK_ALL_OOSVAR:
		p.advance()
		return newNode(NODE_ALL_OOSVAR), nil

	case TOK_NR, TOK_FNR, TOK_NF, TOK_FILENAME, TOK_FILENUM,
		TOK_IFS_VAR, TOK_IPS_VAR, TOK_IRS_VAR,
		TOK_OFS_VAR, TOK_OPS_VAR, TOK_ORS_VAR, TOK_FLATSEP,
		TOK_M_PI, TOK_M_E:
		p.advance()
		return &ASTNode{Type: NODE_CONTEXT_VAR, StrVal: tok.StrVal}, nil

	case TOK_ENV:
		p.advance()
		// ENV["varname"] or ENV[expr]
		if _, err := p.expect(TOK_LBRACKET); err != nil {
			return nil, err
		}
		key, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		if _, err := p.expect(TOK_RBRACKET); err != nil {
			return nil, err
		}
		return &ASTNode{Type: NODE_ENV_REF, Children: []*ASTNode{key}}, nil

	case TOK_PANIC:
		p.advance()
		return newNode(NODE_PANIC), nil

	case TOK_STDOUT:
		p.advance()
		return &ASTNode{Type: NODE_CONTEXT_VAR, StrVal: "stdout"}, nil
	case TOK_STDERR:
		p.advance()
		return &ASTNode{Type: NODE_CONTEXT_VAR, StrVal: "stderr"}, nil

	case TOK_IDENT:
		// Could be a function call, local variable, or type error
		name := tok.StrVal
		p.advance()

		// Function call?
		if p.peekType() == TOK_LPAREN {
			p.advance()
			var args []*ASTNode
			for p.peekType() != TOK_RPAREN && p.peekType() != TOK_EOF {
				if len(args) > 0 {
					if _, err := p.expect(TOK_COMMA); err != nil {
						return nil, err
					}
				}
				// Handle func literal in argument
				if p.peekType() == TOK_FUNC || p.peekType() == TOK_FUNCT {
					p.advance()
					funcLit, err := p.parseFuncLiteral()
					if err != nil {
						return nil, err
					}
					args = append(args, funcLit)
				} else {
					arg, err := p.parseExpr()
					if err != nil {
						return nil, err
					}
					args = append(args, arg)
				}
			}
			if _, err := p.expect(TOK_RPAREN); err != nil {
				return nil, err
			}
			return &ASTNode{Type: NODE_FUNC_CALL, FuncName: name, Children: args}, nil
		}

		// Local variable reference
		return &ASTNode{Type: NODE_LOCAL_VAR, StrVal: name}, nil

	case TOK_LPAREN:
		p.advance()
		expr, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		if _, err := p.expect(TOK_RPAREN); err != nil {
			return nil, err
		}
		return expr, nil

	case TOK_LBRACKET:
		// Array literal
		p.advance()
		node := &ASTNode{Type: NODE_ARRAY_LIT}
		for p.peekType() != TOK_RBRACKET && p.peekType() != TOK_EOF {
			if len(node.Children) > 0 {
				if _, err := p.expect(TOK_COMMA); err != nil {
					return nil, err
				}
			}
			elem, err := p.parseExpr()
			if err != nil {
				return nil, err
			}
			node.Children = append(node.Children, elem)
		}
		if _, err := p.expect(TOK_RBRACKET); err != nil {
			return nil, err
		}
		return node, nil

	case TOK_LBRACE:
		// Map literal
		p.advance()
		node := &ASTNode{Type: NODE_MAP_LIT}
		for p.peekType() != TOK_RBRACE && p.peekType() != TOK_EOF {
			if len(node.Children) > 0 {
				if _, err := p.expect(TOK_COMMA); err != nil {
					return nil, err
				}
			}
			key, err := p.parseExpr()
			if err != nil {
				return nil, err
			}
			if _, err := p.expect(TOK_COLON); err != nil {
				return nil, err
			}
			val, err := p.parseExpr()
			if err != nil {
				return nil, err
			}
			node.Children = append(node.Children, &ASTNode{
				Type:     NODE_MAP_KV,
				Children: []*ASTNode{key, val},
			})
		}
		if _, err := p.expect(TOK_RBRACE); err != nil {
			return nil, err
		}
		return node, nil
	}

	return nil, fmt.Errorf("mlr: cannot parse DSL expression.\nmlr: Parse error on token %q at line %d column %d.\nExpected one of:\n  { ( field_name $[ braced_field_name $[[ $[[[ full_srec oosvar_name @[ braced_oosvar_name\n  full_oosvar all non_sigil_name float int + - .+ .- ! ~ string_literal regex_case_insensitive\n  int_literal float_literal boolean_literal null_literal inf_literal nan_literal\n  const_M_PI const_M_E panic [ ctx_IPS ctx_IFS ctx_IRS ctx_OPS ctx_OFS ctx_ORS\n  ctx_FLATSEP ctx_NF ctx_NR ctx_FNR ctx_FILENAME ctx_FILENUM env func\n",
		tok.StrVal, tok.Line, tok.Col)
}

func (p *Parser) parseFuncLiteral() (*ASTNode, error) {
	// func(params) { body }
	if _, err := p.expect(TOK_LPAREN); err != nil {
		return nil, err
	}

	var params []string
	for p.peekType() != TOK_RPAREN && p.peekType() != TOK_EOF {
		if len(params) > 0 {
			if _, err := p.expect(TOK_COMMA); err != nil {
				return nil, err
			}
		}
		paramTok, err := p.expect(TOK_IDENT)
		if err != nil {
			return nil, err
		}
		params = append(params, paramTok.StrVal)
	}

	if _, err := p.expect(TOK_RPAREN); err != nil {
		return nil, err
	}

	body, err := p.parseBlock()
	if err != nil {
		return nil, err
	}

	node := &ASTNode{
		Type:    NODE_FUNC_DEF,
		StrVal:  "__anon__",
		IntVal:  int64(len(params)),
		Children: []*ASTNode{body},
	}
	for _, param := range params {
		node.Children = append([]*ASTNode{{Type: NODE_LOCAL_VAR, StrVal: param}}, node.Children...)
	}

	return node, nil
}

// parseLHS parses an assignment left-hand side
func (p *Parser) parseLHS() (*ASTNode, error) {
	return p.parsePrimary()
}

