package main

import (
	"fmt"
	"math"
	"os"
	"strings"
)

// Execute runs the DSL program on a record and returns the last boolean value (for filter)
func (prog *DSLProgram) Execute(rec *Record, state *State) *MLRVal {
	if prog == nil {
		return MV_TRUE
	}

	// Execute main block
	if prog.mainBlock != nil {
		evalCtx := &EvalContext{
			rec:   rec,
			state: state,
			prog:  prog,
		}
		result := evalCtx.execBlock(prog.mainBlock)
		if result != nil {
			return result
		}
	}

	return MV_ABSENT
}

// Flush executes end blocks
func (prog *DSLProgram) Flush(state *State) []*Record {
	if prog == nil || prog.endBlock == nil {
		return nil
	}

	evalCtx := &EvalContext{
		rec:   NewRecord(),
		state: state,
		prog:  prog,
	}
	evalCtx.execBlock(prog.endBlock)

	return evalCtx.emitted
}

// ExecuteBegin runs begin blocks
func (prog *DSLProgram) ExecuteBegin(state *State) {
	if prog == nil || prog.beginBlock == nil {
		return
	}

	evalCtx := &EvalContext{
		rec:   NewRecord(),
		state: state,
		prog:  prog,
	}
	evalCtx.execBlock(prog.beginBlock)
}

// EvalContext holds execution state for DSL evaluation
type EvalContext struct {
	rec     *Record
	state   *State
	prog    *DSLProgram
	locals  map[string]*MLRVal
	emitted []*Record
	// Return value from return statement
	returnVal  *MLRVal
	hasReturn  bool
	breakFlag  bool
	continueFlag bool
}

func (ctx *EvalContext) pushLocals() map[string]*MLRVal {
	old := ctx.locals
	ctx.locals = make(map[string]*MLRVal)
	// Copy from parent
	for k, v := range old {
		ctx.locals[k] = v
	}
	return old
}

func (ctx *EvalContext) popLocals(old map[string]*MLRVal) {
	ctx.locals = old
}

func (ctx *EvalContext) getLocal(name string) *MLRVal {
	if ctx.locals != nil {
		if v, ok := ctx.locals[name]; ok {
			return v
		}
	}
	return MV_ABSENT
}

func (ctx *EvalContext) setLocal(name string, val *MLRVal) {
	if ctx.locals == nil {
		ctx.locals = make(map[string]*MLRVal)
	}
	ctx.locals[name] = val
}

// execBlock executes a block of statements, returns last bare boolean
func (ctx *EvalContext) execBlock(block *ASTNode) *MLRVal {
	var lastBool *MLRVal

	for _, stmt := range block.Children {
		result := ctx.execStmt(stmt)
		if ctx.hasReturn || ctx.breakFlag || ctx.continueFlag {
			return nil
		}
		if result != nil && (result.IsBool() || result.IsInt() || result.IsFloat()) {
			lastBool = result
		}
	}

	return lastBool
}

// execStmt executes a single statement
func (ctx *EvalContext) execStmt(node *ASTNode) *MLRVal {
	if node == nil {
		return nil
	}

	switch node.Type {
	case NODE_BLOCK:
		return ctx.execBlock(node)

	case NODE_ASSIGN:
		return ctx.execAssign(node)

	case NODE_IF:
		return ctx.execIf(node)

	case NODE_FOR_KONLY, NODE_FOR_KV:
		ctx.execFor(node)
		return nil

	case NODE_FOR_OOSVAR:
		ctx.execForOosvar(node)
		return nil

	case NODE_WHILE:
		ctx.execWhile(node)
		return nil

	case NODE_DO_WHILE:
		ctx.execDoWhile(node)
		return nil

	case NODE_BREAK:
		ctx.breakFlag = true
		return nil

	case NODE_CONTINUE:
		ctx.continueFlag = true
		return nil

	case NODE_RETURN:
		if len(node.Children) > 0 {
			ctx.returnVal = ctx.evalExpr(node.Children[0])
		} else {
			ctx.returnVal = MV_ABSENT
		}
		ctx.hasReturn = true
		return nil

	case NODE_PRINT_STMT, NODE_PRINTN_STMT, NODE_EPRINT_STMT, NODE_EPRINTN_STMT:
		return ctx.execPrint(node)

	case NODE_DUMP_STMT, NODE_EDUMP_STMT:
		return ctx.execDump(node)

	case NODE_EMIT_STMT, NODE_EMIT1_STMT, NODE_EMITF_STMT, NODE_EMITP_STMT:
		return ctx.execEmit(node)

	case NODE_TEE_STMT:
		return ctx.execTee(node)

	case NODE_UNSET_STMT:
		return ctx.execUnset(node)

	case NODE_FILTER_STMT:
		return ctx.evalExpr(node.Children[0])

	case NODE_VAR_DECL:
		return ctx.execVarDecl(node)

	case NODE_CALL_STMT:
		ctx.callSubr(node.FuncName, node.Children)
		return nil

	default:
		// Expression statement - evaluate and return
		return ctx.evalExpr(node)
	}
}

func (ctx *EvalContext) execAssign(node *ASTNode) *MLRVal {
	lhs := node.Children[0]
	rhs := node.Children[1]

	// Evaluate RHS
	var val *MLRVal
	op := node.Op

	if op == "=" {
		val = ctx.evalExpr(rhs)
	} else {
		// Compound assignment: get current value, apply op, store
		current := ctx.evalLHSGet(lhs)
		newVal := ctx.evalExpr(rhs)
		baseOp := strings.TrimSuffix(op, "=")
		val = ctx.applyBinaryOp(baseOp, current, newVal)
	}

	// Store value
	ctx.assignLHS(lhs, val)

	return nil
}

func (ctx *EvalContext) evalLHSGet(lhs *ASTNode) *MLRVal {
	switch lhs.Type {
	case NODE_FIELD_REF:
		return ctx.rec.Get(lhs.StrVal)
	case NODE_OOSVAR_REF:
		return ctx.state.OOSvars.Get(lhs.StrVal)
	case NODE_LOCAL_VAR:
		return ctx.getLocal(lhs.StrVal)
	case NODE_INDEX:
		container := ctx.evalExpr(lhs.Children[0])
		key := ctx.evalExpr(lhs.Children[1])
		return ctx.indexGet(container, key)
	}
	return MV_ABSENT
}

func (ctx *EvalContext) assignLHS(lhs *ASTNode, val *MLRVal) {
	switch lhs.Type {
	case NODE_FIELD_REF:
		if val.IsAbsent() {
			ctx.rec.Remove(lhs.StrVal)
		} else {
			ctx.rec.Put(lhs.StrVal, val)
		}

	case NODE_FIELD_IDX:
		// $[expr] = val
		key := ctx.evalExpr(lhs.Children[0])
		keyStr := key.String()
		if val.IsAbsent() {
			ctx.rec.Remove(keyStr)
		} else {
			ctx.rec.Put(keyStr, val)
		}

	case NODE_ALL_SREC:
		// $* = map
		if val.IsMap() {
			// Replace record contents
			for _, k := range ctx.rec.Keys() {
				ctx.rec.Remove(k)
			}
			for _, k := range val.MapVal.Keys() {
				ctx.rec.Put(k, val.MapVal.Get(k))
			}
		}

	case NODE_OOSVAR_REF:
		if val.IsAbsent() {
			ctx.state.OOSvars.Remove(lhs.StrVal)
		} else {
			ctx.state.OOSvars.Put(lhs.StrVal, val)
		}

	case NODE_OOSVAR_IDX:
		// @[expr] = val
		key := ctx.evalExpr(lhs.Children[0])
		keyStr := key.String()
		if val.IsAbsent() {
			ctx.state.OOSvars.Remove(keyStr)
		} else {
			ctx.state.OOSvars.Put(keyStr, val)
		}

	case NODE_LOCAL_VAR:
		ctx.setLocal(lhs.StrVal, val)

	case NODE_INDEX:
		// expr[key] = val - need to handle nested assignment
		container := ctx.evalExpr(lhs.Children[0])
		key := ctx.evalExpr(lhs.Children[1])
		ctx.indexSet(lhs.Children[0], container, key, val)
	}
}

func (ctx *EvalContext) indexSet(containerLHS *ASTNode, container *MLRVal, key, val *MLRVal) {
	keyStr := key.String()

	if container.IsMap() {
		if val.IsAbsent() {
			container.MapVal.Remove(keyStr)
		} else {
			container.MapVal.Put(keyStr, val)
		}
	} else if container.IsArray() {
		// Convert key to 1-based integer
		idx := toInt(key)
		if idx >= 1 && int(idx) <= len(container.ArrVal) {
			container.ArrVal[idx-1] = val
		} else if idx < 0 && int(-idx) <= len(container.ArrVal) {
			container.ArrVal[len(container.ArrVal)+int(idx)] = val
		}
	} else if container.IsAbsent() || container.IsNull() {
		// Create new map
		newMap := NewMlrmap()
		if !val.IsAbsent() {
			newMap.Put(keyStr, val)
		}
		newContainer := &MLRVal{Type: VT_MAP, MapVal: newMap}
		ctx.assignLHS(containerLHS, newContainer)
	} else {
		// String or other: can't index
	}
}

func toInt(v *MLRVal) int64 {
	switch v.Type {
	case VT_INT:
		return v.IntVal
	case VT_FLOAT:
		return int64(v.FltVal)
	case VT_STRING:
		n, err := parseInt64(v.StrVal)
		if err == nil {
			return n
		}
	}
	return 0
}

func (ctx *EvalContext) indexGet(container *MLRVal, key *MLRVal) *MLRVal {
	if container == nil || container.IsAbsent() || container.IsNull() {
		return MV_ABSENT
	}

	if container.IsMap() {
		keyStr := key.String()
		return container.MapVal.Get(keyStr)
	}

	if container.IsArray() {
		idx := toInt(key)
		arr := container.ArrVal
		if idx > 0 && int(idx) <= len(arr) {
			return arr[idx-1]
		}
		if idx < 0 && int(-idx) <= len(arr) {
			return arr[len(arr)+int(idx)]
		}
		return MV_ABSENT
	}

	if container.IsString() {
		// String indexing
		idx := toInt(key)
		runes := []rune(container.StrVal)
		if idx > 0 && int(idx) <= len(runes) {
			return MvFromString(string(runes[idx-1]))
		}
		if idx < 0 && int(-idx) <= len(runes) {
			return MvFromString(string(runes[len(runes)+int(idx)]))
		}
		return MV_ABSENT
	}

	return MV_ABSENT
}

func (ctx *EvalContext) execIf(node *ASTNode) *MLRVal {
	children := node.Children
	i := 0

	for i+1 < len(children) {
		cond := ctx.evalExpr(children[i])
		if isTruthy(cond) {
			return ctx.execBlock(children[i+1])
		}
		i += 2
	}

	// Else block
	if i < len(children) {
		return ctx.execBlock(children[i])
	}

	return nil
}

func isTruthy(v *MLRVal) bool {
	if v == nil {
		return false
	}
	switch v.Type {
	case VT_BOOL:
		return v.BoolVal
	case VT_INT:
		return v.IntVal != 0
	case VT_FLOAT:
		return v.FltVal != 0.0 && !math.IsNaN(v.FltVal)
	case VT_STRING:
		return v.StrVal != ""
	case VT_ABSENT, VT_NULL, VT_ERROR:
		return false
	case VT_ARRAY:
		return len(v.ArrVal) > 0
	case VT_MAP:
		return v.MapVal.Len() > 0
	}
	return false
}

func (ctx *EvalContext) execFor(node *ASTNode) {
	children := node.Children
	numKeys := int(node.IntVal)
	if numKeys == 0 {
		if node.Type == NODE_FOR_KV {
			numKeys = 2
		} else {
			numKeys = 1
		}
	}

	// For k[,v] in expr
	var keyVar, valVar string
	if node.Type == NODE_FOR_KONLY || numKeys == 1 {
		keyVar = children[0].StrVal
		valVar = ""
	} else {
		keyVar = children[0].StrVal
		valVar = children[1].StrVal
	}

	iterExprIdx := numKeys
	bodyIdx := numKeys + 1

	iterExpr := ctx.evalExpr(children[iterExprIdx])
	body := children[bodyIdx]

	savedLocals := ctx.pushLocals()

	if iterExpr.IsMap() {
		for _, k := range iterExpr.MapVal.Keys() {
			v := iterExpr.MapVal.Get(k)
			ctx.setLocal(keyVar, MvFromString(k))
			if valVar != "" {
				ctx.setLocal(valVar, v)
			}
			ctx.execBlock(body)
			if ctx.breakFlag {
				ctx.breakFlag = false
				break
			}
			ctx.continueFlag = false
		}
	} else if iterExpr.IsArray() {
		for i, v := range iterExpr.ArrVal {
			ctx.setLocal(keyVar, MvFromInt(int64(i+1)))
			if valVar != "" {
				ctx.setLocal(valVar, v)
			}
			ctx.execBlock(body)
			if ctx.breakFlag {
				ctx.breakFlag = false
				break
			}
			ctx.continueFlag = false
		}
	} else if iterExpr == ctx.rec || iterExpr.IsMap() {
		// $* iteration
	} else if node.Type == NODE_FOR_KONLY {
		// Iterate over record fields
		rec := ctx.rec
		for _, k := range rec.Keys() {
			ctx.setLocal(keyVar, MvFromString(k))
			ctx.execBlock(body)
			if ctx.breakFlag {
				ctx.breakFlag = false
				break
			}
			ctx.continueFlag = false
		}
	}

	ctx.popLocals(savedLocals)
}

func (ctx *EvalContext) execForOosvar(node *ASTNode) {
	// Same as execFor but for OOS vars
	ctx.execFor(node)
}

func (ctx *EvalContext) execWhile(node *ASTNode) {
	cond := node.Children[0]
	body := node.Children[1]

	for {
		condVal := ctx.evalExpr(cond)
		if !isTruthy(condVal) {
			break
		}
		ctx.execBlock(body)
		if ctx.breakFlag {
			ctx.breakFlag = false
			break
		}
		ctx.continueFlag = false
	}
}

func (ctx *EvalContext) execDoWhile(node *ASTNode) {
	body := node.Children[0]
	cond := node.Children[1]

	for {
		ctx.execBlock(body)
		if ctx.breakFlag {
			ctx.breakFlag = false
			break
		}
		ctx.continueFlag = false

		condVal := ctx.evalExpr(cond)
		if !isTruthy(condVal) {
			break
		}
	}
}

func (ctx *EvalContext) execPrint(node *ASTNode) *MLRVal {
	var sb strings.Builder

	// Find expression to print (first child that's not a redirect)
	children := node.Children
	exprIdx := 0

	// Check for redirect (last child might be redirect target)
	hasRedirect := node.StrVal != ""
	redirectTarget := ""
	var redirectExpr *ASTNode

	if hasRedirect && len(children) > 0 {
		redirectExpr = children[len(children)-1]
		children = children[:len(children)-1]
	}

	if len(children) > exprIdx {
		val := ctx.evalExpr(children[exprIdx])
		sb.WriteString(val.String())
	}

	var output *os.File
	if hasRedirect {
		redirVal := ctx.evalExpr(redirectExpr)
		redirectTarget = redirVal.String()
		if redirectTarget == "stderr" {
			output = os.Stderr
		} else if redirectTarget == "stdout" {
			output = os.Stdout
		} else {
			// File or pipe
			output = ctx.getOrOpenFile(redirectTarget, node.StrVal)
		}
	} else {
		if node.Type == NODE_EPRINT_STMT || node.Type == NODE_EPRINTN_STMT {
			output = os.Stderr
		} else {
			output = os.Stdout
		}
	}

	text := sb.String()
	if node.Type == NODE_PRINT_STMT || node.Type == NODE_EPRINT_STMT {
		fmt.Fprintln(output, text)
	} else {
		fmt.Fprint(output, text)
	}

	return nil
}

func (ctx *EvalContext) getOrOpenFile(path, mode string) *os.File {
	if f, ok := ctx.state.OpenFiles[path]; ok {
		return f
	}

	var flags int
	if mode == ">>" {
		flags = os.O_WRONLY | os.O_CREATE | os.O_APPEND
	} else if mode == "|" {
		// Pipe - not supported simply
		return os.Stdout
	} else {
		flags = os.O_WRONLY | os.O_CREATE | os.O_TRUNC
	}

	f, err := os.OpenFile(path, flags, 0644)
	if err != nil {
		fmt.Fprintf(os.Stderr, "mlr: cannot open file %s: %v\n", path, err)
		return os.Stdout
	}
	ctx.state.OpenFiles[path] = f
	return f
}

func (ctx *EvalContext) execDump(node *ASTNode) *MLRVal {
	// Dump OOS vars as JSON
	var output *os.File
	if node.Type == NODE_EDUMP_STMT {
		output = os.Stderr
	} else {
		output = os.Stdout
	}

	w := newJSONWriter(nil, ctx.state.Opts, false)
	_ = w

	// Simple JSON dump
	var sb strings.Builder
	sb.WriteString("{\n")
	keys := ctx.state.OOSvars.Keys()
	for i, k := range keys {
		v := ctx.state.OOSvars.Get(k)
		sb.WriteString("  ")
		sb.WriteString(jsonQuote(k))
		sb.WriteString(": ")
		sb.WriteString(v.jsonString())
		if i < len(keys)-1 {
			sb.WriteString(",")
		}
		sb.WriteString("\n")
	}
	sb.WriteString("}\n")
	fmt.Fprint(output, sb.String())

	return nil
}

func (ctx *EvalContext) execEmit(node *ASTNode) *MLRVal {
	children := node.Children

	if len(children) == 0 {
		return nil
	}

	// Find the value to emit
	var emitVal *MLRVal
	var indices []*MLRVal

	if node.Type == NODE_EMITF {
		// emitf: emit side-by-side
		rec := NewRecord()
		for _, child := range children {
			// Each child should be an oosvar ref or expr
			val := ctx.evalExpr(child)
			var key string
			if child.Type == NODE_OOSVAR_REF {
				key = child.StrVal
			} else {
				key = val.String()
			}
			if val.IsMap() {
				for _, k := range val.MapVal.Keys() {
					rec.Put(k, val.MapVal.Get(k))
				}
			} else {
				rec.Put(key, val)
			}
		}
		ctx.emitted = append(ctx.emitted, rec)
		return nil
	}

	if node.Type == NODE_EMIT1 {
		// emit1: emit the value directly
		emitVal = ctx.evalExpr(children[0])
	} else {
		// emit with possible indices
		startIdx := 0
		// Check for redirect
		if node.StrVal != "" {
			startIdx = 1
		}

		if startIdx < len(children) {
			emitVal = ctx.evalExpr(children[startIdx])
			for i := startIdx + 1; i < len(children); i++ {
				indices = append(indices, ctx.evalExpr(children[i]))
			}
		}
	}

	if emitVal == nil {
		return nil
	}

	// Emit the value
	if len(indices) == 0 {
		if emitVal.IsMap() {
			rec := NewRecord()
			for _, k := range emitVal.MapVal.Keys() {
				v := emitVal.MapVal.Get(k)
				if v.IsMap() {
					// Nested - emit flat
					for _, k2 := range v.MapVal.Keys() {
						rec.Put(k2, v.MapVal.Get(k2))
					}
				} else {
					rec.Put(k, v)
				}
			}
			ctx.emitted = append(ctx.emitted, rec)
		} else if emitVal.IsArray() {
			for i, v := range emitVal.ArrVal {
				rec := NewRecord()
				rec.Put(fmt.Sprintf("%d", i+1), v)
				ctx.emitted = append(ctx.emitted, rec)
			}
		} else {
			rec := NewRecord()
			rec.Put("value", emitVal)
			ctx.emitted = append(ctx.emitted, rec)
		}
	} else {
		// With indices - emit nested map entries
		ctx.emitWithIndices(emitVal, indices)
	}

	return nil
}

func (ctx *EvalContext) emitWithIndices(val *MLRVal, indices []*MLRVal) {
	if len(indices) == 0 {
		// Emit the current value
		if val.IsMap() {
			rec := NewRecord()
			for _, k := range val.MapVal.Keys() {
				rec.Put(k, val.MapVal.Get(k))
			}
			ctx.emitted = append(ctx.emitted, rec)
		}
		return
	}

	if !val.IsMap() {
		return
	}

	idx := indices[0]
	idxStr := idx.String()

	for _, k := range val.MapVal.Keys() {
		v := val.MapVal.Get(k)
		rec := NewRecord()
		rec.Put(idxStr, MvFromString(k))
		if len(indices) > 1 {
			// More indices
			if v.IsMap() {
				idx2 := indices[1]
				idx2Str := idx2.String()
				for _, k2 := range v.MapVal.Keys() {
					v2 := v.MapVal.Get(k2)
					rec2 := rec.Copy()
					rec2.Put(idx2Str, MvFromString(k2))
					if v2.IsMap() {
						for _, k3 := range v2.MapVal.Keys() {
							rec2.Put(k3, v2.MapVal.Get(k3))
						}
					} else {
						rec2.Put("value", v2)
					}
					ctx.emitted = append(ctx.emitted, rec2)
				}
			}
		} else {
			if v.IsMap() {
				for _, k2 := range v.MapVal.Keys() {
					rec.Put(k2, v.MapVal.Get(k2))
				}
			} else {
				rec.Put("value", v)
			}
			ctx.emitted = append(ctx.emitted, rec)
		}
	}
}

func (ctx *EvalContext) execTee(node *ASTNode) *MLRVal {
	// tee: output current record to a file
	// The current record is $*
	var output *os.File

	if node.StrVal != "" && len(node.Children) > 0 {
		r := ctx.evalExpr(node.Children[0])
		rStr := r.String()
		if rStr == "stderr" {
			output = os.Stderr
		} else {
			output = ctx.getOrOpenFile(rStr, node.StrVal)
		}
	} else {
		output = os.Stdout
	}

	// Write current record to output
	w := newDKVPWriter(nil, ctx.state.Opts)
	_ = w
	_ = output
	// TODO: proper writer

	return nil
}

func (ctx *EvalContext) execUnset(node *ASTNode) *MLRVal {
	for _, child := range node.Children {
		switch child.Type {
		case NODE_FIELD_REF:
			ctx.rec.Remove(child.StrVal)
		case NODE_ALL_SREC:
			for _, k := range ctx.rec.Keys() {
				ctx.rec.Remove(k)
			}
		case NODE_OOSVAR_REF:
			ctx.state.OOSvars.Remove(child.StrVal)
		case NODE_ALL_OOSVAR:
			for _, k := range ctx.state.OOSvars.Keys() {
				ctx.state.OOSvars.Remove(k)
			}
		case NODE_LOCAL_VAR:
			delete(ctx.locals, child.StrVal)
		case NODE_INDEX:
			container := ctx.evalExpr(child.Children[0])
			key := ctx.evalExpr(child.Children[1])
			if container.IsMap() {
				container.MapVal.Remove(key.String())
			}
		}
	}
	return nil
}

func (ctx *EvalContext) execVarDecl(node *ASTNode) *MLRVal {
	var val *MLRVal
	if len(node.Children) > 0 {
		val = ctx.evalExpr(node.Children[0])
	} else {
		val = MV_ABSENT
	}
	ctx.setLocal(node.StrVal, val)
	return nil
}

func (ctx *EvalContext) callSubr(name string, args []*ASTNode) {
	// Call a user-defined subroutine
	subrNode, ok := ctx.prog.subrs[name]
	if !ok {
		return
	}

	paramCount := int(subrNode.IntVal)
	bodyIdx := paramCount

	savedLocals := ctx.pushLocals()

	// Bind parameters
	for i := 0; i < paramCount && i < len(args); i++ {
		paramName := subrNode.Children[i].StrVal
		val := ctx.evalExpr(args[i])
		ctx.setLocal(paramName, val)
	}

	body := subrNode.Children[bodyIdx]
	ctx.execBlock(body)

	ctx.popLocals(savedLocals)
	ctx.hasReturn = false
}

// evalExpr evaluates an expression and returns its value
func (ctx *EvalContext) evalExpr(node *ASTNode) *MLRVal {
	if node == nil {
		return MV_ABSENT
	}

	switch node.Type {
	case NODE_INT_LIT:
		return MvFromInt(node.IntVal)
	case NODE_FLOAT_LIT:
		return MvFromFloat(node.FltVal)
	case NODE_STRING_LIT:
		return MvFromString(node.StrVal)
	case NODE_BOOL_LIT:
		return MvFromBool(node.BoolVal)
	case NODE_NULL_LIT:
		return MV_NULL
	case NODE_INF_LIT:
		if node.BoolVal {
			return MvFromFloat(math.Inf(1))
		}
		return MvFromFloat(math.Inf(-1))
	case NODE_NAN_LIT:
		return MvFromFloat(math.NaN())

	case NODE_FIELD_REF:
		return ctx.rec.Get(node.StrVal)

	case NODE_FIELD_IDX:
		key := ctx.evalExpr(node.Children[0])
		return ctx.rec.Get(key.String())

	case NODE_ALL_SREC:
		// Return the record as a map
		m := NewMlrmap()
		for _, k := range ctx.rec.Keys() {
			m.Put(k, ctx.rec.Get(k))
		}
		return &MLRVal{Type: VT_MAP, MapVal: m}

	case NODE_OOSVAR_REF:
		return ctx.state.OOSvars.Get(node.StrVal)

	case NODE_OOSVAR_IDX:
		key := ctx.evalExpr(node.Children[0])
		return ctx.state.OOSvars.Get(key.String())

	case NODE_ALL_OOSVAR:
		m := NewMlrmap()
		for _, k := range ctx.state.OOSvars.Keys() {
			m.Put(k, ctx.state.OOSvars.Get(k))
		}
		return &MLRVal{Type: VT_MAP, MapVal: m}

	case NODE_LOCAL_VAR:
		return ctx.getLocal(node.StrVal)

	case NODE_CONTEXT_VAR:
		return ctx.getContextVar(node.StrVal)

	case NODE_ENV_REF:
		key := ctx.evalExpr(node.Children[0])
		val := os.Getenv(key.String())
		return MvFromString(val)

	case NODE_INDEX:
		container := ctx.evalExpr(node.Children[0])
		key := ctx.evalExpr(node.Children[1])
		return ctx.indexGet(container, key)

	case NODE_BINARY_OP:
		left := ctx.evalExpr(node.Children[0])
		// Short-circuit for && and ||
		if node.Op == "&&" {
			if !isTruthy(left) {
				return MV_FALSE
			}
			right := ctx.evalExpr(node.Children[1])
			return MvFromBool(isTruthy(right))
		}
		if node.Op == "||" {
			if isTruthy(left) {
				return MV_TRUE
			}
			right := ctx.evalExpr(node.Children[1])
			return MvFromBool(isTruthy(right))
		}
		right := ctx.evalExpr(node.Children[1])
		return ctx.applyBinaryOp(node.Op, left, right)

	case NODE_UNARY_OP:
		operand := ctx.evalExpr(node.Children[0])
		return ctx.applyUnaryOp(node.Op, operand)

	case NODE_TERNARY_OP:
		cond := ctx.evalExpr(node.Children[0])
		if isTruthy(cond) {
			return ctx.evalExpr(node.Children[1])
		}
		return ctx.evalExpr(node.Children[2])

	case NODE_ABSENT_COALESCE:
		left := ctx.evalExpr(node.Children[0])
		if !left.IsAbsent() {
			return left
		}
		return ctx.evalExpr(node.Children[1])

	case NODE_EMPTY_COALESCE:
		left := ctx.evalExpr(node.Children[0])
		if !left.IsAbsent() && !left.IsNull() && !(left.IsString() && left.StrVal == "") {
			return left
		}
		return ctx.evalExpr(node.Children[1])

	case NODE_FUNC_CALL:
		return ctx.callFunc(node.FuncName, node.Children)

	case NODE_ARRAY_LIT:
		arr := make([]*MLRVal, len(node.Children))
		for i, child := range node.Children {
			arr[i] = ctx.evalExpr(child)
		}
		return &MLRVal{Type: VT_ARRAY, ArrVal: arr}

	case NODE_MAP_LIT:
		m := NewMlrmap()
		for _, kv := range node.Children {
			k := ctx.evalExpr(kv.Children[0])
			v := ctx.evalExpr(kv.Children[1])
			m.Put(k.String(), v)
		}
		return &MLRVal{Type: VT_MAP, MapVal: m}

	case NODE_ASSIGN:
		ctx.execAssign(node)
		return MV_ABSENT

	case NODE_PANIC:
		panic("mlr: explicit panic in DSL")

	case NODE_FUNC_DEF:
		// Anonymous function - return as a closure
		return &MLRVal{Type: VT_MAP, MapVal: func() *Mlrmap {
			m := NewMlrmap()
			m.Put("__func__", MvFromString(node.StrVal))
			return m
		}()}
	}

	return MV_ABSENT
}

func (ctx *EvalContext) getContextVar(name string) *MLRVal {
	switch name {
	case "NR":
		return MvFromInt(ctx.state.NR)
	case "FNR":
		return MvFromInt(ctx.state.FNR)
	case "NF":
		return MvFromInt(int64(ctx.rec.Len()))
	case "FILENAME":
		return MvFromString(ctx.state.Filename)
	case "FILENUM":
		return MvFromInt(ctx.state.Filenum)
	case "IFS":
		return MvFromString(ctx.state.Opts.IFS)
	case "IPS":
		return MvFromString(ctx.state.Opts.IPS)
	case "IRS":
		return MvFromString(ctx.state.Opts.IRS)
	case "OFS":
		return MvFromString(ctx.state.Opts.OFS)
	case "OPS":
		return MvFromString(ctx.state.Opts.OPS)
	case "ORS":
		return MvFromString(ctx.state.Opts.ORS)
	case "FLATSEP":
		return MvFromString(ctx.state.Opts.FlatSep)
	case "M_PI":
		return MvFromFloat(math.Pi)
	case "M_E":
		return MvFromFloat(math.E)
	case "stdout":
		return MvFromString("stdout")
	case "stderr":
		return MvFromString("stderr")
	}
	return MV_ABSENT
}

