func (ctx *EvalContext) applyBinaryOp(op string, left, right *MLRVal) *MLRVal {
	switch op {
	case "+":
		return mvAdd(left, right)
	case "-":
		return mvSub(left, right)
	case "*":
		return mvMul(left, right)
	case "/":
		return mvDiv(left, right)
	case "//":
		return mvIntDiv(left, right)
	case "%":
		return mvMod(left, right)
	case "**":
		return mvPow(left, right)
	case ".":
		return mvConcat(left, right)
	case ".+":
		return mvDotAdd(left, right)
	case ".-":
		return mvDotSub(left, right)
	case ".*":
		return mvDotMul(left, right)
	case "./":
		return mvDotDiv(left, right)
	case "==":
		return MvFromBool(mvEqual(left, right))
	case "!=":
		return MvFromBool(!mvEqual(left, right))
	case "<":
		return MvFromBool(mvCompare(left, right) < 0)
	case ">":
		return MvFromBool(mvCompare(left, right) > 0)
	case "<=":
		return MvFromBool(mvCompare(left, right) <= 0)
	case ">=":
		return MvFromBool(mvCompare(left, right) >= 0)
	case "<=>":
		return MvFromInt(int64(mvCompare(left, right)))
	case "=~":
		return MvFromBool(mvMatch(left, right))
	case "!=~":
		return MvFromBool(!mvMatch(left, right))
	case "&&":
		return MvFromBool(isTruthy(left) && isTruthy(right))
	case "||":
		return MvFromBool(isTruthy(left) || isTruthy(right))
	case "^^":
		return MvFromBool(isTruthy(left) != isTruthy(right))
	case "&":
		return mvBitAnd(left, right)
	case "|":
		return mvBitOr(left, right)
	case "^":
		return mvBitXor(left, right)
	case "<<":
		return mvLShift(left, right)
	case ">>":
		return mvRShift(left, right)
	case ">>>":
		return mvURShift(left, right)
	}
	return MV_ERROR
}

func (ctx *EvalContext) applyUnaryOp(op string, operand *MLRVal) *MLRVal {
	switch op {
	case "-":
		return mvNegate(operand)
	case "!":
		return MvFromBool(!isTruthy(operand))
	case "~":
		return mvBitNot(operand)
	}
	return MV_ERROR
}

// Arithmetic operations
func mvAdd(a, b *MLRVal) *MLRVal {
	if a.IsAbsent() {
		if b.IsAbsent() {
			return MV_ABSENT
		}
		return b
	}
	if b.IsAbsent() {
		return a
	}
	if a.IsNull() || b.IsNull() {
		if a.IsNull() && b.IsNull() {
			return MV_EMPTY
		}
		if a.IsNull() {
			return b
		}
		return a
	}
	if a.IsError() || b.IsError() {
		return MV_ERROR
	}
	if a.IsBool() || b.IsBool() {
		return MV_ERROR
	}
	if a.IsInt() && b.IsInt() {
		return MvFromInt(a.IntVal + b.IntVal)
	}
