// callFunc calls a built-in or user-defined function
func (ctx *EvalContext) callFunc(name string, argNodes []*ASTNode) *MLRVal {
	// Evaluate arguments
	args := make([]*MLRVal, len(argNodes))
	for i, an := range argNodes {
		args[i] = ctx.evalExpr(an)
	}

	// Check user-defined functions first
	if funcNode, ok := ctx.prog.funcs[name]; ok {
		return ctx.callUserFunc(funcNode, args, argNodes)
	}

	// Call built-in function
	return callBuiltin(name, args, ctx, argNodes)
}

func (ctx *EvalContext) callUserFunc(funcNode *ASTNode, args []*MLRVal, argNodes []*ASTNode) *MLRVal {
	paramCount := int(funcNode.IntVal)
	bodyIdx := paramCount

	savedLocals := ctx.pushLocals()

	// Bind parameters
	for i := 0; i < paramCount; i++ {
		paramName := funcNode.Children[i].StrVal
		if i < len(args) {
			ctx.setLocal(paramName, args[i])
		} else {
			ctx.setLocal(paramName, MV_ABSENT)
		}
	}

	body := funcNode.Children[bodyIdx]
	ctx.execBlock(body)

	var result *MLRVal
	if ctx.hasReturn {
		result = ctx.returnVal
		ctx.hasReturn = false
		ctx.returnVal = nil
	} else {
		result = MV_ABSENT
	}

	ctx.popLocals(savedLocals)
	return result
}
